INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23754, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "认可", "is_correct": true, "explanation": "“认可”表示妈妈接受并肯定我选的专业，与句意相符。"}, {"text": "解剖", "is_correct": false, "explanation": "语义：“解剖”指切开生物体进行研究，与对专业的态度毫无关系。"}, {"text": "砍伐", "is_correct": false, "explanation": "配价：“砍伐”要求以树木等作宾语，不能以专业作宾语。"}, {"text": "熨烫", "is_correct": false, "explanation": "语义：“熨烫”指用熨斗整理衣物，用来形容妈妈对专业的态度读不通。"}], "explanations": {"认可": "“认可”表示妈妈接受并肯定我选的专业，与句意相符。", "解剖": "语义：“解剖”指切开生物体进行研究，与对专业的态度毫无关系。", "砍伐": "配价：“砍伐”要求以树木等作宾语，不能以专业作宾语。", "熨烫": "语义：“熨烫”指用熨斗整理衣物，用来形容妈妈对专业的态度读不通。"}, "sentence_index": 0, "correct_answer": "认可"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我认可这个想法很糟糕，不值得再讨论。", "explanation": "这里应该用〈认为〉。认可表示觉得事情好、对而接受，不能与“很糟糕”这样的否定评价搭配。"}, {"text": "他在失物招领处认可了那只丢失的钱包是自己的，马上领了回去。", "explanation": "这里应该用〈认领〉。认可指觉得对而接受，认领失物要说认领。"}, {"text": "警察认可他是凶手，已经抓了他。", "explanation": "这里应该用〈认定〉。认可表示觉得对而接受，不用于认定某人是凶手这类负面结论。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a49d5b1-7f84-41de-86cb-4a1970ee0761') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23754, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "认可", "is_correct": true, "explanation": "“认可”指觉得这个计划好而接受，与“还不太”表示的保留态度相符。"}, {"text": "烘焙", "is_correct": false, "explanation": "配价：“烘焙”要求以食品作宾语，不能以计划作宾语。"}, {"text": "种植", "is_correct": false, "explanation": "语义：“种植”指栽种植物，与计划无关。"}, {"text": "烧制", "is_correct": false, "explanation": "语义：“烧制”指用火加工陶瓷、砖瓦等器物，不能用于计划。"}], "explanations": {"认可": "“认可”指觉得这个计划好而接受，与“还不太”表示的保留态度相符。", "烘焙": "配价：“烘焙”要求以食品作宾语，不能以计划作宾语。", "种植": "语义：“种植”指栽种植物，与计划无关。", "烧制": "语义：“烧制”指用火加工陶瓷、砖瓦等器物，不能用于计划。"}, "sentence_index": 6, "correct_answer": "认可"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她一进门就认可了老朋友的声音。", "explanation": "这里应该用〈听出〉。认可指觉得对而接受，辨认声音要说听出。"}, {"text": "这张旧照片让我认可了小时候住过的胡同。", "explanation": "这里应该用〈认出〉。认可指觉得对而接受，辨认地方要说认出。"}, {"text": "她在人群里一眼就认可了多年不见的同学。", "explanation": "这里应该用〈认出〉。认可指觉得对而接受，辨认人要说认出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a49d5b1-7f84-41de-86cb-4a1970ee0761') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23754, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我被认可他的建议。", "corrected_sentence": "我很认可他的建议。", "error_description": "“被”不能放在“认可”前表示“很认可”，应说“我很认可他的建议”；“被认可”需要被认可的事物作主语，如“我的建议被认可了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a49d5b1-7f84-41de-86cb-4a1970ee0761') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23754, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我还没认可了他的做法。", "corrected_sentence": "我还没认可过他的做法。", "error_description": "“没”否定有过的经历时要用“没……过”，应说“还没认可过他的做法”；“没”与“了”不能搭配。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a49d5b1-7f84-41de-86cb-4a1970ee0761') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
