INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23758, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "同侪的意思是一起学习或工作的人，就像同学或同事。", "primary_collocate": null, "pronunciation": "tóng chái", "ipa": "tʰʊŋ³⁵ ʈʂʰai³⁵", "syllable_count": 2, "sentences": [{"text": "我的同侪都在同一所学校学习。", "target_word": "同侪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他和同侪每天一起做实验。", "target_word": "同侪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让同侪互相检查作业。", "target_word": "同侪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在公司，同侪常常一起吃午饭。", "target_word": "同侪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她向同侪请教了这个问题。", "target_word": "同侪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同侪一起完成了这个项目。", "target_word": "同侪", "complexity_tier": "T3", "furigana": "tóng chái yì qǐ wán chéng le zhè ge xiàng mù.", "sentence_source": "generated"}, {"text": "开会前，他先和同侪商量了一下。", "target_word": "同侪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有一位很友好的同侪。", "target_word": "同侪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同侪之间应该互相帮助。", "target_word": "同侪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "毕业后，我和以前的同侪还有联系。", "target_word": "同侪", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "一起学习或工作的同学、同事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad6792c6-a92e-4e98-9b44-bbdd20737884') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23758, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "同侪", "is_correct": true, "explanation": "正确。“同侪”指一起学习或工作的人，与“在同一所学校学习”相符。"}, {"text": "乘客", "is_correct": false, "explanation": "语义：乘客指搭乘交通工具的人，不是一起学习的人，句子不通。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师指做饭的人，与“在同一所学校学习”无关，句子不通。"}, {"text": "同行", "is_correct": false, "explanation": "搭配：“同行”多指同一职业的人，与“在同一所学校学习”不搭配。"}], "explanations": {"同侪": "正确。“同侪”指一起学习或工作的人，与“在同一所学校学习”相符。", "乘客": "语义：乘客指搭乘交通工具的人，不是一起学习的人，句子不通。", "厨师": "语义：厨师指做饭的人，与“在同一所学校学习”无关，句子不通。", "同行": "搭配：“同行”多指同一职业的人，与“在同一所学校学习”不搭配。"}, "sentence_index": 0, "correct_answer": "同侪"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我认识一条同侪，我们常一起吃饭。", "explanation": "这里应该用〈位〉。同侪指人，“条”多用于长条形物体，不能用来量人。"}, {"text": "教室里坐着一张同侪。", "explanation": "这里应该用〈位〉。同侪指人，“张”多用于平面的物体，不能用来量人。"}, {"text": "他是我的一块同侪。", "explanation": "这里应该用〈位〉。同侪指人，“块”多用于块状物体，不能用来量人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a49d5b1-7f84-41de-86cb-4a1970ee0761') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23758, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "同侪", "is_correct": true, "explanation": "正确。“开会前，他先和同侪商量了一下”指会前与一起工作的人商量，与句意相符。"}, {"text": "影子", "is_correct": false, "explanation": "语义：影子不是人，无法与他“商量”，句子不通。"}, {"text": "路人", "is_correct": false, "explanation": "搭配：“商量”一般用于同事、同伴，路人与开会前的商量没有工作关系，不搭配。"}, {"text": "闹钟", "is_correct": false, "explanation": "语义：闹钟是物件，不能与他商量，句子不通。"}], "explanations": {"同侪": "正确。“开会前，他先和同侪商量了一下”指会前与一起工作的人商量，与句意相符。", "影子": "语义：影子不是人，无法与他“商量”，句子不通。", "路人": "搭配：“商量”一般用于同事、同伴，路人与开会前的商量没有工作关系，不搭配。", "闹钟": "语义：闹钟是物件，不能与他商量，句子不通。"}, "sentence_index": 6, "correct_answer": "同侪"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "同侪给我们发工资。", "explanation": "这里应该用〈老板〉。同侪指地位相近的人，没有给别人发工资的身份，应说“老板给我们发工资”。"}, {"text": "他正在喝同侪。", "explanation": "这里应该用〈咖啡〉。“喝”搭配饮品，同侪是人，不能被喝。"}, {"text": "他很孝顺同侪。", "explanation": "这里应该用〈父母〉。“孝顺”的对象是父母或长辈，不能用于同侪。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a49d5b1-7f84-41de-86cb-4a1970ee0761') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23758, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我有一只同侪很努力。", "corrected_sentence": "我有一位同侪很努力。", "error_description": "同侪指人，量词应用“位”，不能用“只”（“只”多用于动物或成对的物体）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a49d5b1-7f84-41de-86cb-4a1970ee0761') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23758, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "会议前，她先同侪讨论了一下。", "corrected_sentence": "会议前，她先和同侪讨论了一下。", "error_description": "“和同侪”表示与谁一起讨论，漏掉“和”后，“同侪”变成了句子主语，句子不通。应为“先和同侪讨论”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a49d5b1-7f84-41de-86cb-4a1970ee0761') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
