INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23768, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "物体沿光滑的表面平稳地朝某个方向移动。", "primary_collocate": null, "pronunciation": "huá xiàng", "ipa": "xua˧˥ ɕiaŋ˥˩", "syllable_count": 2, "sentences": [{"text": "小孩坐在滑梯上，慢慢滑向地面。", "target_word": "滑向", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雪橇滑向山脚，速度越来越快。", "target_word": "滑向", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冰球滑向球门，守门员没拦住。", "target_word": "滑向", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他脚下一滑，整个人滑向河边。", "target_word": "滑向", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小船静静地滑向岸边。", "target_word": "滑向", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "水珠从叶子上滑向地面。", "target_word": "滑向", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "滑雪的人从山顶滑向山谷。", "target_word": "滑向", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "手机从桌上滑向桌边，差点掉下去。", "target_word": "滑向", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "溜冰的女孩慢慢滑向场地中间。", "target_word": "滑向", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "月光下，天鹅滑向湖心。", "target_word": "滑向", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "滑向了", "label": "体标"}], "register": "中性", "sense_fingerprint": "滑向：动词，物体在光滑的表面上平稳地朝某个方向滑动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ca44288-1204-4ede-a46f-083eed1c9108') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23768, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "滑向", "is_correct": true, "explanation": "正确：滑向 huá xiàng，动词，物体在光滑表面上朝某方向滑动。"}, {"text": "画像", "is_correct": false, "explanation": "huà（第四声）与 huá（第二声）声调不同，意思是画中的形象。"}, {"text": "华夏", "is_correct": false, "explanation": "xià 与 xiàng 韵母不同（少了 -ng），意思是中国的古称。"}, {"text": "花香", "is_correct": false, "explanation": "声调混淆：huā xiāng 与 huá xiàng，两个音节声调均不同，意思是花的香气。"}], "explanations": {"滑向": "正确：滑向 huá xiàng，动词，物体在光滑表面上朝某方向滑动。", "画像": "huà（第四声）与 huá（第二声）声调不同，意思是画中的形象。", "华夏": "xià 与 xiàng 韵母不同（少了 -ng），意思是中国的古称。", "花香": "声调混淆：huā xiāng 与 huá xiàng，两个音节声调均不同，意思是花的香气。"}, "sentence_index": null, "correct_answer": "滑向"}, "level_3": {"options": [{"text": "滑向", "is_correct": true, "explanation": "正确：“滑向”表示物体平稳地朝某方向滑动，符合小孩坐在滑梯上的场景。"}, {"text": "扑向", "is_correct": false, "explanation": "搭配：“扑”指快速猛然地冲去，与“慢慢”搭配不当。"}, {"text": "跳向", "is_correct": false, "explanation": "语义：“跳”需要腾起的动作，坐在滑梯上的小孩无法跳向地面。"}, {"text": "冲向", "is_correct": false, "explanation": "语义：“冲”是迅猛地向前，与“慢慢”矛盾，小孩慢慢下滑时不能冲向地面。"}], "explanations": {"滑向": "正确：“滑向”表示物体平稳地朝某方向滑动，符合小孩坐在滑梯上的场景。", "扑向": "搭配：“扑”指快速猛然地冲去，与“慢慢”搭配不当。", "跳向": "语义：“跳”需要腾起的动作，坐在滑梯上的小孩无法跳向地面。", "冲向": "语义：“冲”是迅猛地向前，与“慢慢”矛盾，小孩慢慢下滑时不能冲向地面。"}, "sentence_index": 0, "correct_answer": "滑向"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一个箭步冲上前，滑向了楼梯口。", "explanation": "这里应该用〈冲向〉。滑向是平稳地移动，与“一个箭步冲上前”的急冲动作矛盾。"}, {"text": "这只狗突然滑向了小偷。", "explanation": "这里应该用〈扑向〉。滑向是平稳地滑动，不能描述狗猛地扑过去。"}, {"text": "他拔腿狂奔，滑向了河边。", "explanation": "这里应该用〈跑向〉。滑向是平稳地滑动，与“拔腿狂奔”的动作矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cb12e7d-639a-44ff-b76c-a02f91b41442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23768, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "滑向", "is_correct": true, "explanation": "正确：“滑向”表示沿着雪坡平稳地滑下，符合滑雪的动作。"}, {"text": "扔向", "is_correct": false, "explanation": "配价：“扔”需要一个被扔的东西作宾语，“滑雪的人扔向山谷”不成立。"}, {"text": "投向", "is_correct": false, "explanation": "配价：“投向”要有被投掷的宾语，此处缺少。"}, {"text": "挤向", "is_correct": false, "explanation": "语义：“挤”指在拥挤中硬往前钻，滑雪的人从山顶滑下并无挤的动作，句义不通。"}], "explanations": {"滑向": "正确：“滑向”表示沿着雪坡平稳地滑下，符合滑雪的动作。", "扔向": "配价：“扔”需要一个被扔的东西作宾语，“滑雪的人扔向山谷”不成立。", "投向": "配价：“投向”要有被投掷的宾语，此处缺少。", "挤向": "语义：“挤”指在拥挤中硬往前钻，滑雪的人从山顶滑下并无挤的动作，句义不通。"}, "sentence_index": 6, "correct_answer": "滑向"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小狗飞奔着滑向主人身边。", "explanation": "这里应该用〈奔向〉。滑向是平稳地滑动，与“飞奔”的快速奔跑不符。"}, {"text": "他一拳滑向对手。", "explanation": "“滑向”指平稳的滑动，不能描述挥拳打击的动作。"}, {"text": "他站在原地不动，却滑向了远方。", "explanation": "这里应该用〈望向〉。滑向是移动，与“站在原地不动”矛盾；看远方要用“望向”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cb12e7d-639a-44ff-b76c-a02f91b41442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23768, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把木箱慢慢滑向。", "corrected_sentence": "他把木箱慢慢滑向门口。", "error_description": "错误：“滑向”后面必须带出去向，此句缺少“门口”，句子不完整。正确应为“滑向门口”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cb12e7d-639a-44ff-b76c-a02f91b41442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23768, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "冰壶慢慢滑向到圆心。", "corrected_sentence": "冰壶慢慢滑向圆心。", "error_description": "错误：“滑向”已含方向义，其后不能再加“到”，构成“向”与“到”重复。正确应为“滑向圆心”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cb12e7d-639a-44ff-b76c-a02f91b41442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23772, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "好转", "is_correct": true, "explanation": "反义：“好转”指情况向好的方向发展，与“恶化”相反。"}, {"text": "增强", "is_correct": false, "explanation": "无关：“增强”指力量、程度变强，不构成与“恶化”相反的关系。"}, {"text": "停留", "is_correct": false, "explanation": "无关：“停留”指暂时停住，与“恶化”不构成反义。"}, {"text": "讨论", "is_correct": false, "explanation": "无关：“讨论”指交换意见，与“恶化”不构成反义。"}], "correct_answer": "好转", "explanations": {"好转": "反义：“好转”指情况向好的方向发展，与“恶化”相反。", "增强": "无关：“增强”指力量、程度变强，不构成与“恶化”相反的关系。", "停留": "无关：“停留”指暂时停住，与“恶化”不构成反义。", "讨论": "无关：“讨论”指交换意见，与“恶化”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cb12e7d-639a-44ff-b76c-a02f91b41442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23772, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "改善", "is_correct": true, "explanation": "反义：“改善”指情况变好，与“恶化”相反。"}, {"text": "增多", "is_correct": false, "explanation": "无关：“增多”指数量变大，不指情况的好坏变化，与“恶化”不构成反义。"}, {"text": "考虑", "is_correct": false, "explanation": "无关：“考虑”指思量，与“恶化”不构成反义。"}, {"text": "保护", "is_correct": false, "explanation": "无关：“保护”指使不受损害，与“恶化”不构成反义。"}], "correct_answer": "改善", "explanations": {"改善": "反义：“改善”指情况变好，与“恶化”相反。", "增多": "无关：“增多”指数量变大，不指情况的好坏变化，与“恶化”不构成反义。", "考虑": "无关：“考虑”指思量，与“恶化”不构成反义。", "保护": "无关：“保护”指使不受损害，与“恶化”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cb12e7d-639a-44ff-b76c-a02f91b41442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23772, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "事情变得不好，比如生病更重了。", "primary_collocate": null, "pronunciation": "è huà", "ipa": "ɤ˥˩ xua˥˩", "syllable_count": 2, "sentences": [{"text": "奶奶感冒后，病又恶化了。", "target_word": "恶化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生说，他的病没有恶化。", "target_word": "恶化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不吃药，病情一天天恶化。", "target_word": "恶化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "晚上雨下得更大，路况恶化了。", "target_word": "恶化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃了药以后，病情不再恶化。", "target_word": "恶化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈担心孩子的咳嗽会恶化。", "target_word": "恶化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的伤口没洗干净，所以恶化了。", "target_word": "恶化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病人的情况突然恶化，医生马上来了。", "target_word": "恶化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气恶化以后，我们回家了。", "target_word": "恶化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的眼病这两年恶化得很快。", "target_word": "恶化", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "恶化了", "label": "体标"}, {"form": "恶化过", "label": "体标"}], "register": "中性", "sense_fingerprint": "事情变坏，如病情加重", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ca44288-1204-4ede-a46f-083eed1c9108') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23772, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "修理", "is_correct": false, "explanation": "搭配：“修理”用于机器、物件，不能用于描述病的变化。"}, {"text": "恶化", "is_correct": true, "explanation": "正确：“恶化”指病情向更坏的方向发展，与“奶奶感冒后”“又”的语境相符。"}, {"text": "赚取", "is_correct": false, "explanation": "搭配：“赚取”的对象是钱或利润，不能说“病又赚取了”。"}, {"text": "治疗", "is_correct": false, "explanation": "语义：“治疗”指对病人进行医治的行为，不描述病的变化。"}], "explanations": {"修理": "搭配：“修理”用于机器、物件，不能用于描述病的变化。", "恶化": "正确：“恶化”指病情向更坏的方向发展，与“奶奶感冒后”“又”的语境相符。", "赚取": "搭配：“赚取”的对象是钱或利润，不能说“病又赚取了”。", "治疗": "语义：“治疗”指对病人进行医治的行为，不描述病的变化。"}, "sentence_index": 0, "correct_answer": "恶化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今年感冒的人数恶化了。", "explanation": "这里应该用〈增加〉。恶化用于情况变坏，人数的变化要用增加或减少。"}, {"text": "这场大雨恶化了我的新书。", "explanation": "这里应该用〈弄坏〉。恶化说情况、状态变坏，不用于具体物品被损坏，“书”要用弄坏或淋坏。"}, {"text": "这个孩子这几年的身高越来越恶化了。", "explanation": "这里应该用〈长高〉。恶化说情况变坏，身高的增长要用长高或增高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cb12e7d-639a-44ff-b76c-a02f91b41442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23772, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "愈合", "is_correct": false, "explanation": "语义：“愈合”指伤口长好，与“没洗干净，所以”的因果不相符。"}, {"text": "恶化", "is_correct": true, "explanation": "正确：“恶化”指伤口情况变坏，与“没洗干净”导致的结果相符。"}, {"text": "痊愈", "is_correct": false, "explanation": "语义：“痊愈”指彻底好了，与“没洗干净，所以”的因果不相符。"}, {"text": "缝合", "is_correct": false, "explanation": "配价：“缝合”需要施事去缝，伤口自己不会缝合。"}], "explanations": {"愈合": "语义：“愈合”指伤口长好，与“没洗干净，所以”的因果不相符。", "恶化": "正确：“恶化”指伤口情况变坏，与“没洗干净”导致的结果相符。", "痊愈": "语义：“痊愈”指彻底好了，与“没洗干净，所以”的因果不相符。", "缝合": "配价：“缝合”需要施事去缝，伤口自己不会缝合。"}, "sentence_index": 6, "correct_answer": "恶化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的责任这两年恶化了。", "explanation": "这里应该用〈加重〉。恶化说情况、局势变坏，责任的轻重要用加重或减轻。"}, {"text": "这块布的颜色恶化得很快。", "explanation": "这里应该用〈褪色〉。恶化说情况变坏，颜色变淡要用褪色。"}, {"text": "他的学历这两年恶化了。", "explanation": "这里应该用〈提高〉。恶化说情况变坏，学历是要提高的，不能说恶化。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cb12e7d-639a-44ff-b76c-a02f91b41442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23772, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的咳嗽很恶化了，医生很担心。", "corrected_sentence": "他的咳嗽恶化了，医生很担心。", "error_description": "错误在“很恶化了”：“很”不能修饰表示变化过程的动词“恶化”，去掉“很”即可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cb12e7d-639a-44ff-b76c-a02f91b41442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23772, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的眼病去年恶化了过，今年又加重了。", "corrected_sentence": "他的眼病去年恶化过，今年又加重了。", "error_description": "错误：“恶化了过”，正确：“恶化过”。表示经历过的体标“过”与完成的“了”不能同时用在同一动词上。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cb12e7d-639a-44ff-b76c-a02f91b41442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23776, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "隐性", "is_correct": true, "explanation": "隐性：与显性相对，指特征不容易被察觉。"}, {"text": "响亮", "is_correct": false, "explanation": "与“显性”无反义关系。响亮指声音大而清楚，与显性不构成相对的概念。"}, {"text": "柔软", "is_correct": false, "explanation": "与“显性”无反义关系。柔软指质地松软，与显性不构成相对的概念。"}, {"text": "冷淡", "is_correct": false, "explanation": "与“显性”无反义关系。冷淡指态度不热情，与显性不构成相对的概念。"}], "correct_answer": "隐性", "explanations": {"隐性": "隐性：与显性相对，指特征不容易被察觉。", "响亮": "与“显性”无反义关系。响亮指声音大而清楚，与显性不构成相对的概念。", "柔软": "与“显性”无反义关系。柔软指质地松软，与显性不构成相对的概念。", "冷淡": "与“显性”无反义关系。冷淡指态度不热情，与显性不构成相对的概念。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8ce0e32-1612-422e-a57e-9a90541b1d45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23776, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "隐性", "is_correct": true, "explanation": "隐性：与显性相对，指特征不容易被察觉。"}, {"text": "潮湿", "is_correct": false, "explanation": "与“显性”无反义关系。潮湿指含水分多，与显性不构成相对的概念。"}, {"text": "高大", "is_correct": false, "explanation": "与“显性”无反义关系。高大指体形或高度，与显性不构成相对的概念。"}, {"text": "辽阔", "is_correct": false, "explanation": "与“显性”无反义关系。辽阔指范围广大，与显性不构成相对的概念。"}], "correct_answer": "隐性", "explanations": {"隐性": "隐性：与显性相对，指特征不容易被察觉。", "潮湿": "与“显性”无反义关系。潮湿指含水分多，与显性不构成相对的概念。", "高大": "与“显性”无反义关系。高大指体形或高度，与显性不构成相对的概念。", "辽阔": "与“显性”无反义关系。辽阔指范围广大，与显性不构成相对的概念。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8ce0e32-1612-422e-a57e-9a90541b1d45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23776, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "显性就是很容易看见或知道的样子。", "primary_collocate": null, "pronunciation": "xiǎn xìng", "ipa": "ɕi̯ɛn˨˩ ɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他的进步是显性的，老师一眼就看到了。", "target_word": "显性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "显性的错误容易改，隐性的错误难找。", "target_word": "显性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的价格优势是显性的，一进门就能看到。", "target_word": "显性", "complexity_tier": "T3", "furigana": "xiǎn xìng", "sentence_source": "generated"}, {"text": "她的不高兴是显性的，大家都看得出来。", "target_word": "显性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司显性的问题已经解决了。", "target_word": "显性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "显性的好处你马上就能看到。", "target_word": "显性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种病有显性症状，很容易发现。", "target_word": "显性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先说显性的原因，再说隐性的原因。", "target_word": "显性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的变化不是显性的，别人没注意。", "target_word": "显性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "显性成本比隐性成本好算。", "target_word": "显性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "显性基因", "label": "复合"}, {"form": "显性成本", "label": "复合"}], "register": "书面", "sense_fingerprint": "摆在明处、很容易看见或知道的样子，与隐性相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b13cb17d-02c1-4f79-bcfd-22a8dcf8b695') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23776, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "显性", "is_correct": true, "explanation": "显性（xiǎn xìng）：摆在明处、很容易看见或知道的样子，与“隐性”相对。"}, {"text": "线性", "is_correct": false, "explanation": "线性（xiàn xìng）与显性的第一音节声调不同：xiàn 为第四声，xiǎn 为第三声。意思是呈直线关系。"}, {"text": "现行", "is_correct": false, "explanation": "现行（xiàn xíng）与显性的声调不同：第一音节 xiàn 为第四声，第二音节 xíng 为第二声。意思是当前正在实行的。"}, {"text": "显形", "is_correct": false, "explanation": "显形（xiǎn xíng）与显性的第二音节声调不同：xíng 为第二声，xìng 为第四声。意思是显露出原本的形状。"}, {"text": "限行", "is_correct": false, "explanation": "限行（xiàn xíng）与显性的两个音节声调都不同。意思是限制车辆或人员通行。"}], "explanations": {"显性": "显性（xiǎn xìng）：摆在明处、很容易看见或知道的样子，与“隐性”相对。", "线性": "线性（xiàn xìng）与显性的第一音节声调不同：xiàn 为第四声，xiǎn 为第三声。意思是呈直线关系。", "现行": "现行（xiàn xíng）与显性的声调不同：第一音节 xiàn 为第四声，第二音节 xíng 为第二声。意思是当前正在实行的。", "显形": "显形（xiǎn xíng）与显性的第二音节声调不同：xíng 为第二声，xìng 为第四声。意思是显露出原本的形状。", "限行": "限行（xiàn xíng）与显性的两个音节声调都不同。意思是限制车辆或人员通行。"}, "sentence_index": null, "correct_answer": "显性"}, "level_3": {"options": [{"text": "显性", "is_correct": true, "explanation": "显性：指进步容易被察觉，与“老师一眼就看到了”相合。"}, {"text": "隐性", "is_correct": false, "explanation": "语义：隐性指不容易察觉，与后句“老师一眼就看到了”矛盾。"}, {"text": "模糊", "is_correct": false, "explanation": "语义：模糊指看不清楚，与“一眼就看到了”矛盾。"}, {"text": "深奥", "is_correct": false, "explanation": "搭配：深奥多用来形容道理或学问，不用来修饰“进步”。"}], "explanations": {"显性": "显性：指进步容易被察觉，与“老师一眼就看到了”相合。", "隐性": "语义：隐性指不容易察觉，与后句“老师一眼就看到了”矛盾。", "模糊": "语义：模糊指看不清楚，与“一眼就看到了”矛盾。", "深奥": "搭配：深奥多用来形容道理或学问，不用来修饰“进步”。"}, "sentence_index": 0, "correct_answer": "显性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她的不高兴很显性，却一直藏在心里没说。", "explanation": "这里应该用〈隐秘〉。显性指很容易看见，“一直藏在心里没说”与之矛盾，应说“隐秘”。"}, {"text": "她一进门，心里的不高兴却很显性，谁都看不出来。", "explanation": "这里应该用〈隐蔽〉。显性指很容易看见，“谁都看不出来”与之矛盾，应说“隐蔽”。"}, {"text": "那棵老树很显性，走近了才能认出来。", "explanation": "这里应该用〈不起眼〉。显性指很容易看见，“走近了才能认出来”与之矛盾，应说“不起眼”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8ce0e32-1612-422e-a57e-9a90541b1d45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23776, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "显性", "is_correct": true, "explanation": "显性（xiǎn xìng）：摆在明处、很容易看见或知道的样子，与“隐性”相对。"}, {"text": "先行", "is_correct": false, "explanation": "先行（xiān xíng）与显性的第一音节声调不同：xiān 为第一声，xiǎn 为第三声。意思是事先走在前面。"}, {"text": "线形", "is_correct": false, "explanation": "线形（xiàn xíng）与显性的两个音节声调都不同。意思是线条的形状。"}, {"text": "线型", "is_correct": false, "explanation": "线型（xiàn xíng）与显性的两个音节声调都不同。意思是线条的类型或样式。"}, {"text": "现形", "is_correct": false, "explanation": "现形（xiàn xíng）与显性的两个音节声调都不同。意思是露出本来面目。"}], "explanations": {"显性": "显性（xiǎn xìng）：摆在明处、很容易看见或知道的样子，与“隐性”相对。", "先行": "先行（xiān xíng）与显性的第一音节声调不同：xiān 为第一声，xiǎn 为第三声。意思是事先走在前面。", "线形": "线形（xiàn xíng）与显性的两个音节声调都不同。意思是线条的形状。", "线型": "线型（xiàn xíng）与显性的两个音节声调都不同。意思是线条的类型或样式。", "现形": "现形（xiàn xíng）与显性的两个音节声调都不同。意思是露出本来面目。"}, "sentence_index": null, "correct_answer": "显性"}, "level_3": {"options": [{"text": "显性", "is_correct": true, "explanation": "显性：指症状容易察觉，与“很容易发现”相合。"}, {"text": "无形", "is_correct": false, "explanation": "语义：无形指看不见，与“很容易发现”矛盾。"}, {"text": "微妙", "is_correct": false, "explanation": "语义：微妙指细微难辨，与“很容易发现”矛盾。"}, {"text": "隐蔽", "is_correct": false, "explanation": "搭配：隐蔽多修饰行动或位置，一般不说“隐蔽症状”。"}], "explanations": {"显性": "显性：指症状容易察觉，与“很容易发现”相合。", "无形": "语义：无形指看不见，与“很容易发现”矛盾。", "微妙": "语义：微妙指细微难辨，与“很容易发现”矛盾。", "隐蔽": "搭配：隐蔽多修饰行动或位置，一般不说“隐蔽症状”。"}, "sentence_index": 6, "correct_answer": "显性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "豌豆的圆粒性状很显性，却总是看不出来。", "explanation": "这里应该用〈模糊〉。显性指很容易看见，“看不出来”与之矛盾，应说“模糊”。"}, {"text": "他的童年记忆很显性，却一点也想不起来。", "explanation": "这里应该用〈淡忘〉。显性指很容易知道，“一点也想不起来”与之矛盾，应说“淡忘”。"}, {"text": "学校的这门课很显性，却没人能说清教的是什么。", "explanation": "这里应该用〈不明确〉。显性指很容易知道，“没人能说清教的是什么”与之矛盾，应说“不明确”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8ce0e32-1612-422e-a57e-9a90541b1d45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23776, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个病的症状显性的，医生很快就判断出来了。", "corrected_sentence": "这个病的症状是显性的，医生很快就判断出来了。", "error_description": "“显性的”作表语前要用“是”。应说“是显性的”，不说“显性的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8ce0e32-1612-422e-a57e-9a90541b1d45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23776, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这项改变是显性地，大家一眼就能看到。", "corrected_sentence": "这项改变是显性的，大家一眼就能看到。", "error_description": "“显性”作表语时要用“的”，不用“地”（“地”用于修饰动词）。应说“是显性的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8ce0e32-1612-422e-a57e-9a90541b1d45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23778, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "粗劣", "is_correct": true, "explanation": "反义：“粗劣”指质量差，与“精良”相反。"}, {"text": "宽敞", "is_correct": false, "explanation": "无关：“宽敞”形容空间大，与“精良”不构成反义。"}, {"text": "灵活", "is_correct": false, "explanation": "无关：“灵活”指动作或思路敏捷，与“精良”不构成反义。"}, {"text": "明亮", "is_correct": false, "explanation": "无关：“明亮”形容光线充足或颜色亮，与“精良”不构成反义。"}], "correct_answer": "粗劣", "explanations": {"粗劣": "反义：“粗劣”指质量差，与“精良”相反。", "宽敞": "无关：“宽敞”形容空间大，与“精良”不构成反义。", "灵活": "无关：“灵活”指动作或思路敏捷，与“精良”不构成反义。", "明亮": "无关：“明亮”形容光线充足或颜色亮，与“精良”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cb12e7d-639a-44ff-b76c-a02f91b41442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
