INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23778, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "物品做得很好，质量高。", "primary_collocate": null, "pronunciation": "jīng liáng", "ipa": "tɕiŋ˥ liɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这双皮鞋做得精良，穿很多年也不坏。", "target_word": "精良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店卖的茶具都很精良。", "target_word": "精良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸送我一支做工精良的钢笔。", "target_word": "精良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆自行车质量精良，骑起来很稳。", "target_word": "精良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有一套精良的画笔。", "target_word": "精良", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些玩具造得很精良。", "target_word": "精良", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人们用精良的机器做衣服。", "target_word": "精良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书印得很精良，纸也好。", "target_word": "精良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的手表小而精良。", "target_word": "精良", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这把椅子看上去简单，做得却很精良。", "target_word": "精良", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "物品做得好、质量高", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ca44288-1204-4ede-a46f-083eed1c9108') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23778, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "粗劣", "is_correct": false, "explanation": "语义：“粗劣”指质量差，与后句“穿很多年也不坏”的评价相矛盾。"}, {"text": "精良", "is_correct": true, "explanation": "正确：“精良”指做得好、质量高，与“穿很多年也不坏”的评价相符。"}, {"text": "脆弱", "is_correct": false, "explanation": "语义：“脆弱”指容易损坏，与“穿很多年也不坏”相矛盾。"}, {"text": "不结实", "is_correct": false, "explanation": "语义：“不结实”指容易坏，与“穿很多年也不坏”相矛盾。"}], "explanations": {"粗劣": "语义：“粗劣”指质量差，与后句“穿很多年也不坏”的评价相矛盾。", "精良": "正确：“精良”指做得好、质量高，与“穿很多年也不坏”的评价相符。", "脆弱": "语义：“脆弱”指容易损坏，与“穿很多年也不坏”相矛盾。", "不结实": "语义：“不结实”指容易坏，与“穿很多年也不坏”相矛盾。"}, "sentence_index": 0, "correct_answer": "精良"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个孩子很精良。", "explanation": "这里应该用〈聪明〉。精良形容物品做得好，形容人的智力要用聪明。"}, {"text": "这条河的水很精良。", "explanation": "这里应该用〈清澈〉。精良形容物品的制作质量，水的透明程度要用清澈。"}, {"text": "今天的天气很精良。", "explanation": "这里应该用〈晴朗〉。精良只形容物品的做工和质量，天气要用晴朗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cb12e7d-639a-44ff-b76c-a02f91b41442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23778, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "透明", "is_correct": false, "explanation": "语义：“透明”形容质地或颜色，不用来说机器的质量，与“工人们用……做衣服”的语境不符。"}, {"text": "精良", "is_correct": true, "explanation": "正确：“精良”指机器质量好、做得细致，与“用……做衣服”的语境相符。"}, {"text": "柔软", "is_correct": false, "explanation": "搭配：“柔软”形容质地，不用来形容机器。"}, {"text": "苦涩", "is_correct": false, "explanation": "语义：“苦涩”形容味道，与“机器”不相关。"}], "explanations": {"透明": "语义：“透明”形容质地或颜色，不用来说机器的质量，与“工人们用……做衣服”的语境不符。", "精良": "正确：“精良”指机器质量好、做得细致，与“用……做衣服”的语境相符。", "柔软": "搭配：“柔软”形容质地，不用来形容机器。", "苦涩": "语义：“苦涩”形容味道，与“机器”不相关。"}, "sentence_index": 6, "correct_answer": "精良"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个店员很精良。", "explanation": "这里应该用〈热情〉。精良形容物品做得好，形容人的态度要用热情。"}, {"text": "这场雨下得很精良。", "explanation": "这里应该用〈大〉。精良只形容物品的做工和质量，雨势要用大或小。"}, {"text": "她的笑容很精良。", "explanation": "这里应该用〈甜美〉。精良只形容物品的做工和质量，笑容要用甜美或灿烂。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cb12e7d-639a-44ff-b76c-a02f91b41442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23778, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这套家具做很精良，用了很多年。", "corrected_sentence": "这套家具做得很精良，用了很多年。", "error_description": "错误：“做很精良”，正确：“做得很精良”。“做”后接表示程度的补语时，要用“得”连接。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cb12e7d-639a-44ff-b76c-a02f91b41442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23778, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这把剪刀的质量最很精良。", "corrected_sentence": "这把剪刀的质量最精良。", "error_description": "错误：“最很精良”，正确：“最精良”。“最”和“很”都表示程度，不能同时修饰同一个形容词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cb12e7d-639a-44ff-b76c-a02f91b41442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
