INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23782, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一个东西的各个部分是怎么连在一起的样子。", "primary_collocate": null, "pronunciation": "jià gòu", "ipa": "tɕja˥˩ kou˥˩", "syllable_count": 2, "sentences": [{"text": "这个网站的架构很简单。", "target_word": "架构", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我想了解这台机器的架构。", "target_word": "架构", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师用图给我们讲了电脑的架构。", "target_word": "架构", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座桥的架构很特别。", "target_word": "架构", "complexity_tier": "T3", "furigana": "zhè zuò qiáo de jià gòu hěn tè bié", "sentence_source": "generated"}, {"text": "看了这张图，我就明白了整个系统的架构。", "target_word": "架构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个软件的架构是上下两层。", "target_word": "架构", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想搞懂这座塔的架构。", "target_word": "架构", "complexity_tier": "T3", "furigana": "tā xiǎng gǎo dǒng zhè zuò tǎ de jià gòu", "sentence_source": "generated"}, {"text": "这个游戏的架构让新手也能看懂。", "target_word": "架构", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们把整个网络的架构画在纸上。", "target_word": "架构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书里讲过手机系统的架构。", "target_word": "架构", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "软件架构", "label": "复合"}, {"form": "网络架构", "label": "复合"}, {"form": "管理架构", "label": "复合"}], "register": "通用", "sense_fingerprint": "各部分之间相连的方式", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3c2bd5b-1259-421c-b750-220f4c66d70c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23782, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "架构", "is_correct": true, "explanation": "正确。“架构”指网站各部分的连接方式，可以用“很简单”来形容。"}, {"text": "身高", "is_correct": false, "explanation": "语义：网站没有身高，不能说“网站的身高很简单”。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：网站没有年龄可言，“年龄很简单”说不通。"}, {"text": "滋味", "is_correct": false, "explanation": "搭配：“滋味”指食物入口的感受，不能用来形容网站。"}], "explanations": {"架构": "正确。“架构”指网站各部分的连接方式，可以用“很简单”来形容。", "身高": "语义：网站没有身高，不能说“网站的身高很简单”。", "年龄": "语义：网站没有年龄可言，“年龄很简单”说不通。", "滋味": "搭配：“滋味”指食物入口的感受，不能用来形容网站。"}, "sentence_index": 0, "correct_answer": "架构"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种合金的架构很甜。", "explanation": "这里把“架构”误用于形容味道。“架构”只表示各部分的连接方式，不表示味道。"}, {"text": "这辆跑车的架构很高兴。", "explanation": "这里把“架构”误用于形容情绪。“架构”只表示各部分的连接方式，不表示情绪。"}, {"text": "老师给我们讲了一只架构。", "explanation": "这里量词用错。“架构”是抽象的连接方式，应该用〈个〉或〈种〉计量；“只”多用于动物，或成对物品中的一个。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62039189-ca3b-4dd6-a66b-4c86db4284d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23782, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "架构", "is_correct": true, "explanation": "正确。“架构”指塔各部分怎样连在一起，与“搞懂”和“塔”相符。"}, {"text": "心情", "is_correct": false, "explanation": "语义：塔没有心情，不能说“搞懂塔的心情”。"}, {"text": "嗓音", "is_correct": false, "explanation": "搭配：“嗓音”指人或动物的声音，不用来形容塔。"}, {"text": "性别", "is_correct": false, "explanation": "语义：塔没有性别，“性别”只用于人或动物。"}], "explanations": {"架构": "正确。“架构”指塔各部分怎样连在一起，与“搞懂”和“塔”相符。", "心情": "语义：塔没有心情，不能说“搞懂塔的心情”。", "嗓音": "搭配：“嗓音”指人或动物的声音，不用来形容塔。", "性别": "语义：塔没有性别，“性别”只用于人或动物。"}, "sentence_index": 6, "correct_answer": "架构"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这段时间的架构很红。", "explanation": "这里把“架构”误用于形容颜色。“架构”只表示各部分的连接方式，不表示颜色。"}, {"text": "这场聚会的架构很热闹。", "explanation": "这里把“架构”误用于形容场面的热闹。本词并不表示这一含义。"}, {"text": "这杯茶的架构很香。", "explanation": "这里把“架构”误用于描述茶的香气。本词并不表示气味。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62039189-ca3b-4dd6-a66b-4c86db4284d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23782, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只架构让机器更稳定。", "corrected_sentence": "这种架构让机器更稳定。", "error_description": "量词错误：“架构”应该用“种”计量；“只”多用于动物或成对物品中的一个，不能用来数“架构”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62039189-ca3b-4dd6-a66b-4c86db4284d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23782, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把这台小音箱的架构画很清楚。", "corrected_sentence": "他把这台小音箱的架构画得很清楚。", "error_description": "补语错误：“画”后表示结果的补语要用“得”连接，应说“画得很清楚”，不能省略“得”说“画很清楚”。错误出在描述“架构”的谓语上。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62039189-ca3b-4dd6-a66b-4c86db4284d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
