INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23786, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62039189-ca3b-4dd6-a66b-4c86db4284d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23786, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把一样东西弄坏，让它不再有用。", "primary_collocate": null, "pronunciation": "cuī huǐ", "ipa": "tsʰuei˥ xuei˨˩˦", "syllable_count": 2, "sentences": [{"text": "大风摧毁了院子里的棚子。", "target_word": "摧毁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一拳摧毁了那张旧桌子。", "target_word": "摧毁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子把沙子城堡摧毁了。", "target_word": "摧毁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洪水摧毁了路边的小桥。", "target_word": "摧毁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雷电摧毁了家里的电视。", "target_word": "摧毁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人用机器摧毁旧楼房。", "target_word": "摧毁", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "一场大雨摧毁了地里的菜。", "target_word": "摧毁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次事故摧毁了他的汽车。", "target_word": "摧毁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "虫子正摧毁着果园里的树。", "target_word": "摧毁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "狂风摧毁过这座木桥。", "target_word": "摧毁", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "摧毁了", "label": "体标"}, {"form": "摧毁过", "label": "体标"}, {"form": "摧毁着", "label": "体标"}, {"form": "摧毁性", "label": "复合"}], "register": "书面语", "sense_fingerprint": "把东西弄坏到不能再用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3c2bd5b-1259-421c-b750-220f4c66d70c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23786, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "修理", "is_correct": false, "explanation": "语义：“修理”是人为的修复，大风不会修理棚子，且与“摧毁”的结果相反。"}, {"text": "摧毁", "is_correct": true, "explanation": "“摧毁”指把东西弄坏到不能再用，与大风刮坏棚子的语境相合。"}, {"text": "搭建", "is_correct": false, "explanation": "语义：“搭建”是建起来，大风不能搭建棚子，与句意相反。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：“擦”多用于擦拭表面，不说擦棚子导致损坏。"}], "explanations": {"修理": "语义：“修理”是人为的修复，大风不会修理棚子，且与“摧毁”的结果相反。", "摧毁": "“摧毁”指把东西弄坏到不能再用，与大风刮坏棚子的语境相合。", "搭建": "语义：“搭建”是建起来，大风不能搭建棚子，与句意相反。", "擦": "搭配：“擦”多用于擦拭表面，不说擦棚子导致损坏。"}, "sentence_index": 0, "correct_answer": "摧毁"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他不小心把杯子摧毁了一个角。", "explanation": "这里应该用〈磕坏〉。“摧毁”指整体弄坏到不能再用，只磕坏一个角应说磕坏。"}, {"text": "他把玩具的漆皮摧毁了一块。", "explanation": "这里应该用〈刮掉〉。“摧毁”指整体弄坏到不再有用，只刮掉一小块漆皮，应说刮掉。"}, {"text": "台风摧毁了一些瓦片的边角。", "explanation": "这里应该用〈损坏〉。“摧毁”表示整体毁坏，只坏了边角应说损坏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62039189-ca3b-4dd6-a66b-4c86db4284d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23786, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "收割", "is_correct": false, "explanation": "语义：“收割”是人有计划地采收庄稼，大雨不会收割，与句意不符。"}, {"text": "栽种", "is_correct": false, "explanation": "语义：“栽种”是种下植物，与大雨毁坏菜地的语境相反。"}, {"text": "摧毁", "is_correct": true, "explanation": "“摧毁”指把东西弄坏到不能再用，与大雨毁坏菜的语境相合。"}, {"text": "宰杀", "is_correct": false, "explanation": "搭配：“宰杀”多用于牲畜，不说宰杀蔬菜。"}], "explanations": {"收割": "语义：“收割”是人有计划地采收庄稼，大雨不会收割，与句意不符。", "栽种": "语义：“栽种”是种下植物，与大雨毁坏菜地的语境相反。", "摧毁": "“摧毁”指把东西弄坏到不能再用，与大雨毁坏菜的语境相合。", "宰杀": "搭配：“宰杀”多用于牲畜，不说宰杀蔬菜。"}, "sentence_index": 6, "correct_answer": "摧毁"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那把旧椅子被大风摧毁了，但是还能正常坐。", "explanation": "“摧毁”表示彻底弄坏、再也不能用；此句说的是轻微损坏、仍能正常使用，与摧毁的意思相反。"}, {"text": "这件白衬衫被墨水摧毁了，洗一洗又干净如新。", "explanation": "“摧毁”表示彻底弄坏、再也不能用；此句说的是弄脏后洗干净即可恢复，与摧毁的意思相反。"}, {"text": "那张木桌被他一拳摧毁后，马上又被完整地拼了回去。", "explanation": "“摧毁”表示彻底弄坏、再也不能用；此句说的是打碎后又拼好，暂时破碎而非毁坏，与摧毁的意思相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62039189-ca3b-4dd6-a66b-4c86db4284d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23786, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "前天的大风把院子里的棚子摧毁。", "corrected_sentence": "前天的大风把院子里的棚子摧毁了。", "error_description": "错误：“把”字句中“摧毁”后缺少“了”。正确：“把……摧毁了”，“把”字句的动词后要带“了”等成分才完整。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62039189-ca3b-4dd6-a66b-4c86db4284d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23786, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雷电昨天已经把那台旧收音机摧毁着。", "corrected_sentence": "雷电昨天已经把那台旧收音机摧毁了。", "error_description": "错误：“摧毁着”表示动作正在进行，与“昨天”的已完成时间矛盾；已完成的动作应用“摧毁了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62039189-ca3b-4dd6-a66b-4c86db4284d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
