INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23792, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "敌意就是不喜欢别人，想伤害别人的感觉。", "primary_collocate": null, "pronunciation": "dí yì", "ipa": "ti˧˥ i˥˩", "syllable_count": 2, "sentences": [{"text": "他看着我，眼里全是敌意。", "target_word": "敌意", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新同学对我没有敌意，还帮了我。", "target_word": "敌意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗朝陌生人叫，是因为它有敌意。", "target_word": "敌意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你为什么对我这么有敌意？", "target_word": "敌意", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她说话很客气，但我听出了敌意。", "target_word": "敌意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个男孩见面时，都带着敌意。", "target_word": "敌意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想跟他做朋友，所以我没有敌意。", "target_word": "敌意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对新来的邻居有一点敌意。", "target_word": "敌意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的笑容里一点敌意也没有。", "target_word": "敌意", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家都感到了他的敌意。", "target_word": "敌意", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一丝敌意", "label": "量词"}], "register": "中性", "sense_fingerprint": "不喜欢别人、想伤害别人的感觉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ca44288-1204-4ede-a46f-083eed1c9108') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23792, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "湿度", "is_correct": false, "explanation": "搭配：“湿度”不与“眼里全是”搭配，说法不通。"}, {"text": "体积", "is_correct": false, "explanation": "语义：体积不是能充满眼睛的情绪或状态，“眼里全是体积”说不通。"}, {"text": "敌意", "is_correct": true, "explanation": "敌意指不喜欢别人、想伤害别人的感觉，“眼里全是”表示满眼的情绪，正好填入。"}, {"text": "重量", "is_correct": false, "explanation": "语义：重量不能用来描述“眼里全是”的内容，句子说不通。"}], "explanations": {"湿度": "搭配：“湿度”不与“眼里全是”搭配，说法不通。", "体积": "语义：体积不是能充满眼睛的情绪或状态，“眼里全是体积”说不通。", "敌意": "敌意指不喜欢别人、想伤害别人的感觉，“眼里全是”表示满眼的情绪，正好填入。", "重量": "语义：重量不能用来描述“眼里全是”的内容，句子说不通。"}, "sentence_index": 0, "correct_answer": "敌意"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是我公司的敌意，我们常在会上争论。", "explanation": "这里应该用〈对头〉。敌意是情绪，不能直接指人。"}, {"text": "他对我很有敌意，我们是一起长大的好朋友。", "explanation": "这里应该用〈好感〉。敌意指不喜欢别人、想伤害别人的感觉，与“一起长大的好朋友”相反；友好的感情要用好感。"}, {"text": "他的敌意很温暖，常常请我吃饭。", "explanation": "这里应该用〈善意〉。敌意指不喜欢别人、想伤害别人的感觉，与“温暖”“请我吃饭”相反；友好的心意要用善意。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cb12e7d-639a-44ff-b76c-a02f91b41442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23792, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "友谊", "is_correct": false, "explanation": "语义：“没有友谊”与“我想跟他做朋友”相矛盾。"}, {"text": "敌意", "is_correct": true, "explanation": "敌意指不喜欢别人、想伤害别人的感觉，与“我想跟他做朋友”形成对照，正好填入。"}, {"text": "钱包", "is_correct": false, "explanation": "语义：钱包与“做朋友”“没有……”的语境没有关联，句子说不通。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“没有体重”不成常用搭配，句子说不通。"}], "explanations": {"友谊": "语义：“没有友谊”与“我想跟他做朋友”相矛盾。", "敌意": "敌意指不喜欢别人、想伤害别人的感觉，与“我想跟他做朋友”形成对照，正好填入。", "钱包": "语义：钱包与“做朋友”“没有……”的语境没有关联，句子说不通。", "体重": "搭配：“没有体重”不成常用搭配，句子说不通。"}, "sentence_index": 6, "correct_answer": "敌意"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是我的敌意，我们从不说话。", "explanation": "这里应该用〈仇人〉。敌意是情绪，不能直接指人。"}, {"text": "她总是主动帮我，我非常感激她的敌意。", "explanation": "这里应该用〈帮助〉。敌意是不喜欢别人、想伤害别人的感觉，不能作为“感激”的对象；感谢的应是对方的帮助。"}, {"text": "他的敌意很温暖，常常借书给我。", "explanation": "这里应该用〈善意〉。敌意指不喜欢别人、想伤害别人的感觉，与“温暖”“借书给我”相反；友好的心意要用善意。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cb12e7d-639a-44ff-b76c-a02f91b41442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23792, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那种的敌意让我很难受。", "corrected_sentence": "那种敌意让我很难受。", "error_description": "错误在“的”：“那种”是指示词，后面直接接名词，不加“的”，应说“那种敌意”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cb12e7d-639a-44ff-b76c-a02f91b41442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23792, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他对我敌意，我很害怕。", "corrected_sentence": "他对我有敌意，我很害怕。", "error_description": "错误在“有”的省略：“敌意”是名词，“对……有敌意”中间需要动词“有”，漏掉后不成句。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cb12e7d-639a-44ff-b76c-a02f91b41442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
