INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23798, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "很难做或者很难学会的事情。", "primary_collocate": null, "pronunciation": "gāo nán dù", "ipa": "kɑʊ˥ nan˧˥ tu˥˩", "syllable_count": 3, "sentences": [{"text": "他喜欢挑战高难度。", "target_word": "高难度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高难度的事情，他都愿意试一试。", "target_word": "高难度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不怕高难度，只怕不努力。", "target_word": "高难度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师先教简单的，再教高难度。", "target_word": "高难度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天练习高难度，进步很快。", "target_word": "高难度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高难度的东西，要一步一步学。", "target_word": "高难度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他选了一门高难度的课。", "target_word": "高难度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她完成了一件高难度的工作。", "target_word": "高难度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项高难度的技术，只有他会。", "target_word": "高难度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别怕高难度，慢慢来。", "target_word": "高难度", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "很难做或很难学会的事情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3c2bd5b-1259-421c-b750-220f4c66d70c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23798, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "空气", "is_correct": false, "explanation": "搭配：“挑战”要的对象是困难或对手，不能说挑战“空气”。"}, {"text": "高难度", "is_correct": true, "explanation": "正确：“挑战高难度”指主动去做难度很大的事，与“他喜欢”搭配。"}, {"text": "旧鞋", "is_correct": false, "explanation": "语义：“旧鞋”不是困难，“挑战旧鞋”说不通，与“喜欢挑战”的语义不合。"}, {"text": "老底", "is_correct": false, "explanation": "语域：“老底”是口语，指底细或家底，与句子语气不合，也不能作“挑战”的对象。"}], "explanations": {"空气": "搭配：“挑战”要的对象是困难或对手，不能说挑战“空气”。", "高难度": "正确：“挑战高难度”指主动去做难度很大的事，与“他喜欢”搭配。", "旧鞋": "语义：“旧鞋”不是困难，“挑战旧鞋”说不通，与“喜欢挑战”的语义不合。", "老底": "语域：“老底”是口语，指底细或家底，与句子语气不合，也不能作“挑战”的对象。"}, "sentence_index": 0, "correct_answer": "高难度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈在菜市场买了三斤高难度。", "explanation": "这里应该用〈面粉〉。“高难度”是抽象概念，不能像面粉那样用“斤”称重买卖。"}, {"text": "他是班里的高难度，老师都不敢管他。", "explanation": "这里应该用〈刺头〉。“高难度”指事情本身难，不指人，用来说难管的人要用“刺头”。"}, {"text": "他陷入了高难度，一时走不出来。", "explanation": "这里应该用〈困境〉。“高难度”说的是事情本身很难，不能像“困境”那样被“陷入”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62039189-ca3b-4dd6-a66b-4c86db4284d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23798, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "葡萄", "is_correct": false, "explanation": "语义：“葡萄”是水果，“一门葡萄的课”说不通，与句意无关。"}, {"text": "高难度", "is_correct": true, "explanation": "正确：“一门高难度的课”指难度很大的课，与“他选了”的语境相符。"}, {"text": "圆形", "is_correct": false, "explanation": "语义：“圆形的课”说不通，课程没有形状，与“高难度”的语义无关。"}, {"text": "深红", "is_correct": false, "explanation": "体貌：“深红”是颜色，不能用来形容课程的外观或难度。"}], "explanations": {"葡萄": "语义：“葡萄”是水果，“一门葡萄的课”说不通，与句意无关。", "高难度": "正确：“一门高难度的课”指难度很大的课，与“他选了”的语境相符。", "圆形": "语义：“圆形的课”说不通，课程没有形状，与“高难度”的语义无关。", "深红": "体貌：“深红”是颜色，不能用来形容课程的外观或难度。"}, "sentence_index": 6, "correct_answer": "高难度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天早上都喝高难度，身体很好。", "explanation": "这里应该用〈饮料〉。“高难度”是抽象概念，不能当饮品来喝，说喝的东西要用“饮料”。"}, {"text": "这次高难度很好吃，大家都很开心。", "explanation": "“好吃”形容食物的味道，“高难度”指事情的难度，二者不能搭配，句子不通。"}, {"text": "这个房间的高难度是蓝色的。", "explanation": "这里应该用〈装修〉。“高难度”形容事情困难，不能用来描述房间的颜色，说房间的风格和颜色应该用“装修”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62039189-ca3b-4dd6-a66b-4c86db4284d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23798, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我喜欢挑战一根高难度，越难越有劲。", "corrected_sentence": "我喜欢挑战高难度，越难越有劲。", "error_description": "“高难度”是抽象名词，不能用“根”计量。应直接说“挑战高难度”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62039189-ca3b-4dd6-a66b-4c86db4284d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23798, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她挑了高难度地课，是为了让自己成长。", "corrected_sentence": "她挑了高难度的课，是为了让自己成长。", "error_description": "“高难度”修饰名词“课”时应用“的”，不能用“地”。应说“高难度的课”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62039189-ca3b-4dd6-a66b-4c86db4284d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
