INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23800, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一样的东西再做一个出来。", "primary_collocate": null, "pronunciation": "fù běn", "ipa": "fu˥˩ pən˨˩˦", "syllable_count": 2, "sentences": [{"text": "这幅画是原作的副本，不是真品。", "target_word": "副本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经理要我给这份报告做个副本。", "target_word": "副本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这张照片有三份副本，你拿一份吧。", "target_word": "副本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把这张地图的副本挂在墙上。", "target_word": "副本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份合同有正本和副本，我们各拿一份。", "target_word": "副本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把手机里的重要照片都做了一份副本。", "target_word": "副本", "complexity_tier": "T3", "furigana": "wǒ bǎ shǒu jī lǐ de zhòng yào zhào piàn dōu zuò le yí fèn fù běn.", "sentence_source": "generated"}, {"text": "复印店可以帮你打印这张表格的副本。", "target_word": "副本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座雕像只是副本，真的在博物馆里。", "target_word": "副本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请保存好收据的副本，退货时要用。", "target_word": "副本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这是画家自己画的副本，价格便宜些。", "target_word": "副本", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "份", "label": "量词"}, {"form": "电子副本", "label": "复合"}], "register": "中性", "sense_fingerprint": "副本：照原样再做出来的一份东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8034b76-f125-4129-9131-77cfab88eaca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23800, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "副本", "is_correct": true, "explanation": "正确。“副本”指照原作复制的画，与“原作”和“不是真品”的语境相符。"}, {"text": "作家", "is_correct": false, "explanation": "语义：原作是作品，不是人，“原作的作家”说不通。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“原作的”后不能接“价格”，句中说的是画的复制品。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机与画无关，“这幅画是原作的手机”不成立。"}], "explanations": {"副本": "正确。“副本”指照原作复制的画，与“原作”和“不是真品”的语境相符。", "作家": "语义：原作是作品，不是人，“原作的作家”说不通。", "价格": "搭配：“原作的”后不能接“价格”，句中说的是画的复制品。", "手机": "语义：手机与画无关，“这幅画是原作的手机”不成立。"}, "sentence_index": 0, "correct_answer": "副本"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "副本在悬崖边完成了动作，观众看得很紧张。", "explanation": "这里应该用〈替身〉。副本指复制件，代替演员完成危险动作的人要用替身。"}, {"text": "我订了一只副本，放在客厅里。", "explanation": "这里应该用〈份〉。副本计量用“份”，“只”不能用于副本。"}, {"text": "这种面包的副本只有面粉和水。", "explanation": "这里应该用〈原料〉。副本是复制件，不能说食物的副本只有面粉和水，构成食物的材料要用原料。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '386cdea5-bdf8-4a73-a55f-82328e64a0c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23800, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "副本", "is_correct": true, "explanation": "正确。“副本”指照原样复制的打印件或复印件，与“打印”相符。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子不能被打印，“打印椅子”说不通。"}, {"text": "咖啡", "is_correct": false, "explanation": "语义：咖啡是饮品，不能被打印出来。"}, {"text": "饭", "is_correct": false, "explanation": "配价：“打印”的对象须是可印刷的文件或图片，饭不能被打印。"}], "explanations": {"副本": "正确。“副本”指照原样复制的打印件或复印件，与“打印”相符。", "椅子": "语义：椅子不能被打印，“打印椅子”说不通。", "咖啡": "语义：咖啡是饮品，不能被打印出来。", "饭": "配价：“打印”的对象须是可印刷的文件或图片，饭不能被打印。"}, "sentence_index": 6, "correct_answer": "副本"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个部件坏了，要换一个新副本。", "explanation": "这里应该用〈零件〉。副本是复制件，坏了要换上的部件应称零件，不能说副本。"}, {"text": "我用复印机打印了一台副本。", "explanation": "这里应该用〈份〉。副本计量用“份”，“台”用于机器等大型器具，不用于印出来的文件。"}, {"text": "他在照相馆洗了一颗副本，给了妈妈。", "explanation": "这里应该用〈份〉。副本计量用“份”，“颗”用于粒状小物，不能用于洗出来的照片。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '386cdea5-bdf8-4a73-a55f-82328e64a0c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23800, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他给我做了一只副本，让我留着。", "corrected_sentence": "他给我做了一份副本，让我留着。", "error_description": "“副本”的量词应用“份”，不能用“只”。错误形式：一只副本；正确形式：一份副本。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '386cdea5-bdf8-4a73-a55f-82328e64a0c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23800, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把一只副本交给了我。", "corrected_sentence": "他把一份副本交给了我。", "error_description": "“副本”的量词应用“份”，不能用“只”。错误形式：一只副本；正确形式：一份副本。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '386cdea5-bdf8-4a73-a55f-82328e64a0c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
