INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23802, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "打败困难或拿下地方。", "primary_collocate": null, "pronunciation": "gōng kè", "ipa": "kʊŋ˥ kʰɤ˥˩", "syllable_count": 2, "sentences": [{"text": "军队三天就攻克了那座城市。", "target_word": "攻克", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们花了一年，攻克了这个难题。", "target_word": "攻克", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题太难，谁也没攻克过。", "target_word": "攻克", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要攻克学习中的每一个难关。", "target_word": "攻克", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "勇敢的战士攻克了敌人的城墙。", "target_word": "攻克", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师带着学生攻克数学难题。", "target_word": "攻克", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生们终于攻克了这种病。", "target_word": "攻克", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把最后一道难题攻克了。", "target_word": "攻克", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国王的军队攻克了山上的城堡。", "target_word": "攻克", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "团队日夜工作，想攻克技术问题。", "target_word": "攻克", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "攻克了", "label": "体标"}, {"form": "攻克过", "label": "体标"}], "register": "中性", "sense_fingerprint": "打败困难或拿下一个地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bf87788-5a50-449d-91ed-9ab27df85da9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23802, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "攻克", "is_correct": true, "explanation": "正确：指攻占城市，符合句意。"}, {"text": "旅游", "is_correct": false, "explanation": "语义：“旅游”指游览观光，不表示用兵攻占城市，与句意不符。"}, {"text": "装修", "is_correct": false, "explanation": "搭配：“装修”用于房屋、房间，不能说装修城市。"}, {"text": "逗留", "is_correct": false, "explanation": "配价：“逗留”是不及物动词，不能直接带“城市”作宾语。"}], "explanations": {"攻克": "正确：指攻占城市，符合句意。", "旅游": "语义：“旅游”指游览观光，不表示用兵攻占城市，与句意不符。", "装修": "搭配：“装修”用于房屋、房间，不能说装修城市。", "逗留": "配价：“逗留”是不及物动词，不能直接带“城市”作宾语。"}, "sentence_index": 0, "correct_answer": "攻克"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他攻克了一碗汤。", "explanation": "这里应该用〈喝〉。攻克指攻下难关或堡垒，喝汤要说喝，不能说攻克。"}, {"text": "他攻克了拥挤的人群。", "explanation": "这里应该用〈避开〉。攻克的对象是难关或堡垒，遇到拥挤的人群要避开。"}, {"text": "他攻克了一封来信。", "explanation": "这里应该用〈收到〉。攻克指攻下难关或堡垒，来信要说收到，不能说攻克。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5601a5e-75f0-4fff-8c6a-03e27937530d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23802, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "攻克", "is_correct": true, "explanation": "正确：指战胜疾病，符合句意。"}, {"text": "交流", "is_correct": false, "explanation": "搭配：“交流”的对象是经验、想法，不能说交流一种病。"}, {"text": "同意", "is_correct": false, "explanation": "搭配：“同意”带意见、请求等宾语，不能说同意这种病。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”用于美好的事物，疾病不能用来欣赏，句意不通。"}], "explanations": {"攻克": "正确：指战胜疾病，符合句意。", "交流": "搭配：“交流”的对象是经验、想法，不能说交流一种病。", "同意": "搭配：“同意”带意见、请求等宾语，不能说同意这种病。", "欣赏": "语义：“欣赏”用于美好的事物，疾病不能用来欣赏，句意不通。"}, "sentence_index": 6, "correct_answer": "攻克"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师攻克了学生的努力。", "explanation": "这里应该用〈赞美〉。攻克用于难关，努力是要被肯定的，称赞要用赞美。"}, {"text": "她攻克了老师的表扬。", "explanation": "这里应该用〈获得〉。表扬是别人给予的，要说获得，不能说攻克。"}, {"text": "他攻克了朋友的帮助。", "explanation": "这里应该用〈拒绝〉。帮助不是需要攻下的堡垒，不接受要用拒绝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5601a5e-75f0-4fff-8c6a-03e27937530d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23802, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那支部队攻克了一只堡垒。", "corrected_sentence": "那支部队攻克了一座堡垒。", "error_description": "量词错误：“堡垒”的量词应用“座”，不能用“只”（“只”通常用于动物等）。错误形式是“一只堡垒”，正确形式是“一座堡垒”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5601a5e-75f0-4fff-8c6a-03e27937530d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23802, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她正在攻克了那道数学难题。", "corrected_sentence": "她正在攻克那道数学难题。", "error_description": "“正在”表示动作进行中，不能与“了”同用；此处误加“了”。正确：她正在攻克那道数学难题。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5601a5e-75f0-4fff-8c6a-03e27937530d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
