INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23804, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "生命线是让人活着的最重要的东西。", "primary_collocate": null, "pronunciation": "shēng mìng xiàn", "ipa": "ʂɤŋ˥ miŋ˥˩ ɕi̯ɛn˥˩", "syllable_count": 3, "sentences": [{"text": "对重病的人来说，药就是生命线。", "target_word": "生命线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地震后，救援队送来的水是大家的生命线。", "target_word": "生命线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里的小路是村民的生命线。", "target_word": "生命线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "氧气管是病人的生命线。", "target_word": "生命线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对海上的人来说，淡水是生命线。", "target_word": "生命线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这点粮食是全家人的生命线。", "target_word": "生命线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他手里的绳子是唯一的生命线。", "target_word": "生命线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，输血是这位病人的生命线。", "target_word": "生命线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天，煤是山村人家的生命线。", "target_word": "生命线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "食物和水是灾区居民的生命线。", "target_word": "生命线", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一条生命线", "label": "量词（条）"}, {"form": "生命線", "label": "繁体"}], "register": "中性", "sense_fingerprint": "生命线：让人活下去的最重要的东西，如水、粮食、药", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8034b76-f125-4129-9131-77cfab88eaca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23804, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "宠物", "is_correct": false, "explanation": "语义：宠物是陪伴的动物，药不能充当宠物，与病人用药的语境不符。"}, {"text": "眼睛", "is_correct": false, "explanation": "体貌：眼睛是身体器官，药不能被比作眼睛。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：钢琴是乐器，“药就是钢琴”说不通。"}, {"text": "生命线", "is_correct": true, "explanation": "“生命线”指让重病的人活下去的最重要的东西，正符合“药”的作用。"}], "explanations": {"宠物": "语义：宠物是陪伴的动物，药不能充当宠物，与病人用药的语境不符。", "眼睛": "体貌：眼睛是身体器官，药不能被比作眼睛。", "钢琴": "语义：钢琴是乐器，“药就是钢琴”说不通。", "生命线": "“生命线”指让重病的人活下去的最重要的东西，正符合“药”的作用。"}, "sentence_index": 0, "correct_answer": "生命线"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他为了救孩子，差点丢了生命线。", "explanation": "这里应该用〈性命〉。“丢了”后接的是人的性命，“生命线”指维持生存的东西，不指性命本身。"}, {"text": "路口的生命线指向东方。", "explanation": "这里应该用〈路标〉。路标用来指示方向，“指向”是路标的作用；“生命线”不是标志物。"}, {"text": "这棵老树的生命线很顽强。", "explanation": "这里应该用〈生命力〉。“顽强”形容生命力，“生命线”不能用来形容树的顽强。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '386cdea5-bdf8-4a73-a55f-82328e64a0c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23804, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "乐器", "is_correct": false, "explanation": "语义：绳子不是乐器，“唯一的乐器”与手里的绳子无关。"}, {"text": "眉毛", "is_correct": false, "explanation": "体貌：眉毛是面部器官，绳子不能被比作眉毛。"}, {"text": "手表", "is_correct": false, "explanation": "语义：手表是计时工具，与“手里的绳子”指代的对象不符。"}, {"text": "生命线", "is_correct": true, "explanation": "“生命线”指关键时刻能救命的东西，与绳子在险境中的作用相符。"}], "explanations": {"乐器": "语义：绳子不是乐器，“唯一的乐器”与手里的绳子无关。", "眉毛": "体貌：眉毛是面部器官，绳子不能被比作眉毛。", "手表": "语义：手表是计时工具，与“手里的绳子”指代的对象不符。", "生命线": "“生命线”指关键时刻能救命的东西，与绳子在险境中的作用相符。"}, "sentence_index": 6, "correct_answer": "生命线"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这套房子的生命线可以达到五十年。", "explanation": "这里应该用〈寿命〉。“生命线”不指使用年限，说房子的使用年限要用〈寿命〉。"}, {"text": "这位医生用生命线挽救了一个孩子。", "explanation": "这里应该用〈生命〉。“用生命挽救”指以性命去救人，“生命线”不指性命本身。"}, {"text": "这幅水墨画的生命线很有力。", "explanation": "这里应该用〈线条〉。“有力”形容线条的笔力，“生命线”不指画中的线条。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '386cdea5-bdf8-4a73-a55f-82328e64a0c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23804, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这袋粮食是全家人的一只生命线。", "corrected_sentence": "这袋粮食是全家人的一条生命线。", "error_description": "量词错误：“生命线”的量词应为“条”，不能用“只”。错误形式为“一只生命线”，正确形式为“一条生命线”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '386cdea5-bdf8-4a73-a55f-82328e64a0c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23804, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这点水是生命线的我们家。", "corrected_sentence": "这点水是我们家的生命线。", "error_description": "语序错误：定语“我们家的”与“生命线”颠倒，应为“我们家的生命线”，不能说“生命线的我们家”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '386cdea5-bdf8-4a73-a55f-82328e64a0c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
