INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23816, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "治疗就是让生病的人好起来。", "primary_collocate": null, "pronunciation": "zhì liáo", "ipa": "ʈʂʐ̩˥˩ ljɑʊ̯˧˥", "syllable_count": 2, "sentences": [{"text": "医生正在治疗他的病。", "target_word": "治疗", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这种病要早点儿治疗。", "target_word": "治疗", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他在医院治疗了两个月。", "target_word": "治疗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生用药治疗我的感冒。", "target_word": "治疗", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这种病很难治疗。", "target_word": "治疗", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他的腿以前治疗过。", "target_word": "治疗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，必须马上治疗他的牙。", "target_word": "治疗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈带我去医院治疗眼睛。", "target_word": "治疗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生用新办法治疗病人。", "target_word": "治疗", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "生病了要去医院治疗。", "target_word": "治疗", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "治疗了", "label": "体标"}, {"form": "治疗过", "label": "体标"}, {"form": "治疗方案", "label": "复合"}], "register": "中性", "sense_fingerprint": "动词：用医疗办法让病人好起来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e55a90f-bee7-49d4-adc2-7ec13ce55273') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23816, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "治疗", "is_correct": true, "explanation": "正确。“治疗”指用医疗办法让病人好起来，与“医生”“病”搭配。"}, {"text": "制造", "is_correct": false, "explanation": "语义：“制造”指做出东西，病不能由医生制造出来，句子不通。"}, {"text": "购买", "is_correct": false, "explanation": "搭配：“购买”的对象是商品，“病”不能被购买。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”用于清理场所或物品，不能用于“病”。"}], "explanations": {"治疗": "正确。“治疗”指用医疗办法让病人好起来，与“医生”“病”搭配。", "制造": "语义：“制造”指做出东西，病不能由医生制造出来，句子不通。", "购买": "搭配：“购买”的对象是商品，“病”不能被购买。", "打扫": "搭配：“打扫”用于清理场所或物品，不能用于“病”。"}, "sentence_index": 0, "correct_answer": "治疗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衣服很难治疗。", "explanation": "这里应该用〈洗〉。“治疗”针对病痛，衣服脏了要说“洗”。"}, {"text": "我的自行车坏了，得去治疗。", "explanation": "这里应该用〈修理〉。“治疗”针对人或动物的病，机器坏了要说“修理”。"}, {"text": "老师治疗了这道题。", "explanation": "这里应该用〈解释〉。“治疗”的对象是病人，讲题要用“解释”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25231ecd-b38e-4013-b8b0-2f67ce0365af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23816, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "治疗", "is_correct": true, "explanation": "正确。“治疗”的对象是病，牙病要说“治疗”。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”用于衣服、鞋帽，不能用于“牙”。"}, {"text": "感谢", "is_correct": false, "explanation": "语义：“感谢”的对象必须是人，牙不能被感谢，句子不通。"}, {"text": "欢迎", "is_correct": false, "explanation": "搭配：“欢迎”的对象是人，不能用于“牙”。"}], "explanations": {"治疗": "正确。“治疗”的对象是病，牙病要说“治疗”。", "穿": "搭配：“穿”用于衣服、鞋帽，不能用于“牙”。", "感谢": "语义：“感谢”的对象必须是人，牙不能被感谢，句子不通。", "欢迎": "搭配：“欢迎”的对象是人，不能用于“牙”。"}, "sentence_index": 6, "correct_answer": "治疗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们要治疗城市的垃圾。", "explanation": "这里应该用〈清理〉。“治疗”针对病痛，垃圾要说“清理”。"}, {"text": "这件事你该怎么治疗？", "explanation": "这里应该用〈处理〉。“治疗”用于疾病，事情要说“处理”。"}, {"text": "工人正在治疗街道。", "explanation": "这里应该用〈清扫〉。“治疗”的对象是人或动物的病，街道要说“清扫”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25231ecd-b38e-4013-b8b0-2f67ce0365af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23816, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "医生终于把他的腿治疗了好。", "corrected_sentence": "医生终于把他的腿治疗好了。", "error_description": "结果补语“好”应紧跟动词，“了”放在句末。正确的说法是“治疗好了”，不是“治疗了好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25231ecd-b38e-4013-b8b0-2f67ce0365af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23816, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他去年治疗了过一次。", "corrected_sentence": "他去年治疗过一次。", "error_description": "“了”与“过”不能同时用在动词后表示经历，应去掉“了”。正确的说法是“他去年治疗过一次”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25231ecd-b38e-4013-b8b0-2f67ce0365af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23818, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "输入", "is_correct": true, "explanation": "输入：把信息送进设备，与“输出”构成反义关系。"}, {"text": "观看", "is_correct": false, "explanation": "观看：仔细地看，与“输出”没有反义关系。"}, {"text": "讲解", "is_correct": false, "explanation": "讲解：说明道理或内容，与“输出”没有反义关系。"}, {"text": "购买", "is_correct": false, "explanation": "购买：花钱买进，与“输出”没有反义关系。"}], "correct_answer": "输入", "explanations": {"输入": "输入：把信息送进设备，与“输出”构成反义关系。", "观看": "观看：仔细地看，与“输出”没有反义关系。", "讲解": "讲解：说明道理或内容，与“输出”没有反义关系。", "购买": "购买：花钱买进，与“输出”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce4fd29c-2289-4e96-96ae-fe634b805df6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23818, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "输入", "is_correct": true, "explanation": "输入：把数据送入设备，与“输出”构成反义关系。"}, {"text": "储存", "is_correct": false, "explanation": "储存：把数据保存起来，与“输出”没有反义关系。"}, {"text": "打开", "is_correct": false, "explanation": "打开：使开放或启动，与“输出”没有反义关系。"}, {"text": "排列", "is_correct": false, "explanation": "排列：按一定次序摆放，与“输出”没有反义关系。"}], "correct_answer": "输入", "explanations": {"输入": "输入：把数据送入设备，与“输出”构成反义关系。", "储存": "储存：把数据保存起来，与“输出”没有反义关系。", "打开": "打开：使开放或启动，与“输出”没有反义关系。", "排列": "排列：按一定次序摆放，与“输出”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce4fd29c-2289-4e96-96ae-fe634b805df6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23818, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "电脑把东西展示出来。", "primary_collocate": null, "pronunciation": "shū chū", "ipa": "ʂu˥ tʂʰu˥", "syllable_count": 2, "sentences": [{"text": "电脑可以把结果输出到屏幕上。", "target_word": "输出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台电脑正在输出图像。", "target_word": "输出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个视频有问题，电脑输出不了。", "target_word": "输出", "complexity_tier": "T3", "furigana": "zhè ge shìpín yǒu wèntí, diànnǎo shūchū bù liǎo", "sentence_source": "generated"}, {"text": "电脑没有输出任何文字。", "target_word": "输出", "complexity_tier": "T3", "furigana": "diànnǎo méiyǒu shūchū rènhé wénzì", "sentence_source": "generated"}, {"text": "电脑输出的结果和我想的一样。", "target_word": "输出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让电脑输出了一张地图。", "target_word": "输出", "complexity_tier": "T3", "furigana": "lǎoshī ràng diànnǎo shūchū le yì zhāng dìtú", "sentence_source": "generated"}, {"text": "他按了一下键，电脑马上输出了答案。", "target_word": "输出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电脑为什么不输出画面呢？", "target_word": "输出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机连着电视，可以把照片输出到电视上。", "target_word": "输出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "程序运行完以后，电脑会输出一张表。", "target_word": "输出", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "输出了", "label": "体标"}], "register": "中性", "sense_fingerprint": "电脑等设备把处理的结果显示、传送出来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7caa9dc1-b16c-4823-8c0d-d506d16883a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23818, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "输出", "is_correct": true, "explanation": "正确：“输出”指把结果显示或传送出来，与“到屏幕上”搭配。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”的对象是液体，不能把结果“喝”到屏幕上。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指发出歌声，与“结果”“屏幕”的语境不符，句子说不通。"}, {"text": "制造", "is_correct": false, "explanation": "搭配：“制造”后接产品、问题，不说“制造到屏幕上”，搭配不通。"}], "explanations": {"输出": "正确：“输出”指把结果显示或传送出来，与“到屏幕上”搭配。", "喝": "语义：“喝”的对象是液体，不能把结果“喝”到屏幕上。", "唱": "语义：“唱”指发出歌声，与“结果”“屏幕”的语境不符，句子说不通。", "制造": "搭配：“制造”后接产品、问题，不说“制造到屏幕上”，搭配不通。"}, "sentence_index": 0, "correct_answer": "输出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在键盘上输出了一段文字。", "explanation": "这里应该用〈输入〉。键盘是输入设备，把文字送进电脑要用输入，输出是从电脑向外送出。"}, {"text": "我们把剩下的饭输出完了。", "explanation": "这里应该用〈吃〉。输出表示电脑把东西展示或送出，与吃饭无关；吃完饭要说吃，不能说输出。"}, {"text": "他把照片输出了电脑。", "explanation": "这里应该用〈导入〉。输出是从电脑送出，把照片送进电脑要用导入。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce4fd29c-2289-4e96-96ae-fe634b805df6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23818, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "输出", "is_correct": true, "explanation": "正确：“输出”指电脑把答案显示出来，与“电脑马上”和“答案”搭配自然。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”的对象是食物，不能说“吃了答案”。"}, {"text": "打碎", "is_correct": false, "explanation": "语义：“打碎”针对器物，答案无法被打碎，句子说不通。"}, {"text": "进行", "is_correct": false, "explanation": "配价：“进行”后要接动作性名词，不能直接带宾语“答案”。"}], "explanations": {"输出": "正确：“输出”指电脑把答案显示出来，与“电脑马上”和“答案”搭配自然。", "吃": "语义：“吃”的对象是食物，不能说“吃了答案”。", "打碎": "语义：“打碎”针对器物，答案无法被打碎，句子说不通。", "进行": "配价：“进行”后要接动作性名词，不能直接带宾语“答案”。"}, "sentence_index": 6, "correct_answer": "输出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学生把作业输出给了老师。", "explanation": "这里应该用〈交〉。输出用于数据、结果的显示或传送，不用于把作业交给别人。"}, {"text": "他在超市里输出了一瓶酱油。", "explanation": "这里应该用〈买〉。“输出”指电脑把结果展示或传送出来，买东西要用“买”。"}, {"text": "他一个月输出了三千块钱。", "explanation": "这里应该用〈挣〉。输出不表示获得收入，挣钱要用挣。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce4fd29c-2289-4e96-96ae-fe634b805df6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23818, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "电脑可以把视频输出投影仪上。", "corrected_sentence": "电脑可以把视频输出到投影仪上。", "error_description": "错误：“输出”后缺少引出去处的介词“到”。“把……输出到……”结构中，“到”引出输出的目的地，不能省略。正确应为“把视频输出到投影仪上”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce4fd29c-2289-4e96-96ae-fe634b805df6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23818, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台打印机输出地很清楚。", "corrected_sentence": "这台打印机输出得很清楚。", "error_description": "错误：“输出”后的程度补语要用结构助词“得”连接，“地”用于修饰动词，不能用于补语。正确应为“输出得很清楚”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce4fd29c-2289-4e96-96ae-fe634b805df6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
