INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23820, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "坦克是一种有履带、有铁壳、能打仗的车。", "primary_collocate": null, "pronunciation": "tǎn kè", "ipa": "tʰan˨˩ kʰɤ˥˩", "syllable_count": 2, "sentences": [{"text": "那辆坦克很大，也很重。", "target_word": "坦克", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷年轻时在部队开过坦克。", "target_word": "坦克", "complexity_tier": "T3", "furigana": "yé ye nián qīng shí zài bù duì kāi guo tǎn kè", "sentence_source": "generated"}, {"text": "电影里的坦克把墙撞倒了。", "target_word": "坦克", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坦克的铁壳又厚又硬。", "target_word": "坦克", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上开来了三辆坦克。", "target_word": "坦克", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坦克一开，地面都在震动。", "target_word": "坦克", "complexity_tier": "T3", "furigana": "tǎn kè yì kāi, dì miàn dōu zài zhèn dòng", "sentence_source": "generated"}, {"text": "老兵给孩子讲坦克的故事。", "target_word": "坦克", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军队的坦克停在山下。", "target_word": "坦克", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们看着坦克慢慢开走。", "target_word": "坦克", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在军事展上看到了真的坦克。", "target_word": "坦克", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "辆", "label": "量词"}, {"form": "坦克兵", "label": "复合词"}, {"form": "坦克部队", "label": "复合词"}], "register": "中性", "sense_fingerprint": "坦克：有铁壳、能打仗的大车", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8034b76-f125-4129-9131-77cfab88eaca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23820, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自行车", "is_correct": false, "explanation": "体貌：自行车体形小、很轻，不能说“很大，也很重”。"}, {"text": "滑板车", "is_correct": false, "explanation": "体貌：滑板车体形小、很轻，不符合“很大，也很重”的描述。"}, {"text": "坦克", "is_correct": true, "explanation": "“坦克”是有铁壳的大型军用车辆，符合“很大，也很重”。"}, {"text": "童车", "is_correct": false, "explanation": "体貌：童车是给婴儿乘坐的小车，又小又轻，不能说“很大，也很重”。"}], "explanations": {"自行车": "体貌：自行车体形小、很轻，不能说“很大，也很重”。", "滑板车": "体貌：滑板车体形小、很轻，不符合“很大，也很重”的描述。", "坦克": "“坦克”是有铁壳的大型军用车辆，符合“很大，也很重”。", "童车": "体貌：童车是给婴儿乘坐的小车，又小又轻，不能说“很大，也很重”。"}, "sentence_index": 0, "correct_answer": "坦克"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他骑着坦克去上班。", "explanation": "这里应该用〈电动车〉。坦克是履带式军用车辆，不能骑着去上班，上班骑的是电动车。"}, {"text": "工地上，坦克正在挖土。", "explanation": "这里应该用〈挖掘机〉。挖土是挖掘机的作业，坦克是作战车辆，不用来挖土。"}, {"text": "路边，坦克在等客人。", "explanation": "这里应该用〈出租车〉。坦克不载客，路边等客的是出租车。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '386cdea5-bdf8-4a73-a55f-82328e64a0c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23820, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "洗衣机", "is_correct": false, "explanation": "语义：洗衣机是家用电器，不能讲它的故事与“老兵给孩子讲”的语境相合。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家用电器，与老兵讲给孩子的故事不符。"}, {"text": "眉毛", "is_correct": false, "explanation": "体貌：眉毛是面部器官，不是可以讲故事的对象。"}, {"text": "坦克", "is_correct": true, "explanation": "“坦克”是军用车辆，老兵给孩子讲坦克的故事符合语境。"}], "explanations": {"洗衣机": "语义：洗衣机是家用电器，不能讲它的故事与“老兵给孩子讲”的语境相合。", "冰箱": "语义：冰箱是家用电器，与老兵讲给孩子的故事不符。", "眉毛": "体貌：眉毛是面部器官，不是可以讲故事的对象。", "坦克": "“坦克”是军用车辆，老兵给孩子讲坦克的故事符合语境。"}, "sentence_index": 6, "correct_answer": "坦克"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈用坦克洗衣服。", "explanation": "这里应该用〈洗衣机〉。坦克是军用车辆，不能用来洗衣服。"}, {"text": "坦克在铁轨上飞驰。", "explanation": "这里应该用〈火车〉。坦克靠履带在地面行驶，不在铁轨上跑。"}, {"text": "坦克载着乘客驶向市区。", "explanation": "这里应该用〈公交车〉。坦克是军用车，不载客进城，载乘客进城的是公交车。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '386cdea5-bdf8-4a73-a55f-82328e64a0c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23820, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一个坦克在路上冒着黑烟。", "corrected_sentence": "一辆坦克在路上冒着黑烟。", "error_description": "量词错误：“坦克”的量词应为“辆”，不能用“个”。错误形式为“一个坦克”，正确形式为“一辆坦克”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '386cdea5-bdf8-4a73-a55f-82328e64a0c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23820, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那辆坦克开了很快。", "corrected_sentence": "那辆坦克开得很快。", "error_description": "补语标记错误：“开”与“快”之间应用“得”，不能用“了”。错误形式为“开了很快”，正确形式为“开得很快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '386cdea5-bdf8-4a73-a55f-82328e64a0c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
