INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23822, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指挥别人做事的人。", "primary_collocate": null, "pronunciation": "zhǐ huī zhě", "ipa": "tʂɻ̩˨˩ xweɪ˥ tʂɤ˨˩", "syllable_count": 3, "sentences": [{"text": "排练时，指挥者对大家说：再来一遍。", "target_word": "指挥者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游戏需要一个指挥者带大家前进。", "target_word": "指挥者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不想当指挥者，只想做自己的事。", "target_word": "指挥者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是工地上的指挥者，大家都听他的。", "target_word": "指挥者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搬家的时候，我是指挥者，告诉大家东西放哪儿。", "target_word": "指挥者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个队都需要一个指挥者。", "target_word": "指挥者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "指挥者说错了，大家就会走错路。", "target_word": "指挥者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次演出的指挥者是我的老师。", "target_word": "指挥者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明喜欢做指挥者，总是告诉别人怎么做。", "target_word": "指挥者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛开始前，指挥者先给大家分好工。", "target_word": "指挥者", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位指挥者", "label": "量词"}], "register": "中性", "sense_fingerprint": "告诉别人该做什么的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7caa9dc1-b16c-4823-8c0d-d506d16883a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23822, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "石头", "is_correct": false, "explanation": "配价：“说”的主语须是能说话的人，“石头”不能对大家说话。"}, {"text": "指挥者", "is_correct": true, "explanation": "“指挥者”能对众人发出指令，“排练时对大家说：再来一遍”符合语境。"}, {"text": "乐器", "is_correct": false, "explanation": "语义：乐器不能发出“再来一遍”的指令，与排练时的语境不符。"}, {"text": "地板", "is_correct": false, "explanation": "语义：地板不会对大家说话，句意不通。"}], "explanations": {"石头": "配价：“说”的主语须是能说话的人，“石头”不能对大家说话。", "指挥者": "“指挥者”能对众人发出指令，“排练时对大家说：再来一遍”符合语境。", "乐器": "语义：乐器不能发出“再来一遍”的指令，与排练时的语境不符。", "地板": "语义：地板不会对大家说话，句意不通。"}, "sentence_index": 0, "correct_answer": "指挥者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "指挥者给客人端上了热菜。", "explanation": "这里应该用〈服务员〉。“指挥者”指带领他人做事的人，不指端菜的人。"}, {"text": "这位指挥者每天给花浇水。", "explanation": "这里应该用〈园丁〉。“指挥者”指带领他人做事的人，不指照料花草的人。"}, {"text": "指挥者采访了当地居民。", "explanation": "这里应该用〈记者〉。“指挥者”指发号施令的人，不指采访的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce4fd29c-2289-4e96-96ae-fe634b805df6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23822, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "窗户", "is_correct": false, "explanation": "语义：窗户不会说话，“窗户说错了”无从谈起，句意不通。"}, {"text": "咖啡", "is_correct": false, "explanation": "语义：咖啡不会说话，“咖啡说错了”不合常理。"}, {"text": "指挥者", "is_correct": true, "explanation": "“指挥者”发出指令，说错了会让大家走错路，句意通顺。"}, {"text": "小狗", "is_correct": false, "explanation": "配价：“说”的主语须是人，小狗不能发出指令。"}], "explanations": {"窗户": "语义：窗户不会说话，“窗户说错了”无从谈起，句意不通。", "咖啡": "语义：咖啡不会说话，“咖啡说错了”不合常理。", "指挥者": "“指挥者”发出指令，说错了会让大家走错路，句意通顺。", "小狗": "配价：“说”的主语须是人，小狗不能发出指令。"}, "sentence_index": 6, "correct_answer": "指挥者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位指挥者在画布上画了一幅画。", "explanation": "这里应该用〈画家〉。“指挥者”指发号施令的人，不指作画的人。"}, {"text": "这位指挥者每天开车接送孩子。", "explanation": "这里应该用〈司机〉。“指挥者”指带领他人做事的人，不指接送孩子的司机。"}, {"text": "指挥者把鸡蛋炒熟了。", "explanation": "这里应该用〈厨师〉。“指挥者”不指做饭的人，不能用来说炒鸡蛋。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce4fd29c-2289-4e96-96ae-fe634b805df6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23822, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们班的指挥者们是小张。", "corrected_sentence": "我们班的指挥者是小张。", "error_description": "错误：“我们班的指挥者”特指一个人，加上“们”变为复数，与后面的单数“是小张”矛盾。正确：“我们班的指挥者是小张”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce4fd29c-2289-4e96-96ae-fe634b805df6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23822, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "很有经验指挥者，总能让大家安静下来。", "corrected_sentence": "很有经验的指挥者，总能让大家安静下来。", "error_description": "错误：“很有经验”修饰“指挥者”时漏掉了“的”。正确：“很有经验的指挥者”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce4fd29c-2289-4e96-96ae-fe634b805df6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
