INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23830, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把不同的事情放在一起，想好先做什么后做什么。", "primary_collocate": null, "pronunciation": "tǒng chóu", "ipa": "tʰʊŋ˨˩˦ ʈʂʰoʊ˧˥", "syllable_count": 2, "sentences": [{"text": "要统筹好时间，先写作业再玩。", "target_word": "统筹", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她统筹了一下，决定先买菜再去银行。", "target_word": "统筹", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "事情太多，你得好好统筹，想想先做哪件。", "target_word": "统筹", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把工作和学习统筹得很好。", "target_word": "统筹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈统筹了今天的事：先洗衣服，后做饭。", "target_word": "统筹", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今天要做的事很多，我先统筹一下安排。", "target_word": "统筹", "complexity_tier": "T3", "furigana": "jīn tiān yào zuò de shì hěn duō, wǒ xiān tǒng chóu yí xià ān pái。", "sentence_source": "generated"}, {"text": "会统筹的人，不会觉得时间不够用。", "target_word": "统筹", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你把这几件事统筹一下，哪个先哪个后？", "target_word": "统筹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出门前我统筹好了路线，先去超市再去医院。", "target_word": "统筹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很会统筹时间，总是先做重要的事。", "target_word": "统筹", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "统筹了", "label": "体标"}, {"form": "统筹过", "label": "体标"}, {"form": "统筹安排", "label": "复合"}, {"form": "統籌", "label": "繁体"}], "register": "书面", "sense_fingerprint": "把几件事放在一起，想好先后顺序再安排", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79c4ad0b-1d06-4255-be99-3a41444b55b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23830, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "统筹", "is_correct": true, "explanation": "统筹：安排先后顺序，与「时间」和「先写作业再玩」的安排相合，符合句意。"}, {"text": "承受", "is_correct": false, "explanation": "搭配：「承受」多接压力、痛苦等，不能与「好时间」搭配。"}, {"text": "攻击", "is_correct": false, "explanation": "语义：「攻击」指进攻，「要攻击好时间」语义不通，与「先写作业再玩」无关。"}, {"text": "阻碍", "is_correct": false, "explanation": "语义：「阻碍」与「先写作业再玩」的安排意图相反，句意矛盾。"}], "explanations": {"统筹": "统筹：安排先后顺序，与「时间」和「先写作业再玩」的安排相合，符合句意。", "承受": "搭配：「承受」多接压力、痛苦等，不能与「好时间」搭配。", "攻击": "语义：「攻击」指进攻，「要攻击好时间」语义不通，与「先写作业再玩」无关。", "阻碍": "语义：「阻碍」与「先写作业再玩」的安排意图相反，句意矛盾。"}, "sentence_index": 0, "correct_answer": "统筹"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他统筹了一下钥匙。", "explanation": "这里应该用〈检查〉。检查指察看是否完好，统筹指安排几件事的先后，不用于单件物品。"}, {"text": "妈妈统筹了房间的衣服。", "explanation": "这里应该用〈整理〉。整理指把杂乱的东西归置好，统筹指安排事情的先后，不用于衣物。"}, {"text": "他统筹了一下天气。", "explanation": "这里应该用〈预报〉。预报指事先说明天气的变化，统筹指安排事情的先后，不用于天气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04dcf9d6-09f4-4224-a53c-706c8d64bfa4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23830, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "统筹", "is_correct": true, "explanation": "统筹：安排先后，与「不觉得时间不够用」的结果相合，符合句意。"}, {"text": "拖延", "is_correct": false, "explanation": "语义：「拖延」会使时间更不够用，与「不会觉得时间不够用」的意思相反。"}, {"text": "攻克", "is_correct": false, "explanation": "搭配：「攻克」多接难关、难题，不说「会攻克的人」来指善于安排时间的人。"}, {"text": "抱怨", "is_correct": false, "explanation": "语义：「抱怨」表示不满，与「不会觉得时间不够用」的描述无关，句意不通。"}], "explanations": {"统筹": "统筹：安排先后，与「不觉得时间不够用」的结果相合，符合句意。", "拖延": "语义：「拖延」会使时间更不够用，与「不会觉得时间不够用」的意思相反。", "攻克": "搭配：「攻克」多接难关、难题，不说「会攻克的人」来指善于安排时间的人。", "抱怨": "语义：「抱怨」表示不满，与「不会觉得时间不够用」的描述无关，句意不通。"}, "sentence_index": 6, "correct_answer": "统筹"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他统筹了两本书。", "explanation": "这里应该用〈订购〉。订购指预先购买，统筹指安排事情的先后，不用于买书。"}, {"text": "妈妈统筹了生病的孩子。", "explanation": "这里应该用〈照顾〉。照顾指看护照料，统筹指统一安排事务，不用于照料人。"}, {"text": "他统筹了三个碗。", "explanation": "这里应该用〈洗〉。洗指用水清除污物，统筹不指清洗餐具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04dcf9d6-09f4-4224-a53c-706c8d64bfa4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23830, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她统筹了好今天的事情。", "corrected_sentence": "她统筹好了今天的事情。", "error_description": "「统筹」与补语「好」连用时，「了」应接在补语之后，应说「统筹好了」，不能说「统筹了好」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04dcf9d6-09f4-4224-a53c-706c8d64bfa4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23830, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他统筹了着三门课的时间。", "corrected_sentence": "他统筹着三门课的时间。", "error_description": "「统筹」后已用「着」表示持续，不能再加「了」。应只用「着」，改为「统筹着」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04dcf9d6-09f4-4224-a53c-706c8d64bfa4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
