INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23838, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "把要做的事情安排好，让很多人一起完成。", "primary_collocate": null, "pronunciation": "xiàng mù guǎn lǐ", "ipa": "ɕiɑŋ⁵¹ mu⁵¹ kuan²¹⁴ li²¹⁴", "syllable_count": 4, "sentences": [{"text": "这次活动的项目管理很重要。", "target_word": "项目管理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师教我们怎样做项目管理。", "target_word": "项目管理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他很会做项目管理，大家都听他的。", "target_word": "项目管理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "搬家需要好的项目管理。", "target_word": "项目管理", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "项目管理让十个人一起完成了工作。", "target_word": "项目管理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校的运动会靠项目管理才能顺利。", "target_word": "项目管理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她把任务分给大家，项目管理做得很好。", "target_word": "项目管理", "complexity_tier": "T3", "furigana": "tā bǎ rènwu fēn gěi dàjiā, xiàngmù guǎnlǐ zuò de hěn hǎo.", "sentence_source": "generated"}, {"text": "项目管理就是把事情安排好。", "target_word": "项目管理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有项目管理，大家不知道做什么。", "target_word": "项目管理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们请了一位专家来做项目管理。", "target_word": "项目管理", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "項目管理", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把事情安排好，让许多人一起完成的做法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ac50366-f88b-44b8-ba28-9c1798834e67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23838, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "雨水", "is_correct": false, "explanation": "语义：“雨水”与“活动”无关，句子说的是活动的组织安排。"}, {"text": "项目管理", "is_correct": true, "explanation": "正确：“项目管理”指把事情安排好、让多人一起完成，与句意相合。"}, {"text": "体温", "is_correct": false, "explanation": "语义：体温指人体的温度，不能用来组织或安排活动，「这次活动的体温」说不通。"}, {"text": "蚂蚁", "is_correct": false, "explanation": "语义：“蚂蚁”不能指活动中的安排工作，句中说的是组织方式。"}], "explanations": {"雨水": "语义：“雨水”与“活动”无关，句子说的是活动的组织安排。", "项目管理": "正确：“项目管理”指把事情安排好、让多人一起完成，与句意相合。", "体温": "语义：体温指人体的温度，不能用来组织或安排活动，「这次活动的体温」说不通。", "蚂蚁": "语义：“蚂蚁”不能指活动中的安排工作，句中说的是组织方式。"}, "sentence_index": 0, "correct_answer": "项目管理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "病人需要好的项目管理。", "explanation": "这里应该用〈护理〉。项目管理指安排多人完成共同的任务，照顾病人要说护理。"}, {"text": "身体需要好的项目管理。", "explanation": "这里应该用〈饮食〉。项目管理用于安排工作，身体的营养与进食要说饮食。"}, {"text": "孩子需要好的项目管理。", "explanation": "这里应该用〈睡眠〉。项目管理是安排工作的活动，孩子的休息要说睡眠。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9898a07c-f445-423d-a684-27958610459f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23838, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "语义：“天气”不能被“做得很好”修饰，句中指的是工作的组织。"}, {"text": "脚步", "is_correct": false, "explanation": "搭配：“做”不能与“脚步”搭配构成“做得很好”的说法。"}, {"text": "项目管理", "is_correct": true, "explanation": "正确：“项目管理做得很好”指组织安排得好，与“分给大家”的语境相合。"}, {"text": "闪电", "is_correct": false, "explanation": "语义：“闪电”不是可以被“做得很好”的对象，与句中的任务分配无关。"}], "explanations": {"天气": "语义：“天气”不能被“做得很好”修饰，句中指的是工作的组织。", "脚步": "搭配：“做”不能与“脚步”搭配构成“做得很好”的说法。", "项目管理": "正确：“项目管理做得很好”指组织安排得好，与“分给大家”的语境相合。", "闪电": "语义：“闪电”不是可以被“做得很好”的对象，与句中的任务分配无关。"}, "sentence_index": 6, "correct_answer": "项目管理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们请了一条项目管理来帮忙。", "explanation": "这里把〈项目管理〉当成了〈人手〉。项目管理是安排工作的活动，不是人，不能用条计量。"}, {"text": "桌上放着一颗项目管理。", "explanation": "这里把〈项目管理〉当成了〈豆子〉这类小粒的东西。项目管理是抽象的安排活动，不能放在桌上，也不能用颗计量。"}, {"text": "屋里放着一把项目管理。", "explanation": "这里把〈项目管理〉当成了〈工具〉。项目管理是抽象的安排活动，不是有柄的器具，不能用把计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9898a07c-f445-423d-a684-27958610459f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23838, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她很会项目管理，大家都愿意跟她合作。", "corrected_sentence": "她很会做项目管理，大家都愿意跟她合作。", "error_description": "“会”后应接动词，“做”不能省略。错误：很会项目管理；正确：很会做项目管理；原因：“会”作能愿动词，其后要带动词“做”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9898a07c-f445-423d-a684-27958610459f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23838, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们终于把项目管理做了完。", "corrected_sentence": "我们终于把项目管理做完了。", "error_description": "结果补语“完”应紧接动词，说“做完了”，不说“做了完”。错误：做了完；正确：做完了；原因：结果补语紧跟动词，“了”放在句末。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9898a07c-f445-423d-a684-27958610459f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
