INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23842, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "队员就是队伍里的人。", "primary_collocate": null, "pronunciation": "duì yuán", "ipa": "twei˥˩ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "我们班的足球队有十一个队员。", "target_word": "队员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明是篮球队的新队员。", "target_word": "队员", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "队员们穿着红色的衣服。", "target_word": "队员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师带着队员们去公园比赛。", "target_word": "队员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是我们划船队里最小的队员。", "target_word": "队员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有一名队员今天生病了，没来。", "target_word": "队员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "队员们在球场上跑来跑去。", "target_word": "队员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "教练给每个队员发了一瓶水。", "target_word": "队员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个队员很会踢球，大家都喜欢他。", "target_word": "队员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛前，队员们围在一起加油。", "target_word": "队员", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "名", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "队员：队伍里的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ac50366-f88b-44b8-ba28-9c1798834e67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23842, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "队员", "is_correct": true, "explanation": "正确。足球队中参加比赛的人叫“队员”，符合“十一个”的人数。"}, {"text": "教练", "is_correct": false, "explanation": "语义：教练是指导者，不属于十一名队员，与句子的人数不合。"}, {"text": "球门", "is_correct": false, "explanation": "语义：球门是器材，不是人，不能计入队员人数。"}, {"text": "队长", "is_correct": false, "explanation": "搭配：一支足球队通常只设一名队长，不能说“十一个队长”。"}], "explanations": {"队员": "正确。足球队中参加比赛的人叫“队员”，符合“十一个”的人数。", "教练": "语义：教练是指导者，不属于十一名队员，与句子的人数不合。", "球门": "语义：球门是器材，不是人，不能计入队员人数。", "队长": "搭配：一支足球队通常只设一名队长，不能说“十一个队长”。"}, "sentence_index": 0, "correct_answer": "队员"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "电影院里的队员很多。", "explanation": "这里应该用〈观众〉。队员指队伍里的人，看电影的人应说“观众”。"}, {"text": "我们班来了一条队员。", "explanation": "量词用错。“条”多用于细长的物品，队员不用“条”。"}, {"text": "超市里的队员很多。", "explanation": "这里应该用〈顾客〉。队员指队伍里的人，超市里买东西的人应说“顾客”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9898a07c-f445-423d-a684-27958610459f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23842, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "队员", "is_correct": true, "explanation": "正确。“队员们”指参加比赛的人，符合“跑来跑去”的动作。"}, {"text": "书", "is_correct": false, "explanation": "语义：书不会在球场上跑来跑去。"}, {"text": "柜子", "is_correct": false, "explanation": "搭配：“柜子”不能加“们”表示复数，也不能用于描述跑来跑去的动作。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会跑来跑去，与句子的主语不合。"}], "explanations": {"队员": "正确。“队员们”指参加比赛的人，符合“跑来跑去”的动作。", "书": "语义：书不会在球场上跑来跑去。", "柜子": "搭配：“柜子”不能加“们”表示复数，也不能用于描述跑来跑去的动作。", "石头": "语义：石头不会跑来跑去，与句子的主语不合。"}, "sentence_index": 6, "correct_answer": "队员"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家医院的队员很多。", "explanation": "这里应该用〈病人〉。队员指队伍里的人，医院里的人应说“病人”。"}, {"text": "新来的那位是一头队员。", "explanation": "量词用错。“头”用于牛、猪等大型牲畜，队员不用“头”。"}, {"text": "这家书店的队员很热情。", "explanation": "这里应该用〈店员〉。队员指队伍里的人，书店工作的人应说“店员”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9898a07c-f445-423d-a684-27958610459f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23842, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们班的足球队有一只新队员。", "corrected_sentence": "我们班的足球队有一名新队员。", "error_description": "错误：“队员”指人，量词应用“名”或“位”，不能用“只”。改为“一名新队员”即正确。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9898a07c-f445-423d-a684-27958610459f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23842, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两只队员站在球门前。", "corrected_sentence": "两位队员站在球门前。", "error_description": "错误：“队员”指人，量词应用“位”或“名”，不能用“只”。改为“两位队员”即正确。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9898a07c-f445-423d-a684-27958610459f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
