INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23846, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一群人或者一些国家，因为一起生活或一起做事，而有共同的利益和责任。", "primary_collocate": null, "pronunciation": "gòng tóng tǐ", "ipa": "kʊŋ˥˩ tʰʊŋ˧˥ tʰi˨˩˦", "syllable_count": 3, "sentences": [{"text": "欧洲的一些国家组成了经济共同体。", "target_word": "共同体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居们住在一起，像一个生活共同体。", "target_word": "共同体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "共同体的成员要一起承担责任。", "target_word": "共同体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "世界各国应该组成命运共同体。", "target_word": "共同体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个共同体里，每个人的利益都连在一起。", "target_word": "共同体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "几个国家为了共同利益，建立了共同体。", "target_word": "共同体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "住在这栋楼里的人，是一个利益共同体。", "target_word": "共同体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "加入共同体以后，各国要分担责任。", "target_word": "共同体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两家公司一起做生意，成了责任共同体。", "target_word": "共同体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家之间要互相帮助，共同体才能稳定。", "target_word": "共同体", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "命运共同体", "label": "复合"}, {"form": "利益共同体", "label": "复合"}, {"form": "共同體", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "因一起生活或做事而有共同利益和责任的人或国家", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd97b7304-e68a-4de4-b193-807fb56c347d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23846, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "共同体", "is_correct": true, "explanation": "正确：“组成了经济共同体”指因一起做事而有共同利益的国家群体，与“经济”搭配。"}, {"text": "文化", "is_correct": false, "explanation": "语义：文化不是可以被组成的群体，“组成了经济文化”不通。"}, {"text": "方言", "is_correct": false, "explanation": "语义：方言是语言的变体，不能组成经济组织，与“组成”不相容。"}, {"text": "乐队", "is_correct": false, "explanation": "搭配：“经济”不能修饰“乐队”，“经济乐队”不成词。"}], "explanations": {"共同体": "正确：“组成了经济共同体”指因一起做事而有共同利益的国家群体，与“经济”搭配。", "文化": "语义：文化不是可以被组成的群体，“组成了经济文化”不通。", "方言": "语义：方言是语言的变体，不能组成经济组织，与“组成”不相容。", "乐队": "搭配：“经济”不能修饰“乐队”，“经济乐队”不成词。"}, "sentence_index": 0, "correct_answer": "共同体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两国签订了和平共同体，双方都要遵守。", "explanation": "这里应该用〈条约〉。条约可以签订并遵守，共同体是人的集体，不能签订。"}, {"text": "两国使用同一种共同体，交易很方便。", "explanation": "这里应该用〈货币〉。货币可以使用，共同体不能被用于交易。"}, {"text": "两国都会弹这种共同体。", "explanation": "这里应该用〈乐器〉。乐器可以弹奏，共同体指人的集体，不能被弹奏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aac0e3e9-ed14-4a49-a8fb-6c93994fbbcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23846, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "共同体", "is_correct": true, "explanation": "正确：“是一个利益共同体”指因共同利益和责任结合在一起的群体，与前文“住在这栋楼里的人”相符。"}, {"text": "国家", "is_correct": false, "explanation": "语义：住在一栋楼里的人不能构成国家，“利益国家”与前文不符。"}, {"text": "车间", "is_correct": false, "explanation": "语义：车间是生产场所，住在楼里的人不是车间，“利益车间”与前文不符。"}, {"text": "花园", "is_correct": false, "explanation": "搭配：“利益”不能修饰“花园”，“利益花园”不成词。"}], "explanations": {"共同体": "正确：“是一个利益共同体”指因共同利益和责任结合在一起的群体，与前文“住在这栋楼里的人”相符。", "国家": "语义：住在一栋楼里的人不能构成国家，“利益国家”与前文不符。", "车间": "语义：车间是生产场所，住在楼里的人不是车间，“利益车间”与前文不符。", "花园": "搭配：“利益”不能修饰“花园”，“利益花园”不成词。"}, "sentence_index": 6, "correct_answer": "共同体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家店的利益共同体有两层楼，很气派。", "explanation": "这里应该用〈房子〉。房子有楼层，利益共同体指人的集体，不能说有几层楼。"}, {"text": "这个利益共同体很硬，摸上去冰凉。", "explanation": "这里应该用〈石头〉。石头可以又硬又凉，利益共同体指人的集体，不能用硬度和温度来描述。"}, {"text": "这个利益共同体只要两块钱，很便宜。", "explanation": "这里应该用〈车票〉。车票有价格，利益共同体指人的集体，不能说只要两块钱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aac0e3e9-ed14-4a49-a8fb-6c93994fbbcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23846, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "几个国家为了贸易，结了一个经济共同体。", "corrected_sentence": "几个国家为了贸易，结成了一个经济共同体。", "error_description": "错误在「结」。「结」单用后接「一个经济共同体」这类表示群体的宾语很不自然，应说「结成」。「结成」是复合动词，可以接「一个经济共同体」作宾语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aac0e3e9-ed14-4a49-a8fb-6c93994fbbcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23846, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "几个邻居合伙经营小店，形了成一个利益共同体。", "corrected_sentence": "几个邻居合伙经营小店，形成了一个利益共同体。", "error_description": "错误在“了”的位置。“形成”是一个词，“了”应放在整个词之后，应说“形成了”，不能拆成“形了成”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aac0e3e9-ed14-4a49-a8fb-6c93994fbbcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
