INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23848, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9898a07c-f445-423d-a684-27958610459f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23848, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "地面裂开了一条缝。", "primary_collocate": null, "pronunciation": "duàn céng", "ipa": "tuan⁵¹ tsʰəŋ³⁵", "syllable_count": 2, "sentences": [{"text": "路边有一条小断层。", "target_word": "断层", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "地震以后，田里出现了断层。", "target_word": "断层", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们在山上看到了一条断层。", "target_word": "断层", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条断层很长，也很深。", "target_word": "断层", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师给我们看断层的照片。", "target_word": "断层", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "断层让公路断开了。", "target_word": "断层", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子不敢走过那条断层。", "target_word": "断层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地面上的断层有一米宽。", "target_word": "断层", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雨后，断层里全是水。", "target_word": "断层", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "专家说这个断层很危险。", "target_word": "断层", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "斷層", "label": "繁体"}], "register": "中性", "sense_fingerprint": "地面裂开形成的缝隙", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ac50366-f88b-44b8-ba28-9c1798834e67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23848, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "石头", "is_correct": false, "explanation": "搭配：“条”一般不用来计量石头，石头应说“块”，与句中的地面裂缝不合。"}, {"text": "断层", "is_correct": true, "explanation": "正确：“断层”指地面裂开的缝，与“路边”和“一条”相合。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：蛋糕不会在路边裂开成缝，句子说的是地面的裂缝。"}, {"text": "乐曲", "is_correct": false, "explanation": "语义：乐曲不是地面上的缝隙，“路边有一条小……”指的是地面。"}], "explanations": {"石头": "搭配：“条”一般不用来计量石头，石头应说“块”，与句中的地面裂缝不合。", "断层": "正确：“断层”指地面裂开的缝，与“路边”和“一条”相合。", "蛋糕": "语义：蛋糕不会在路边裂开成缝，句子说的是地面的裂缝。", "乐曲": "语义：乐曲不是地面上的缝隙，“路边有一条小……”指的是地面。"}, "sentence_index": 0, "correct_answer": "断层"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的膝盖上有一道断层。", "explanation": "这里应该用〈伤口〉。断层指地面裂开的缝，皮肤上的创口要说伤口。"}, {"text": "他的脸上有很多断层。", "explanation": "这里应该用〈皱纹〉。断层指地面裂开的缝，脸上的纹路要说皱纹。"}, {"text": "碗上有一个断层。", "explanation": "这里应该用〈豁口〉。断层指地面裂开的缝，器物缺损的口子要说豁口。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9898a07c-f445-423d-a684-27958610459f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23848, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "声音", "is_correct": false, "explanation": "语义：“声音”不能被“走过”，句中指的是孩子要跨过的地面裂缝。"}, {"text": "电话", "is_correct": false, "explanation": "搭配：电话应说“部”或“通”，不说“那条电话”，也不能被“走过”，与句意不合。"}, {"text": "断层", "is_correct": true, "explanation": "正确：“走过那条断层”指跨过地面上的裂缝，与句意相合。"}, {"text": "花朵", "is_correct": false, "explanation": "语义：花朵不是可以走过去的地面裂缝，与句意不合。"}], "explanations": {"声音": "语义：“声音”不能被“走过”，句中指的是孩子要跨过的地面裂缝。", "电话": "搭配：电话应说“部”或“通”，不说“那条电话”，也不能被“走过”，与句意不合。", "断层": "正确：“走过那条断层”指跨过地面上的裂缝，与句意相合。", "花朵": "语义：花朵不是可以走过去的地面裂缝，与句意不合。"}, "sentence_index": 6, "correct_answer": "断层"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的衣袖上有一道断层。", "explanation": "这里应该用〈口子〉。断层指地面裂开的缝，衣服破开的口子要说口子。"}, {"text": "书的封面上有一道断层。", "explanation": "这里应该用〈折痕〉。断层指地面裂开的缝，纸面上的折痕要说折痕。"}, {"text": "桌上放着一把断层。", "explanation": "这里量词用错：“把”用于有柄的器具，断层是地面裂开的缝，不能放在桌上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9898a07c-f445-423d-a684-27958610459f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23848, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他看见路边有一只断层。", "corrected_sentence": "他看见路边有一条断层。", "error_description": "“断层”指地面裂开的缝，量词用“条”，不用“只”（“只”用于动物）。错误：一只断层；正确：一条断层。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9898a07c-f445-423d-a684-27958610459f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23848, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人在田边发现了一扇断层。", "corrected_sentence": "工人在田边发现了一条断层。", "error_description": "“扇”用于门窗，不能用于地面裂缝。错误：一扇断层；正确：一条断层。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9898a07c-f445-423d-a684-27958610459f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
