INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23850, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "大家团结在一起，像被粘住一样的力量。", "primary_collocate": null, "pronunciation": "níng jù lì", "ipa": "niŋ˧˥ tɕy˥˩ li˥˩", "syllable_count": 3, "sentences": [{"text": "我们班的凝聚力很强。", "target_word": "凝聚力", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "一起做游戏，让大家更有凝聚力。", "target_word": "凝聚力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个小组没有凝聚力，每个人都各做各的。", "target_word": "凝聚力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球队赢了比赛，凝聚力变强了。", "target_word": "凝聚力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷说，一家人要有凝聚力。", "target_word": "凝聚力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家一起劳动，增强了班里的凝聚力。", "target_word": "凝聚力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个乐队的凝聚力让人羡慕。", "target_word": "凝聚力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "缺少凝聚力的队伍很容易散掉。", "target_word": "凝聚力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说我们的凝聚力比去年好多了。", "target_word": "凝聚力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有凝聚力，大家就不会互相帮助。", "target_word": "凝聚力", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "股", "label": "量词"}], "register": "中性", "sense_fingerprint": "凝聚力：大家团结在一起的力量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ac50366-f88b-44b8-ba28-9c1798834e67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23850, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "体重", "is_correct": false, "explanation": "语义：体重指身体的重量，班级没有身体，「我们班的体重很强」说不通。"}, {"text": "凝聚力", "is_correct": true, "explanation": "正确：凝聚力指大家团结在一起的力量，「我们班的凝聚力很强」符合句意。"}, {"text": "电量", "is_correct": false, "explanation": "语义：电量指电的多少，与班级的团结无关，「我们班的电量很强」不成立。"}, {"text": "字数", "is_correct": false, "explanation": "搭配：字数只说多少，不能用「很强」来形容，「我们班的字数很强」不通。"}], "explanations": {"体重": "语义：体重指身体的重量，班级没有身体，「我们班的体重很强」说不通。", "凝聚力": "正确：凝聚力指大家团结在一起的力量，「我们班的凝聚力很强」符合句意。", "电量": "语义：电量指电的多少，与班级的团结无关，「我们班的电量很强」不成立。", "字数": "搭配：字数只说多少，不能用「很强」来形容，「我们班的字数很强」不通。"}, "sentence_index": 0, "correct_answer": "凝聚力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她整天忙碌，凝聚力很充沛。", "explanation": "这里应该用〈精力〉。凝聚力指人或团体结合的力量，个人的体力和干劲要用精力。"}, {"text": "球队有一只很强的凝聚力。", "explanation": "这里量词应该用〈股〉，说「一股凝聚力」。「只」用于动物、手等，不能用于凝聚力这样的抽象力量。"}, {"text": "这位演员很有凝聚力，观众都被打动了。", "explanation": "这里应该用〈感染力〉。凝聚力用于人群的结合，演员打动观众的能力要用感染力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9898a07c-f445-423d-a684-27958610459f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23850, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "噪音", "is_correct": false, "explanation": "语义：噪音是令人厌烦的声音，不会让人羡慕，「这个乐队的噪音让人羡慕」句意不通。"}, {"text": "烦恼", "is_correct": false, "explanation": "语义：烦恼是负面的心理状态，与「让人羡慕」的褒义方向相反。"}, {"text": "凝聚力", "is_correct": true, "explanation": "正确：「这个乐队的凝聚力让人羡慕」说明乐队团结的优点，与句意吻合。"}, {"text": "体积", "is_correct": false, "explanation": "搭配：体积只说物体所占空间的大小，不能用来形容乐队值得羡慕的地方。"}], "explanations": {"噪音": "语义：噪音是令人厌烦的声音，不会让人羡慕，「这个乐队的噪音让人羡慕」句意不通。", "烦恼": "语义：烦恼是负面的心理状态，与「让人羡慕」的褒义方向相反。", "凝聚力": "正确：「这个乐队的凝聚力让人羡慕」说明乐队团结的优点，与句意吻合。", "体积": "搭配：体积只说物体所占空间的大小，不能用来形容乐队值得羡慕的地方。"}, "sentence_index": 6, "correct_answer": "凝聚力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块磁铁的凝聚力很强，能吸起很多铁钉。", "explanation": "这里应该用〈吸引力〉。凝聚力指大家团结在一起的力量，磁铁吸引铁钉的力要用吸引力。"}, {"text": "这盏灯很有凝聚力，照得又亮又远。", "explanation": "这里应该用〈亮度〉。凝聚力指人或团体的团结，灯的明亮程度要用亮度。"}, {"text": "这颗子弹有很强的凝聚力。", "explanation": "这里应该用〈穿透力〉。凝聚力多指人或团体的团结，子弹穿透物体的能力要用穿透力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9898a07c-f445-423d-a684-27958610459f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23850, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个社团很凝聚力，大家一起活动。", "corrected_sentence": "这个社团很有凝聚力，大家一起活动。", "error_description": "错误：「很凝聚力」，漏掉了动词「有」。正确：「很有凝聚力」。凝聚力是名词，前面用程度副词修饰时要说「很有凝聚力」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9898a07c-f445-423d-a684-27958610459f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23850, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们组的一只凝聚力很强，大家很团结。", "corrected_sentence": "我们组的凝聚力很强，大家很团结。", "error_description": "错误：“凝聚力”前多加了“一只”。“只”多用于动物等，抽象的力量不能这样计量，应直接说“我们组的凝聚力很强”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9898a07c-f445-423d-a684-27958610459f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
