INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23852, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "两个东西互相需要，合在一起更好。", "primary_collocate": null, "pronunciation": "hù bǔ xìng", "ipa": "xu˥˩ pu˨˩˦ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "咖啡和甜点的互补性很高。", "target_word": "互补性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们的优点不同，互补性很好。", "target_word": "互补性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个团队成员之间互补性很强。", "target_word": "互补性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "手机和耳机有互补性，要一起买。", "target_word": "互补性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我和同桌互补性很强，他数学好，我语文好。", "target_word": "互补性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好朋友常常有互补性，一个爱说，一个爱听。", "target_word": "互补性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理喜欢找互补性强的人一起工作。", "target_word": "互补性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这两个游戏角色互补性高，一起玩更容易赢。", "target_word": "互补性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "牛奶和面包的互补性，让早饭更健康。", "target_word": "互补性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这对双胞胎性格不同，互补性特别好。", "target_word": "互补性", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "两个东西互相需要、合起来更好的特点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd97b7304-e68a-4de4-b193-807fb56c347d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23852, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "互补性", "is_correct": true, "explanation": "正确：「互补性」指两者互相补充、合起来更好，「咖啡和甜点的互补性很高」符合句意。"}, {"text": "保密性", "is_correct": false, "explanation": "搭配：「保密性」多用于信息、文件，不能说咖啡和甜点的保密性很高。"}, {"text": "合法性", "is_correct": false, "explanation": "语义：咖啡和甜点是食物，「合法性」指符合法律，与句子所说的搭配关系无关。"}, {"text": "偶然性", "is_correct": false, "explanation": "语义：「偶然性」指事情发生的随机程度，与两种食物能否互相搭配的特点不相干。"}], "explanations": {"互补性": "正确：「互补性」指两者互相补充、合起来更好，「咖啡和甜点的互补性很高」符合句意。", "保密性": "搭配：「保密性」多用于信息、文件，不能说咖啡和甜点的保密性很高。", "合法性": "语义：咖啡和甜点是食物，「合法性」指符合法律，与句子所说的搭配关系无关。", "偶然性": "语义：「偶然性」指事情发生的随机程度，与两种食物能否互相搭配的特点不相干。"}, "sentence_index": 0, "correct_answer": "互补性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这两份报告的互补性很高，内容几乎一样。", "explanation": "这里应该用〈重复性〉。互补性指两者互相补充，内容几乎一样的报告应说重复性。"}, {"text": "这个孩子对父母的互补性很强，什么事都要父母帮忙。", "explanation": "这里应该用〈依赖性〉。互补性指两者互相补充、合在一起更好；孩子事事靠父母、只有一方依赖另一方应说依赖性。"}, {"text": "这座桥两边的互补性很好，看起来一模一样。", "explanation": "这里应该用〈对称性〉。互补性指两者互相补充，两边形状一样应说对称性。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aac0e3e9-ed14-4a49-a8fb-6c93994fbbcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23852, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "互补性", "is_correct": true, "explanation": "正确：「互补性强」指彼此能互相补充，适合一起工作，符合句意。"}, {"text": "惰性", "is_correct": false, "explanation": "语义：「惰性」指懒散、不愿动的特点，经理「喜欢找」这种人一起工作说不通。"}, {"text": "透明度", "is_correct": false, "explanation": "搭配：「透明度」说物质或信息是否清楚，不用来形容人的工作搭配。"}, {"text": "怯懦性", "is_correct": false, "explanation": "语义：「怯懦性」指胆小怕事，经理「喜欢找」这种人一起工作与句意相违。"}], "explanations": {"互补性": "正确：「互补性强」指彼此能互相补充，适合一起工作，符合句意。", "惰性": "语义：「惰性」指懒散、不愿动的特点，经理「喜欢找」这种人一起工作说不通。", "透明度": "搭配：「透明度」说物质或信息是否清楚，不用来形容人的工作搭配。", "怯懦性": "语义：「怯懦性」指胆小怕事，经理「喜欢找」这种人一起工作与句意相违。"}, "sentence_index": 6, "correct_answer": "互补性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这两台机器的互补性很高，动作完全一致。", "explanation": "这里应该用〈同步性〉。互补性指两者相互补充，动作同时进行、完全一致应说同步性。"}, {"text": "这两个程序的互补性很强，互不影响。", "explanation": "这里应该用〈独立性〉。互补性指两者互相补充，互不影响的事物应说独立性。"}, {"text": "这份计划各部分的互补性很高，每一部分的风格都完全相同。", "explanation": "这里应该用〈统一性〉。互补性指两者各有不同、互相补充，风格完全相同应说统一性。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aac0e3e9-ed14-4a49-a8fb-6c93994fbbcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23852, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两种颜色有一只很强的互补性。", "corrected_sentence": "这两种颜色有一种很强的互补性。", "error_description": "量词错误：「互补性」是抽象名词，应用量词「种」，不能用「只」（「只」用于动物或成对物品中的一个）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aac0e3e9-ed14-4a49-a8fb-6c93994fbbcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23852, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们两个人的互补性的很强。", "corrected_sentence": "他们两个人的互补性很强。", "error_description": "多加了「的」：「互补性」与谓语「很强」之间不能加「的」，应说「他们两个人的互补性很强」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aac0e3e9-ed14-4a49-a8fb-6c93994fbbcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
