INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23854, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "血缘是指因血统相连而形成的亲属关系。", "primary_collocate": null, "pronunciation": "xuè yuán", "ipa": "ɕɥe˥˩ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "爸爸和女儿之间有很深的血缘关系。", "target_word": "血缘", "complexity_tier": "T3", "furigana": "bà ba hé nǚ ér zhī jiān yǒu hěn shēn de xuè yuán guān xì", "sentence_source": "generated"}, {"text": "医生说，这两个孩子有血缘关系。", "target_word": "血缘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说，血缘是割不断的。", "target_word": "血缘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子一出生，就和父母有着血缘关系。", "target_word": "血缘", "complexity_tier": "T3", "furigana": "hái zi yí chū shēng, jiù hé fù mǔ yǒu zhe xuè yuán guān xì", "sentence_source": "generated"}, {"text": "这个孩子和妈妈血缘很近，长得也像。", "target_word": "血缘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "虽然分开多年，血缘还是让他们想念彼此。", "target_word": "血缘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她终于找到了与自己有血缘关系的亲人。", "target_word": "血缘", "complexity_tier": "T3", "furigana": "tā zhōng yú zhǎo dào le yǔ zì jǐ yǒu xuè yuán guān xì de qīn rén", "sentence_source": "generated"}, {"text": "爷爷说，血缘比什么都重要。", "target_word": "血缘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父母和孩子的血缘，是一辈子的联系。", "target_word": "血缘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "养父母对孩子很好，但没有血缘关系。", "target_word": "血缘", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "血缘关系", "label": "复合"}, {"form": "血緣", "label": "繁体"}], "register": "中性", "sense_fingerprint": "因血统相连而形成的亲属关系", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd97b7304-e68a-4de4-b193-807fb56c347d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23854, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "血缘", "is_correct": true, "explanation": "正确答案。血缘指血统相连的亲属之间的联系。"}, {"text": "学员", "is_correct": false, "explanation": "xué（第二声）与 xuè（第四声）声调不同，意思是学员。"}, {"text": "雪原", "is_correct": false, "explanation": "xuě（第三声）与 xuè（第四声）声调不同，意思是雪原。"}, {"text": "学院", "is_correct": false, "explanation": "xué（第二声）与 xuè（第四声）、yuàn（第四声）与 yuán（第二声）声调都不同，意思是学院。"}], "explanations": {"血缘": "正确答案。血缘指血统相连的亲属之间的联系。", "学员": "xué（第二声）与 xuè（第四声）声调不同，意思是学员。", "雪原": "xuě（第三声）与 xuè（第四声）声调不同，意思是雪原。", "学院": "xué（第二声）与 xuè（第四声）、yuàn（第四声）与 yuán（第二声）声调都不同，意思是学院。"}, "sentence_index": null, "correct_answer": "血缘"}, "level_3": {"options": [{"text": "血缘", "is_correct": true, "explanation": "正确答案。血缘指血统相连的亲属之间的联系，与「很深的……关系」和「爸爸和女儿」相符。"}, {"text": "雇佣", "is_correct": false, "explanation": "语义：“雇佣”指雇主与雇员的关系，父女之间不是雇佣关系。"}, {"text": "同事", "is_correct": false, "explanation": "语义：“同事”指同一单位的工作伙伴，与“爸爸和女儿”的关系不符。"}, {"text": "相貌", "is_correct": false, "explanation": "体貌：“相貌”指长相，不能用来指两人之间的关系。"}], "explanations": {"血缘": "正确答案。血缘指血统相连的亲属之间的联系，与「很深的……关系」和「爸爸和女儿」相符。", "雇佣": "语义：“雇佣”指雇主与雇员的关系，父女之间不是雇佣关系。", "同事": "语义：“同事”指同一单位的工作伙伴，与“爸爸和女儿”的关系不符。", "相貌": "体貌：“相貌”指长相，不能用来指两人之间的关系。"}, "sentence_index": 0, "correct_answer": "血缘"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生给他抽了两百毫升血缘。", "explanation": "这里应该用〈血液〉。血缘指亲属关系，不是身体里的液体，不能被抽取。"}, {"text": "他的血缘是O型。", "explanation": "这里应该用〈血型〉。血缘指亲属关系，血型是血液的类别，不能说“血缘是O型”。"}, {"text": "这篇文章的血缘很清楚，是作者亲自写的。", "explanation": "这里应该用〈来源〉。血缘指亲属关系，文章的出处应说“来源”，不能说“血缘很清楚”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aac0e3e9-ed14-4a49-a8fb-6c93994fbbcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23854, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "血缘", "is_correct": true, "explanation": "正确答案。血缘指血亲关系，与“与自己有……关系的亲人”相符。"}, {"text": "债务", "is_correct": false, "explanation": "语义：“债务”指欠款关系，与“亲人”不相符。"}, {"text": "工作", "is_correct": false, "explanation": "语义：“工作关系”指同事或业务往来，不能用来指亲人。"}, {"text": "容貌", "is_correct": false, "explanation": "体貌：“容貌”指长相，不能和“关系”组成亲人之间的关系。"}], "explanations": {"血缘": "正确答案。血缘指血亲关系，与“与自己有……关系的亲人”相符。", "债务": "语义：“债务”指欠款关系，与“亲人”不相符。", "工作": "语义：“工作关系”指同事或业务往来，不能用来指亲人。", "容貌": "体貌：“容貌”指长相，不能和“关系”组成亲人之间的关系。"}, "sentence_index": 6, "correct_answer": "血缘"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我和同桌之间有很深的血缘。", "explanation": "这里应该用〈友谊〉。血缘指血亲关系，同桌之间没有血缘，不能这样说。"}, {"text": "他对父母的血缘很温暖。", "explanation": "这里应该用〈亲情〉。“温暖”形容感情，血缘是关系，不能说“血缘很温暖”。"}, {"text": "这两座城市之间有很深的血缘，每年都互相访问。", "explanation": "这里应该用〈渊源〉。血缘指血亲关系，城市之间没有血亲，应说“历史渊源很深”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aac0e3e9-ed14-4a49-a8fb-6c93994fbbcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23854, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子和父母之间有一条很近的血缘关系。", "corrected_sentence": "孩子和父母之间有一种很近的血缘关系。", "error_description": "量词错误：“关系”应搭配量词“种”，说“一种血缘关系”；“条”多用于细长的东西，不能用来数“关系”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aac0e3e9-ed14-4a49-a8fb-6c93994fbbcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23854, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们俩有血缘关系着。", "corrected_sentence": "他们俩有血缘关系。", "error_description": "“着”误用：陈述双方有血缘关系时，“着”不能放在“血缘关系”后面，应说“他们俩有血缘关系”，不加“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aac0e3e9-ed14-4a49-a8fb-6c93994fbbcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
