INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23858, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把线或绳子交叉绕在一起做成东西。", "primary_collocate": null, "pronunciation": "biān zhī chéng", "ipa": "pjɛn˥ ʈʂɻ̩˥ ʈʂʰɤŋ˧˥", "syllable_count": 3, "sentences": [{"text": "她正在把红线编织成一个小包。", "target_word": "编织成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸用绳子编织成一张网。", "target_word": "编织成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们学着把草编织成小篮子。", "target_word": "编织成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想把这些毛线编织成一件毛衣。", "target_word": "编织成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教我们把彩线编织成漂亮的手链。", "target_word": "编织成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶用白线编织成一块桌布。", "target_word": "编织成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把细竹条编织成一个圆圆的盒子。", "target_word": "编织成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷把细草绳编织成一根粗绳，用来拴船。", "target_word": "编织成", "complexity_tier": "T3", "furigana": "yé ye bǎ xì cǎo shéng biān zhī chéng yì gēn cū shéng, yòng lái shuān chuán.", "sentence_source": "generated"}, {"text": "这位老人能把麦秆编织成各种小动物。", "target_word": "编织成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈用蓝色的线编织成了一顶小帽子。", "target_word": "编织成", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "编织", "label": "原形"}, {"form": "编织成了", "label": "体标"}, {"form": "編織成", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把线或绳子交叉绕在一起做成东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd87c58c-09f6-4d3a-99ac-19363ee6c39b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23858, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "编织成", "is_correct": true, "explanation": "正确：“编织成”表示用线交叉制作成东西，与“一个小包”搭配，符合句意。"}, {"text": "剪成", "is_correct": false, "explanation": "语义：“剪”是剪断，不能把红线做成一个小包。"}, {"text": "熔成", "is_correct": false, "explanation": "搭配：“熔成”用于金属等材料受热变液体后成型，不用于红线。"}, {"text": "砌成", "is_correct": false, "explanation": "搭配：“砌成”用于砖石、墙体等，不能用红线砌成小包。"}], "explanations": {"编织成": "正确：“编织成”表示用线交叉制作成东西，与“一个小包”搭配，符合句意。", "剪成": "语义：“剪”是剪断，不能把红线做成一个小包。", "熔成": "搭配：“熔成”用于金属等材料受热变液体后成型，不用于红线。", "砌成": "搭配：“砌成”用于砖石、墙体等，不能用红线砌成小包。"}, "sentence_index": 0, "correct_answer": "编织成"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "沙子编织成了一座小山。", "explanation": "这里应该用〈堆成〉。沙子是松散颗粒，要堆积成山，不能编织。"}, {"text": "他把西瓜编织成了几块。", "explanation": "这里应该用〈切成〉。西瓜要切开才能分成几块，编织只适用于线、绳等材料。"}, {"text": "几块木板编织成了一个棚子。", "explanation": "这里应该用〈搭成〉。木板是硬材料，要搭建组装而成，不能用编织的方式。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1fa3d241-5fec-4a1a-b457-3365b82e151e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23858, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "编织成", "is_correct": true, "explanation": "正确：用细竹条交叉编织，可以做成圆盒子，符合句意。"}, {"text": "劈成", "is_correct": false, "explanation": "语义：“劈”是把竹条劈开，不能使竹条形成一个盒子。"}, {"text": "烧成", "is_correct": false, "explanation": "搭配：“烧成”用于陶瓷、泥土等，不说竹条烧成盒子。"}, {"text": "熔成", "is_correct": false, "explanation": "搭配：“熔成”用于金属等受热熔化的材料，不能用于竹条。"}], "explanations": {"编织成": "正确：用细竹条交叉编织，可以做成圆盒子，符合句意。", "劈成": "语义：“劈”是把竹条劈开，不能使竹条形成一个盒子。", "烧成": "搭配：“烧成”用于陶瓷、泥土等，不说竹条烧成盒子。", "熔成": "搭配：“熔成”用于金属等受热熔化的材料，不能用于竹条。"}, "sentence_index": 6, "correct_answer": "编织成"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工厂把铁水编织成了一个零件。", "explanation": "这里应该用〈铸成〉。铁水是熔化的金属，要浇入模具铸造成型，编织只适用于线、绳等材料。"}, {"text": "工人把树编织成了木材。", "explanation": "这里应该用〈砍成〉。树要砍伐、锯开才能成为木材，编织只适用于线、绳等材料。"}, {"text": "农民把甘蔗编织成了汁。", "explanation": "这里应该用〈压成〉。甘蔗要压榨出汁，不能用编织的方式。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1fa3d241-5fec-4a1a-b457-3365b82e151e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23858, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "爸爸用粗绳子编织到一个网兜。", "corrected_sentence": "爸爸用粗绳子编织成一个网兜。", "error_description": "错误：“编织到”。正确：“编织成”。结果补语应为“成”，表示编织出来的结果，“到”不能表示成品。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1fa3d241-5fec-4a1a-b457-3365b82e151e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23858, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "姐姐用粉色的线编织着成了一条小围巾。", "corrected_sentence": "姐姐用粉色的线编织成了一条小围巾。", "error_description": "错误：“编织着成了”。正确：“编织成了”。“着”表示动作进行，与表示完成的结果补语“成了”不能同时用在“编织”和“成”之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1fa3d241-5fec-4a1a-b457-3365b82e151e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23862, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "一致", "is_correct": true, "explanation": "“一致”指彼此相同、没有差异，与“两条路的走向相反”构成反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "“明亮”形容光线充足，与“对立”无反义关系。"}, {"text": "寒冷", "is_correct": false, "explanation": "“寒冷”形容温度低，与“对立”无反义关系。"}, {"text": "灵活", "is_correct": false, "explanation": "“灵活”形容动作敏捷或处理方式不死板，与“对立”无反义关系。"}], "correct_answer": "一致", "explanations": {"一致": "“一致”指彼此相同、没有差异，与“两条路的走向相反”构成反义关系。", "明亮": "“明亮”形容光线充足，与“对立”无反义关系。", "寒冷": "“寒冷”形容温度低，与“对立”无反义关系。", "灵活": "“灵活”形容动作敏捷或处理方式不死板，与“对立”无反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1fa3d241-5fec-4a1a-b457-3365b82e151e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23862, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "一致", "is_correct": true, "explanation": "“一致”指看法相同，与“观点完全对立”构成反义关系。"}, {"text": "热闹", "is_correct": false, "explanation": "“热闹”形容场面喧闹，与“对立”无反义关系。"}, {"text": "干净", "is_correct": false, "explanation": "“干净”形容没有污物，与“对立”无反义关系。"}, {"text": "遥远", "is_correct": false, "explanation": "“遥远”形容距离很远，与“对立”无反义关系。"}], "correct_answer": "一致", "explanations": {"一致": "“一致”指看法相同，与“观点完全对立”构成反义关系。", "热闹": "“热闹”形容场面喧闹，与“对立”无反义关系。", "干净": "“干净”形容没有污物，与“对立”无反义关系。", "遥远": "“遥远”形容距离很远，与“对立”无反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1fa3d241-5fec-4a1a-b457-3365b82e151e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23862, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "两个东西互相不一样，一个和另一个相反。", "primary_collocate": null, "pronunciation": "duì lì", "ipa": "twei˥˩ li˥˩", "syllable_count": 2, "sentences": [{"text": "这幅画用黑和白形成了鲜明的对立。", "target_word": "对立", "complexity_tier": "T3", "furigana": "zhè fú huà yòng hēi hé bái xíng chéng le xiān míng de duì lì.", "sentence_source": "generated"}, {"text": "这两个词的意思正好对立。", "target_word": "对立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他爱甜，我爱辣，我们的口味形成对立。", "target_word": "对立", "complexity_tier": "T3", "furigana": "tā ài tián, wǒ ài là, wǒ men de kǒu wèi xíng chéng duì lì.", "sentence_source": "generated"}, {"text": "这两条路的走向形成对立，一条向北，一条向南。", "target_word": "对立", "complexity_tier": "T3", "furigana": "zhè liǎng tiáo lù de zǒu xiàng xíng chéng duì lì, yì tiáo xiàng běi, yì tiáo xiàng nán.", "sentence_source": "generated"}, {"text": "姐姐和妹妹的性格对立，一个爱说，一个爱静。", "target_word": "对立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "舞台的左边和右边形成对立。", "target_word": "对立", "complexity_tier": "T3", "furigana": "wǔ tái de zuǒ biān hé yòu biān xíng chéng duì lì.", "sentence_source": "generated"}, {"text": "“大”和“小”的意思是对立的。", "target_word": "对立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两队的打法截然对立，一队攻，一队守。", "target_word": "对立", "complexity_tier": "T3", "furigana": "liǎng duì de dǎ fǎ jié rán duì lì, yī duì gōng, yī duì shǒu.", "sentence_source": "generated"}, {"text": "热情和冷淡是对立的态度。", "target_word": "对立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的观点完全对立，一个赞成，一个反对。", "target_word": "对立", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "对立着", "label": "体标"}, {"form": "对立了", "label": "体标"}, {"form": "对立面", "label": "复合"}, {"form": "對立", "label": "繁体"}], "register": "中性", "sense_fingerprint": "两个东西互相不一样，彼此相反", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd87c58c-09f6-4d3a-99ac-19363ee6c39b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23862, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "对立", "is_correct": true, "explanation": "“黑和白”形成的是相反的对照，“鲜明的对立”符合句意。"}, {"text": "数字", "is_correct": false, "explanation": "语义：数字不能与黑白形成鲜明的对照。"}, {"text": "答案", "is_correct": false, "explanation": "语义：答案不是可以与颜色形成对照的事物。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：“鲜明”修饰可以看见的对比，不修饰时间。"}], "explanations": {"对立": "“黑和白”形成的是相反的对照，“鲜明的对立”符合句意。", "数字": "语义：数字不能与黑白形成鲜明的对照。", "答案": "语义：答案不是可以与颜色形成对照的事物。", "时间": "搭配：“鲜明”修饰可以看见的对比，不修饰时间。"}, "sentence_index": 0, "correct_answer": "对立"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这两条河的走向对立，几乎重叠在一起。", "explanation": "这里应该用〈重叠〉。“对立”指两者不一样、相反，走向几乎重叠时不能说“对立”。"}, {"text": "两个人的步子对立，走起路来总是合拍。", "explanation": "这里应该用〈合拍〉。“对立”指两者不一样、相反，步子合拍时不能说“对立”。"}, {"text": "他们在婚姻问题上始终对立，看法完全一样。", "explanation": "这里应该用〈一样〉。“对立”指两者不一样、相反，看法一样时不能说“对立”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1fa3d241-5fec-4a1a-b457-3365b82e151e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23862, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "对立", "is_correct": true, "explanation": "“大”和“小”意思正好相反，“对立的”符合句意。"}, {"text": "相同", "is_correct": false, "explanation": "语义：“大”和“小”的意思相反，不能说“相同的”。"}, {"text": "相近", "is_correct": false, "explanation": "语义：“大”和“小”的意思正好相反，不能说“相近的”。"}, {"text": "对等", "is_correct": false, "explanation": "语义：“对等”指双方相当、相等，“大”和“小”的意思正好相反，不能说“对等的”。"}], "explanations": {"对立": "“大”和“小”意思正好相反，“对立的”符合句意。", "相同": "语义：“大”和“小”的意思相反，不能说“相同的”。", "相近": "语义：“大”和“小”的意思正好相反，不能说“相近的”。", "对等": "语义：“对等”指双方相当、相等，“大”和“小”的意思正好相反，不能说“对等的”。"}, "sentence_index": 6, "correct_answer": "对立"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这两块布的颜色完全对立，看不出区别。", "explanation": "这里应该用〈相同〉。“对立”指两者不一样、相反，颜色相同时不能用“对立”。"}, {"text": "两兄弟长得很对立，连妈妈都分不清。", "explanation": "这里应该用〈相像〉。长相相似不能用“对立”来形容。"}, {"text": "这两份文件的内容完全对立，一份是照抄的另一份。", "explanation": "这里应该用〈一致〉。“对立”指不一样、相反，内容照抄时不能说“对立”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1fa3d241-5fec-4a1a-b457-3365b82e151e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23862, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两条路的方向正好对立面。", "corrected_sentence": "这两条路的方向正好对立。", "error_description": "词形错误：此处应用动词“对立”，不能用名词“对立面”（对立的一方）。多了“面”，句子变成指一方，不再表示两者相反。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1fa3d241-5fec-4a1a-b457-3365b82e151e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23862, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两种颜色鲜明的对立。", "corrected_sentence": "这两种颜色形成鲜明的对立。", "error_description": "省略错误：“形成”不能省略，应说“形成鲜明的对立”，省略后句子不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1fa3d241-5fec-4a1a-b457-3365b82e151e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
