INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23864, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一个很大的地方，人们在这里比赛或表演。", "primary_collocate": null, "pronunciation": "jìng jì chǎng", "ipa": "tɕiŋ˥˩ tɕi˥˩ ʈʂʰɑŋ˨˩˦", "syllable_count": 3, "sentences": [{"text": "这个竞技场很大，能容纳很多人。", "target_word": "竞技场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "马戏团在竞技场里表演了一个晚上。", "target_word": "竞技场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们在竞技场门口等着看比赛。", "target_word": "竞技场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "竞技场外面排着长长的队。", "target_word": "竞技场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我爸爸带我去竞技场看足球赛。", "target_word": "竞技场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "竞技场的座位是红色的，很漂亮。", "target_word": "竞技场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雨了，竞技场里的比赛停了。", "target_word": "竞技场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "歌手在竞技场开了一场音乐会。", "target_word": "竞技场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座竞技场是为了奥运会建的。", "target_word": "竞技场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "竞技场里坐满了来看表演的人。", "target_word": "竞技场", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "座", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "競技場", "label": "繁体"}], "register": "中性", "sense_fingerprint": "竞技场：人们比赛或表演的大场地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd87c58c-09f6-4d3a-99ac-19363ee6c39b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23864, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "竞技场", "is_correct": true, "explanation": "正确：竞技场是一个很大、能容纳很多人的地方，符合“很大，能容纳很多人”的描述。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机是通信工具，不能“容纳很多人”。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包只能装东西，不能容纳很多人。"}, {"text": "眼镜", "is_correct": false, "explanation": "搭配：“容纳”的主语应是场所，眼镜无法与之搭配。"}], "explanations": {"竞技场": "正确：竞技场是一个很大、能容纳很多人的地方，符合“很大，能容纳很多人”的描述。", "手机": "语义：手机是通信工具，不能“容纳很多人”。", "书包": "语义：书包只能装东西，不能容纳很多人。", "眼镜": "搭配：“容纳”的主语应是场所，眼镜无法与之搭配。"}, "sentence_index": 0, "correct_answer": "竞技场"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子们在竞技场里玩滑梯。", "explanation": "这里应该用〈公园〉。玩滑梯要去公园；竞技场是人们比赛或表演的大场地。"}, {"text": "妈妈在竞技场里做饭。", "explanation": "这里应该用〈厨房〉。做饭要在厨房里进行；竞技场是人们比赛或表演的大场地。"}, {"text": "我们在竞技场里午睡。", "explanation": "这里应该用〈卧室〉。午睡要在卧室里；竞技场是人们比赛或表演的大场地。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1fa3d241-5fec-4a1a-b457-3365b82e151e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23864, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "竞技场", "is_correct": true, "explanation": "正确：“下雨了，竞技场里的比赛停了”，竞技场是大型比赛场地，符合语境。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：比赛不会在冰箱里进行。"}, {"text": "衣柜", "is_correct": false, "explanation": "搭配：“比赛”不能在衣柜里进行，衣柜与之不搭配。"}, {"text": "花瓶", "is_correct": false, "explanation": "语义：花瓶不能进行比赛，与“比赛停了”无关。"}], "explanations": {"竞技场": "正确：“下雨了，竞技场里的比赛停了”，竞技场是大型比赛场地，符合语境。", "冰箱": "语义：比赛不会在冰箱里进行。", "衣柜": "搭配：“比赛”不能在衣柜里进行，衣柜与之不搭配。", "花瓶": "语义：花瓶不能进行比赛，与“比赛停了”无关。"}, "sentence_index": 6, "correct_answer": "竞技场"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "病人在竞技场里打针。", "explanation": "这里应该用〈医院〉。打针要在医院进行；竞技场是人们比赛或表演的大场地。"}, {"text": "我去竞技场寄了一封信。", "explanation": "这里应该用〈邮局〉。寄信要去邮局；竞技场是人们比赛或表演的大场地。"}, {"text": "我在竞技场里刷了牙。", "explanation": "这里应该用〈卫生间〉。刷牙要在卫生间；竞技场是人们比赛或表演的大场地。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1fa3d241-5fec-4a1a-b457-3365b82e151e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23864, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "运动员们在一只竞技场里训练。", "corrected_sentence": "运动员们在一座竞技场里训练。", "error_description": "错误：“竞技场”的量词应用“座”，不能用“只”。正确形式：“一座竞技场”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1fa3d241-5fec-4a1a-b457-3365b82e151e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23864, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "运动员们在两个竞技场们里训练。", "corrected_sentence": "运动员们在两个竞技场里训练。", "error_description": "错误：“竞技场”是地点事物，不能加“们”表示复数。正确形式：“两个竞技场里”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1fa3d241-5fec-4a1a-b457-3365b82e151e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
