INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23866, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "两个人或两群人互相打斗，想杀死对方。", "primary_collocate": null, "pronunciation": "sī shā", "ipa": "sɹ̩˥ ʂa˥", "syllable_count": 2, "sentences": [{"text": "两群狼在山谷里厮杀。", "target_word": "厮杀", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "士兵们在河边厮杀了一夜。", "target_word": "厮杀", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "古时候，两个国家的军队常常在这里厮杀。", "target_word": "厮杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影里，两个武士在雪地上厮杀着。", "target_word": "厮杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他听见门外有人在厮杀，吓得不敢出去。", "target_word": "厮杀", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两只老虎为了地盘厮杀起来。", "target_word": "厮杀", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大战开始后，双方的战士立刻厮杀在一起。", "target_word": "厮杀", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷常说，他年轻时在战场上厮杀过。", "target_word": "厮杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥玩的游戏里，英雄要和怪物厮杀。", "target_word": "厮杀", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天黑以前，两队人马还在山下厮杀。", "target_word": "厮杀", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "厮杀了", "label": "体标：了"}, {"form": "厮杀着", "label": "体标：着"}, {"form": "厮杀过", "label": "体标：过"}], "register": "中性", "sense_fingerprint": "两方为了杀死对方而互相搏斗", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67ce11b3-a076-4ef4-a0b4-1773df363eb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23866, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "上学", "is_correct": false, "explanation": "语义：狼群不会上学，“上学”与“两群狼”的主语不相容。"}, {"text": "厮杀", "is_correct": true, "explanation": "正确：“厮杀”指两群狼互相搏斗、想杀死对方，与语境相符。"}, {"text": "结账", "is_correct": false, "explanation": "搭配：“结账”通常用于消费场合，不能用来描述狼群在山谷里的行为。"}, {"text": "考试", "is_correct": false, "explanation": "语义：狼群不参加考试，“考试”与“两群狼在山谷里”的场景矛盾。"}], "explanations": {"上学": "语义：狼群不会上学，“上学”与“两群狼”的主语不相容。", "厮杀": "正确：“厮杀”指两群狼互相搏斗、想杀死对方，与语境相符。", "结账": "搭配：“结账”通常用于消费场合，不能用来描述狼群在山谷里的行为。", "考试": "语义：狼群不参加考试，“考试”与“两群狼在山谷里”的场景矛盾。"}, "sentence_index": 0, "correct_answer": "厮杀"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两只小鸟在树上厮杀，唱了一上午。", "explanation": "这里应该用〈对唱〉。“厮杀”指想杀死对方的搏斗，两只鸟互相唱和时不能用这个词。"}, {"text": "两位同学在教室里厮杀了一下午。", "explanation": "这里应该用〈复习〉。“厮杀”指想杀死对方的搏斗，同学在教室里复习功课时不能用这个词。"}, {"text": "两位医生在手术台前厮杀，救活了病人。", "explanation": "这里应该用〈配合〉。“厮杀”指想杀死对方的搏斗，医生救治病人时要用“配合”，两者语义相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c1890f7-5960-4d2d-be19-63d94ee74132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23866, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "撤退", "is_correct": false, "explanation": "语义：“撤退”与“大战开始后”的交战语境相反。"}, {"text": "厮杀", "is_correct": true, "explanation": "正确：“厮杀”表示双方互相搏斗，与大战的场面相符。"}, {"text": "入睡", "is_correct": false, "explanation": "搭配：“入睡”不能与“立刻……在一起”构成战场上的动作，搭配不当。"}, {"text": "微笑", "is_correct": false, "explanation": "语义：“微笑”与“大战”的激烈场面完全不符。"}], "explanations": {"撤退": "语义：“撤退”与“大战开始后”的交战语境相反。", "厮杀": "正确：“厮杀”表示双方互相搏斗，与大战的场面相符。", "入睡": "搭配：“入睡”不能与“立刻……在一起”构成战场上的动作，搭配不当。", "微笑": "语义：“微笑”与“大战”的激烈场面完全不符。"}, "sentence_index": 6, "correct_answer": "厮杀"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两个司机为了停车位厮杀了几分钟，最后互相让了路。", "explanation": "这里应该用〈争执〉。“厮杀”指想杀死对方的生死搏斗，停车位上的口角用不到这个词，且结尾“互相让了路”也与之矛盾。"}, {"text": "两位学者在会上热情握手，厮杀了一下午。", "explanation": "这里应该用〈寒暄〉。“厮杀”指想杀死对方的搏斗，学者间礼节性的握手问候不能用这个词。"}, {"text": "两位老朋友在江边厮杀，聊了很久。", "explanation": "这里应该用〈散步〉。“厮杀”指想杀死对方的搏斗，老朋友在江边散步聊天时不能用这个词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c1890f7-5960-4d2d-be19-63d94ee74132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23866, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两只公鸡为了一个地盘被厮杀起来。", "corrected_sentence": "两只公鸡为了一个地盘厮杀起来。", "error_description": "“厮杀”是不及物动词，没有宾语，不能加“被”构成被动句，应说“厮杀起来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c1890f7-5960-4d2d-be19-63d94ee74132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23866, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两只狮子为了争夺领地厮杀着一次。", "corrected_sentence": "两只狮子为了争夺领地厮杀过一次。", "error_description": "错误：体标“着”表示动作持续或状态，不能与“一次”这类计次短语搭配；应改为“厮杀过一次”（经历过）或“厮杀了一次”，不能用“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c1890f7-5960-4d2d-be19-63d94ee74132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
