INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23872, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "从地下挖出有用的东西。", "primary_collocate": null, "pronunciation": "cǎi kuàng", "ipa": "tsʰai˨˩ kʰwaŋ˥˩", "syllable_count": 2, "sentences": [{"text": "我在游戏里学会了采矿。", "target_word": "采矿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟喜欢在游戏里挖洞采矿。", "target_word": "采矿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座老矿山以前每天都有人采矿。", "target_word": "采矿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们在地下三百米的地方采矿。", "target_word": "采矿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "采矿以后，工人把石头送出山洞。", "target_word": "采矿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天太冷，山里的人都不采矿了。", "target_word": "采矿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "要采矿，先得有一台好机器。", "target_word": "采矿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，这个国家靠采矿赚了很多钱。", "target_word": "采矿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "想在这里采矿，你要先拿到许可。", "target_word": "采矿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们用大机器在地下采矿。", "target_word": "采矿", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "采矿业", "label": "复合词"}, {"form": "采矿权", "label": "复合词"}, {"form": "采矿机", "label": "复合词"}], "register": "中性", "sense_fingerprint": "从地下挖出有用的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67ce11b3-a076-4ef4-a0b4-1773df363eb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23872, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "打针", "is_correct": false, "explanation": "语义：“游戏里”与“打针”的医疗场景不相符，游戏里学不到打针。"}, {"text": "生病", "is_correct": false, "explanation": "语义：“生病”不是可以学会的技能，“学会了生病”语义不通。"}, {"text": "吃饭", "is_correct": false, "explanation": "语义：“吃饭”是日常行为，不是游戏里可以学会的技能，与语境不符。"}, {"text": "采矿", "is_correct": true, "explanation": "正确：“采矿”是游戏中可以学会的技能，与语境相符。"}], "explanations": {"打针": "语义：“游戏里”与“打针”的医疗场景不相符，游戏里学不到打针。", "生病": "语义：“生病”不是可以学会的技能，“学会了生病”语义不通。", "吃饭": "语义：“吃饭”是日常行为，不是游戏里可以学会的技能，与语境不符。", "采矿": "正确：“采矿”是游戏中可以学会的技能，与语境相符。"}, "sentence_index": 0, "correct_answer": "采矿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她在山上采矿草药，带回家晒干。", "explanation": "这里应该用〈采集〉。“采矿”指挖掘地下矿物，地表采摘草药要用“采集”。"}, {"text": "孩子们在操场上采矿，玩得很开心。", "explanation": "这里应该用〈跑〉。“采矿”指挖掘地下矿物，在操场上奔跑要用“跑”。"}, {"text": "农民在院子里采矿取水，忙了一上午。", "explanation": "这里应该用〈打井〉。“采矿”指挖掘矿物，挖井取水要用“打井”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c1890f7-5960-4d2d-be19-63d94ee74132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23872, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "散步", "is_correct": false, "explanation": "语义：散步不需要机器，与“先得有一台好机器”的语境矛盾。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：睡觉用不着机器，与整句的条件关系不符。"}, {"text": "微笑", "is_correct": false, "explanation": "语义：微笑不需要任何机器，与“先得有一台好机器”的条件关系不成立。"}, {"text": "采矿", "is_correct": true, "explanation": "正确：“采矿”需要机器，与“先得有一台好机器”相符。"}], "explanations": {"散步": "语义：散步不需要机器，与“先得有一台好机器”的语境矛盾。", "睡觉": "语义：睡觉用不着机器，与整句的条件关系不符。", "微笑": "语义：微笑不需要任何机器，与“先得有一台好机器”的条件关系不成立。", "采矿": "正确：“采矿”需要机器，与“先得有一台好机器”相符。"}, "sentence_index": 6, "correct_answer": "采矿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈每周去菜市场采矿蔬菜。", "explanation": "这里应该用〈采购〉。“采矿”指挖掘矿物，在市场买菜要用“采购”。"}, {"text": "科学家在湖边采矿，检测水质。", "explanation": "这里应该用〈采样〉。“采矿”指挖掘矿物，为检测水质取水样要用“采样”。"}, {"text": "记者在街上采矿了很多市民。", "explanation": "这里应该用〈采访〉。“采矿”指挖掘矿物，向市民询问意见要用“采访”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c1890f7-5960-4d2d-be19-63d94ee74132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23872, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们一直在地下采矿着。", "corrected_sentence": "他们一直在地下采着矿。", "error_description": "“采矿”是动宾式离合词，进行体“着”要放在“采”后，应说“采着矿”，不能说“采矿着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c1890f7-5960-4d2d-be19-63d94ee74132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23872, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们昨天没采矿了。", "corrected_sentence": "他们昨天没采矿。", "error_description": "错误：用“没”否定已发生的动作时，动词后一般不加“了”，应说“他们昨天没采矿”，不说“没采矿了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c1890f7-5960-4d2d-be19-63d94ee74132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
