INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23876, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "打仗时用的方法和计划。", "primary_collocate": null, "pronunciation": "zhàn shù", "ipa": "ʈʂan˥˩ ʂu˥˩", "syllable_count": 2, "sentences": [{"text": "将军想出了一个新的战术。", "target_word": "战术", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这支军队用的战术很特别。", "target_word": "战术", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "打仗之前，指挥官要先定好战术。", "target_word": "战术", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "敌人改变了战术，我们也要变。", "target_word": "战术", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "士兵们认真学习新的战术。", "target_word": "战术", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次战斗里，他们用了包围的战术。", "target_word": "战术", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老将军很会用战术，打赢了许多仗。", "target_word": "战术", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在地图上画出了军队的战术。", "target_word": "战术", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好的战术能让小部队打败大部队。", "target_word": "战术", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "古代的将军常常写书讲战术。", "target_word": "战术", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "戰術", "label": "繁体"}, {"form": "种", "label": "量词"}, {"form": "套", "label": "量词"}], "register": "中性", "sense_fingerprint": "军队作战时采用的方法和计划", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '549d97fa-a22a-48f3-802f-0d64c12db3ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23876, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "战术", "is_correct": true, "explanation": "正确：战术（zhàn shù）指打仗时采用的方法和计划。"}, {"text": "站住", "is_correct": false, "explanation": "zhù 与 shù 声母不同（zh 与 sh），声调相同（第四声），意思是站稳、停下来不动。"}, {"text": "战士", "is_correct": false, "explanation": "shì 与 shù 韵母不同（i 与 u），声调相同（第四声），意思是士兵。"}, {"text": "战书", "is_correct": false, "explanation": "shū（第一声）与 shù 韵母相同，声调不同（一声与四声），意思是下战书、宣战的文书。"}, {"text": "展述", "is_correct": false, "explanation": "zhǎn（第三声）与 zhàn（第四声）声调不同，shù 相同，意思是陈述、阐述。"}], "explanations": {"战术": "正确：战术（zhàn shù）指打仗时采用的方法和计划。", "站住": "zhù 与 shù 声母不同（zh 与 sh），声调相同（第四声），意思是站稳、停下来不动。", "战士": "shì 与 shù 韵母不同（i 与 u），声调相同（第四声），意思是士兵。", "战书": "shū（第一声）与 shù 韵母相同，声调不同（一声与四声），意思是下战书、宣战的文书。", "展述": "zhǎn（第三声）与 zhàn（第四声）声调不同，shù 相同，意思是陈述、阐述。"}, "sentence_index": null, "correct_answer": "战术"}, "level_3": {"options": [{"text": "战术", "is_correct": true, "explanation": "正确：战术指打仗时采用的方法和计划，与“将军想出了一个新的……”相符。"}, {"text": "盘子", "is_correct": false, "explanation": "语义：将军想出的应是作战的方法，“盘子”是餐具，句意不通。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“想出”不能与“天气”搭配，天气无法被想出来。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家用电器，不是作战的方法或计划。"}], "explanations": {"战术": "正确：战术指打仗时采用的方法和计划，与“将军想出了一个新的……”相符。", "盘子": "语义：将军想出的应是作战的方法，“盘子”是餐具，句意不通。", "天气": "搭配：“想出”不能与“天气”搭配，天气无法被想出来。", "冰箱": "语义：冰箱是家用电器，不是作战的方法或计划。"}, "sentence_index": 0, "correct_answer": "战术"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "秦国制定了统一六国的战术，经过十年终于实现了。", "explanation": "这里应该用〈战略〉。统一全国的长远规划属于战略，战术指具体的作战方法。"}, {"text": "这座城的战术长达三公里。", "explanation": "这里应该用〈城墙〉。战术是作战的方法和计划，不能用来计量长度，有三公里长的是城墙。"}, {"text": "士兵们每天都要进行艰苦的战术。", "explanation": "这里应该用〈训练〉。战术是作战方法，日常反复练习要用训练。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eaf93011-0e90-41ac-ab22-ff49726bb7fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23876, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "战术", "is_correct": true, "explanation": "正确：战术指打仗时采用的方法，“很会用战术，打赢了许多仗”说的正是这个意思。"}, {"text": "颜料", "is_correct": false, "explanation": "语义：颜料是绘画用的材料，不能用来打仗，句意不通。"}, {"text": "面粉", "is_correct": false, "explanation": "语义：面粉是食材，与打仗的语境无关。"}, {"text": "药膏", "is_correct": false, "explanation": "搭配：“很会用药膏”不能用来说打赢仗，与“打赢许多仗”不搭。"}], "explanations": {"战术": "正确：战术指打仗时采用的方法，“很会用战术，打赢了许多仗”说的正是这个意思。", "颜料": "语义：颜料是绘画用的材料，不能用来打仗，句意不通。", "面粉": "语义：面粉是食材，与打仗的语境无关。", "药膏": "搭配：“很会用药膏”不能用来说打赢仗，与“打赢许多仗”不搭。"}, "sentence_index": 6, "correct_answer": "战术"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "士兵们守住了战术，等待援军。", "explanation": "这里应该用〈阵地〉。战术是作战的方法和计划，不是可以坚守的地方；被守住的地方要用阵地。"}, {"text": "将军下令先运战术，再出兵。", "explanation": "这里应该用〈粮草〉。战术是作战方法，不是实物，不能运送；供应军队的粮食和草料要用粮草。"}, {"text": "这场战争的战术花了一亿两银子。", "explanation": "这里应该用〈军费〉。战术是作战方法，本身不花钱；打仗所需的钱要用军费。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eaf93011-0e90-41ac-ab22-ff49726bb7fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23876, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "敌军设计了一套巧妙的战术的。", "corrected_sentence": "敌军设计了一套巧妙的战术。", "error_description": "结构错误：句末多加了「的」，「战术的」不能作为句子成分结束，应去掉多余的「的」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eaf93011-0e90-41ac-ab22-ff49726bb7fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23876, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次战斗前，将军想出了一本新战术。", "corrected_sentence": "这次战斗前，将军想出了一套新战术。", "error_description": "量词错误：“战术”应用量词“套”或“种”计量，“本”用于书册，不能用来计量战术。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eaf93011-0e90-41ac-ab22-ff49726bb7fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
