INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23878, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "两个人或两方像拉开的弓一样，马上就要打起来了。", "primary_collocate": null, "pronunciation": "jiàn bá nǔ zhāng", "ipa": "tɕjɛn˥˩ pa˧˥ nu˨˩˦ ʈʂɑŋ˥˥", "syllable_count": 4, "sentences": [{"text": "两个男孩剑拔弩张，好像要打架。", "target_word": "剑拔弩张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教室里剑拔弩张，大家都很怕。", "target_word": "剑拔弩张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们一见面就剑拔弩张。", "target_word": "剑拔弩张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两只狗看着对方，样子剑拔弩张。", "target_word": "剑拔弩张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛前，两队的气氛剑拔弩张。", "target_word": "剑拔弩张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸和哥哥吵架，家里剑拔弩张。", "target_word": "剑拔弩张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你们别这样剑拔弩张，好好说话。", "target_word": "剑拔弩张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门口的两个人看起来剑拔弩张。", "target_word": "剑拔弩张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师一进来，剑拔弩张的样子就没了。", "target_word": "剑拔弩张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们说着说着，气氛变得剑拔弩张。", "target_word": "剑拔弩张", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "劍拔弩張", "label": "繁体"}], "register": "书面", "sense_fingerprint": "像拉开的弓，双方马上要打起来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67ce11b3-a076-4ef4-a0b4-1773df363eb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23878, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "剑拔弩张", "is_correct": true, "explanation": "剑拔弩张形容两个人像拉开的弓一样，马上要打起来，与“好像要打架”相符。"}, {"text": "心平气和", "is_correct": false, "explanation": "语义：“心平气和”表示态度平和，与“好像要打架”矛盾。"}, {"text": "亲密无间", "is_correct": false, "explanation": "语义：“亲密无间”形容关系亲近，与“好像要打架”相反。"}, {"text": "蒸蒸日上", "is_correct": false, "explanation": "搭配：“蒸蒸日上”形容事业发展，不用来形容男孩子的状态。"}], "explanations": {"剑拔弩张": "剑拔弩张形容两个人像拉开的弓一样，马上要打起来，与“好像要打架”相符。", "心平气和": "语义：“心平气和”表示态度平和，与“好像要打架”矛盾。", "亲密无间": "语义：“亲密无间”形容关系亲近，与“好像要打架”相反。", "蒸蒸日上": "搭配：“蒸蒸日上”形容事业发展，不用来形容男孩子的状态。"}, "sentence_index": 0, "correct_answer": "剑拔弩张"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这对好朋友相处剑拔弩张。", "explanation": "这里应该用〈友好〉。剑拔弩张指双方冲突对峙，好朋友之间不能这样形容。"}, {"text": "展览馆里，大家剑拔弩张地看着展品。", "explanation": "剑拔弩张形容双方对峙、一触即发，安静观展的场面与词义相反。"}, {"text": "两位老朋友久别重逢，气氛剑拔弩张。", "explanation": "这里应该用〈融洽〉。剑拔弩张指双方对峙、一触即发，与久别重逢的融洽气氛相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c1890f7-5960-4d2d-be19-63d94ee74132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23878, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "剑拔弩张", "is_correct": true, "explanation": "剑拔弩张形容双方对峙、一触即发，与“别这样”的劝阻语境相符。"}, {"text": "无忧无虑", "is_correct": false, "explanation": "语义：“无忧无虑”表示轻松自在，与“别这样，好好说话”的劝阻语境不合。"}, {"text": "悠然自得", "is_correct": false, "explanation": "语义：“悠然自得”表示从容闲适，与对方的争执场面不合。"}, {"text": "落落大方", "is_correct": false, "explanation": "搭配：“落落大方”形容人的举止风度，不能用来修饰说话时的状态。"}], "explanations": {"剑拔弩张": "剑拔弩张形容双方对峙、一触即发，与“别这样”的劝阻语境相符。", "无忧无虑": "语义：“无忧无虑”表示轻松自在，与“别这样，好好说话”的劝阻语境不合。", "悠然自得": "语义：“悠然自得”表示从容闲适，与对方的争执场面不合。", "落落大方": "搭配：“落落大方”形容人的举止风度，不能用来修饰说话时的状态。"}, "sentence_index": 6, "correct_answer": "剑拔弩张"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这对邻居一起修剪花草，剑拔弩张地配合着。", "explanation": "这里应该用〈默契〉。剑拔弩张指双方对峙冲突，邻居合作默契的场面与词义相反。"}, {"text": "他收到礼物，心里剑拔弩张。", "explanation": "这里应该用〈开心〉。剑拔弩张描述双方对峙，只形容两方冲突，不形容一个人的开心心情。"}, {"text": "湖面上风平浪静，水波剑拔弩张。", "explanation": "这里应该用〈平静〉。剑拔弩张指双方对峙、一触即发，不能用来形容风平浪静的水面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c1890f7-5960-4d2d-be19-63d94ee74132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23878, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的话把会场的气氛剑拔弩张。", "corrected_sentence": "他的话把会场的气氛搞得剑拔弩张。", "error_description": "错误：“把”字句中缺少“搞得”引出补语。正确说法是“把会场的气氛搞得剑拔弩张”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c1890f7-5960-4d2d-be19-63d94ee74132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23878, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两人为了一点小事吵剑拔弩张。", "corrected_sentence": "两人为了一点小事吵得剑拔弩张。", "error_description": "错误：动词“吵”后要用“得”引出补语“剑拔弩张”，应说“吵得剑拔弩张”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c1890f7-5960-4d2d-be19-63d94ee74132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
