INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23884, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一个让大家在电脑上一起聊天、说事情的地方。", "primary_collocate": null, "pronunciation": "shè qū lùn tán", "ipa": "ʂɤ˥˩ tɕʰy˥˥ lwən˥˩ tʰan˧˥", "syllable_count": 4, "sentences": [{"text": "社区论坛是大家聊天的地方。", "target_word": "社区论坛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我每天晚上都上社区论坛看看。", "target_word": "社区论坛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在社区论坛问了一个问题。", "target_word": "社区论坛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "社区论坛上有很多人说话。", "target_word": "社区论坛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以去社区论坛找朋友聊天。", "target_word": "社区论坛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把照片发到了社区论坛上。", "target_word": "社区论坛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个社区论坛是免费的。", "target_word": "社区论坛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王在社区论坛上写了一句话。", "target_word": "社区论坛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "社区论坛里的人都很好。", "target_word": "社区论坛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们学校有一个社区论坛。", "target_word": "社区论坛", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "社區論壇", "label": "繁体"}], "register": "中性", "sense_fingerprint": "大家在电脑上聊天说事的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67ce11b3-a076-4ef4-a0b4-1773df363eb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23884, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "社区论坛", "is_correct": true, "explanation": "社区论坛是网上让大家聊天说事的平台，符合“大家聊天的地方”。"}, {"text": "图书馆", "is_correct": false, "explanation": "语义：图书馆要求安静，不是供大家聊天的地方。"}, {"text": "菜市场", "is_correct": false, "explanation": "语义：菜市场是买卖蔬菜的地方，不是聊天的场所。"}, {"text": "教科书", "is_correct": false, "explanation": "搭配：“教科书”是学习用品，不能用“……的地方”来说明它。"}], "explanations": {"社区论坛": "社区论坛是网上让大家聊天说事的平台，符合“大家聊天的地方”。", "图书馆": "语义：图书馆要求安静，不是供大家聊天的地方。", "菜市场": "语义：菜市场是买卖蔬菜的地方，不是聊天的场所。", "教科书": "搭配：“教科书”是学习用品，不能用“……的地方”来说明它。"}, "sentence_index": 0, "correct_answer": "社区论坛"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在社区论坛做了一顿晚饭。", "explanation": "这里应该用〈厨房〉。社区论坛是网络平台，不是做饭的地方。"}, {"text": "我把钥匙放在社区论坛里了。", "explanation": "社区论坛是网络平台，没有实物空间，钥匙不能放在里面，词义不符。"}, {"text": "这本社区论坛很有趣。", "explanation": "这里应该用〈个〉。社区论坛用“个”作量词，“本”用于书籍，不能修饰论坛。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c1890f7-5960-4d2d-be19-63d94ee74132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23884, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "社区论坛", "is_correct": true, "explanation": "社区论坛是网络平台，可以免费使用，符合句意。"}, {"text": "工资", "is_correct": false, "explanation": "语义：工资是劳动报酬，不能说“免费”。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮不是人可以获取或付费的东西，不能说“免费”。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“免费”修饰可以获取的物品或服务，不能用于天气。"}], "explanations": {"社区论坛": "社区论坛是网络平台，可以免费使用，符合句意。", "工资": "语义：工资是劳动报酬，不能说“免费”。", "月亮": "语义：月亮不是人可以获取或付费的东西，不能说“免费”。", "天气": "搭配：“免费”修饰可以获取的物品或服务，不能用于天气。"}, "sentence_index": 6, "correct_answer": "社区论坛"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学生们在我们学校的社区论坛吃饭。", "explanation": "这里应该用〈餐厅〉。社区论坛是网络平台，不能用来吃饭。"}, {"text": "他在社区论坛看病。", "explanation": "这里应该用〈医院〉。社区论坛不是医疗场所，不能在这里看病。"}, {"text": "我们每天在社区论坛上跑步锻炼。", "explanation": "这里应该用〈操场〉。社区论坛是网络平台，不是运动场地，不能在上面跑步锻炼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c1890f7-5960-4d2d-be19-63d94ee74132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23884, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们班的同学常社区论坛上交流。", "corrected_sentence": "我们班的同学常在社区论坛上交流。", "error_description": "错误：“社区论坛”前漏掉介词“在”。正确说法是“在社区论坛上交流”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c1890f7-5960-4d2d-be19-63d94ee74132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23884, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台社区论坛的功能很多。", "corrected_sentence": "这个社区论坛的功能很多。", "error_description": "错误：“社区论坛”应用量词“个”，“台”用于机器、电视等，不能修饰论坛。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c1890f7-5960-4d2d-be19-63d94ee74132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
