INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23886, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西烧热再放进水里，让它变得更结实。", "primary_collocate": null, "pronunciation": "cuì liàn", "ipa": "tsʰweɪ˥˩ ljɛn˥˩", "syllable_count": 2, "sentences": [{"text": "师傅把烧红的刀放进水里淬炼。", "target_word": "淬炼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "铁匠正在淬炼一把新剑。", "target_word": "淬炼", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "钢刀淬炼以后，变得更硬了。", "target_word": "淬炼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人把钢板加热后再淬炼。", "target_word": "淬炼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "淬炼过的剑又硬又结实。", "target_word": "淬炼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这把刀淬炼得很好，不容易断。", "target_word": "淬炼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷教我怎么淬炼铁器。", "target_word": "淬炼", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "水太凉，刀淬炼时会裂开。", "target_word": "淬炼", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "古代的铁匠用水和油来淬炼钢。", "target_word": "淬炼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "师傅说，这把剑淬炼了三次。", "target_word": "淬炼", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "淬炼了", "label": "完成体"}, {"form": "淬炼着", "label": "持续体"}, {"form": "淬炼过", "label": "经历体"}, {"form": "淬煉", "label": "繁体"}], "register": "中性", "sense_fingerprint": "金属烧红后放入水中急速冷却，使其更硬更结实", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '549d97fa-a22a-48f3-802f-0d64c12db3ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23886, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "淬炼", "is_correct": true, "explanation": "正确答案：淬炼（cuì liàn），指把烧红的金属放入水中急速冷却，使其变硬。"}, {"text": "脆片", "is_correct": false, "explanation": "piàn（第四声）与 liàn 声母不同（p/l），意思是薯片等脆的零食。"}, {"text": "脆面", "is_correct": false, "explanation": "miàn（第四声）与 liàn 声母不同（m/l），意思是一种脆口的方便面零食。"}, {"text": "脆亮", "is_correct": false, "explanation": "liàng（第四声）与 liàn 韵尾不同（-ng/-n），意思是声音清脆响亮。"}, {"text": "对练", "is_correct": false, "explanation": "duì（第四声）与 cuì 声母不同（d/c），意思是两人配合进行的练习。"}], "explanations": {"淬炼": "正确答案：淬炼（cuì liàn），指把烧红的金属放入水中急速冷却，使其变硬。", "脆片": "piàn（第四声）与 liàn 声母不同（p/l），意思是薯片等脆的零食。", "脆面": "miàn（第四声）与 liàn 声母不同（m/l），意思是一种脆口的方便面零食。", "脆亮": "liàng（第四声）与 liàn 韵尾不同（-ng/-n），意思是声音清脆响亮。", "对练": "duì（第四声）与 cuì 声母不同（d/c），意思是两人配合进行的练习。"}, "sentence_index": null, "correct_answer": "淬炼"}, "level_3": {"options": [{"text": "淬炼", "is_correct": true, "explanation": "正确：“淬炼”指把烧红的金属放进水中急速冷却，使其变硬，与句意相符。"}, {"text": "切", "is_correct": false, "explanation": "语义：“切”是把东西分开，放进水里的刀不会被“切”，句意不通。"}, {"text": "晾", "is_correct": false, "explanation": "搭配：“晾”是放在空气中使其干燥，与“放进水里”不搭配。"}, {"text": "点燃", "is_correct": false, "explanation": "语义：“点燃”是使其燃烧，刀放进水里不能被点燃，与句意相悖。"}], "explanations": {"淬炼": "正确：“淬炼”指把烧红的金属放进水中急速冷却，使其变硬，与句意相符。", "切": "语义：“切”是把东西分开，放进水里的刀不会被“切”，句意不通。", "晾": "搭配：“晾”是放在空气中使其干燥，与“放进水里”不搭配。", "点燃": "语义：“点燃”是使其燃烧，刀放进水里不能被点燃，与句意相悖。"}, "sentence_index": 0, "correct_answer": "淬炼"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "铁匠用锤子淬炼一把新剑。", "explanation": "这里应该用〈锻造〉。淬炼指把烧红的金属放入水中急速冷却，锤打成形要用锻造。"}, {"text": "工人把矿石放进炉子里淬炼。", "explanation": "这里应该用〈煅烧〉。淬炼是放入水中冷却，不是在炉中加热矿石，此处应该用煅烧。"}, {"text": "师傅用砂纸淬炼刀刃。", "explanation": "这里应该用〈打磨〉。淬炼是热处理工艺，不是用砂纸磨光表面，此处应该用打磨。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eaf93011-0e90-41ac-ab22-ff49726bb7fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23886, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "淬炼", "is_correct": true, "explanation": "正确：“淬炼铁器”指把烧红的铁器放入水中冷却使其变硬，与句意相符。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”的对象是食物，铁器不能被吃，句意不通。"}, {"text": "打扮", "is_correct": false, "explanation": "搭配：“打扮”多用于人或橱窗、房间等，不用于铁器的加工。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”的对象是歌曲或戏曲，不能唱铁器。"}], "explanations": {"淬炼": "正确：“淬炼铁器”指把烧红的铁器放入水中冷却使其变硬，与句意相符。", "吃": "语义：“吃”的对象是食物，铁器不能被吃，句意不通。", "打扮": "搭配：“打扮”多用于人或橱窗、房间等，不用于铁器的加工。", "唱": "语义：“唱”的对象是歌曲或戏曲，不能唱铁器。"}, "sentence_index": 6, "correct_answer": "淬炼"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "陶匠用窑炉淬炼陶器。", "explanation": "这里应该用〈烧制〉。淬炼指把烧热的金属放入水中使其变硬，陶器在窑中烧成要用烧制。"}, {"text": "工人用焊枪把两根管子淬炼在一起。", "explanation": "这里应该用〈焊接〉。淬炼是热处理，不能把两个物件连接在一起，此处应该用焊接。"}, {"text": "妈妈在烤箱里淬炼面包。", "explanation": "这里应该用〈烘烤〉。淬炼指给金属降温使其变硬，不用于烤面包，此处应该用烘烤。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eaf93011-0e90-41ac-ab22-ff49726bb7fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23886, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块铁淬炼很硬。", "corrected_sentence": "这块铁淬炼得很硬。", "error_description": "错误在于缺少补语标记“得”：“淬炼”后应接“得”引出补语，说“淬炼得很硬”，不能省略“得”而直接说“淬炼很硬”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eaf93011-0e90-41ac-ab22-ff49726bb7fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23886, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "明天我们会淬炼了这批钢件。", "corrected_sentence": "明天我们会淬炼这批钢件。", "error_description": "错误在于“淬炼”后多加了“了”。句中有“明天”和“会”，说的是将来，不能用“了”，应去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eaf93011-0e90-41ac-ab22-ff49726bb7fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
