INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23896, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "两个事物、说法或人之间互相对立、互相冲突，比如一个人说要去，又说不要去；也指人与人、国家之间的分歧。", "primary_collocate": null, "pronunciation": "máo dùn", "ipa": "mɑʊ˧˥ twən˥˩", "syllable_count": 2, "sentences": [{"text": "他的话里有矛盾。", "target_word": "矛盾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个说法之间有矛盾。", "target_word": "矛盾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们之间有一点矛盾。", "target_word": "矛盾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学之间有矛盾，要好好谈一谈。", "target_word": "矛盾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师帮我们解决了矛盾。", "target_word": "矛盾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她心里有很多矛盾。", "target_word": "矛盾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份报告里有一个矛盾。", "target_word": "矛盾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个国家的矛盾越来越大。", "target_word": "矛盾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友之间出现矛盾，别着急。", "target_word": "矛盾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要想办法减少矛盾。", "target_word": "矛盾", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "事物、说法或人之间互相冲突、互相反对，或存在分歧", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0b36993-6be1-4beb-8bc2-c6c37fd0d0a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23896, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "矛盾", "is_correct": true, "explanation": "矛盾：指说法之间互相冲突，与「他的话里有」搭配，符合句意。"}, {"text": "河流", "is_correct": false, "explanation": "语义：「河流」是自然界的水道，不能存在于「话里」。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：「身高」描述人的外形，不能说「话里有身高」。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：「窗户」是建筑的一部分，不可能出现在「话里」。"}], "explanations": {"矛盾": "矛盾：指说法之间互相冲突，与「他的话里有」搭配，符合句意。", "河流": "语义：「河流」是自然界的水道，不能存在于「话里」。", "身高": "体貌：「身高」描述人的外形，不能说「话里有身高」。", "窗户": "语义：「窗户」是建筑的一部分，不可能出现在「话里」。"}, "sentence_index": 0, "correct_answer": "矛盾"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这把椅子有矛盾，需要修理。", "explanation": "这里应该用〈松动〉。矛盾指事物或说法之间互相冲突，椅子不稳要用松动。"}, {"text": "墙上挂着一个矛盾。", "explanation": "这里应该用〈画〉。矛盾指事物之间互相对立的关系，是抽象的，不能像画一样挂在墙上。"}, {"text": "这家餐厅的菜矛盾得很好吃。", "explanation": "这里应该用〈美味〉。矛盾指事物之间互相对立，不能用来形容菜的味道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c70bd67-1f70-4fec-9ce1-5b472ee1565d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23896, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "矛盾", "is_correct": true, "explanation": "矛盾：指报告中互相冲突的地方，与「有一个」搭配，符合句意。"}, {"text": "房子", "is_correct": false, "explanation": "语义：「房子」是建筑物，报告里不可能有房子。"}, {"text": "猫", "is_correct": false, "explanation": "语义：「猫」是动物，不能出现在报告里。"}, {"text": "八卦", "is_correct": false, "explanation": "语域：「八卦」是口语化的闲话，不适合用在书面报告中。"}], "explanations": {"矛盾": "矛盾：指报告中互相冲突的地方，与「有一个」搭配，符合句意。", "房子": "语义：「房子」是建筑物，报告里不可能有房子。", "猫": "语义：「猫」是动物，不能出现在报告里。", "八卦": "语域：「八卦」是口语化的闲话，不适合用在书面报告中。"}, "sentence_index": 6, "correct_answer": "矛盾"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台电风扇出现矛盾，需要维修。", "explanation": "这里应该用〈故障〉。矛盾指事物或说法之间互相冲突，电风扇不转要用故障。"}, {"text": "他这次犯了一个矛盾。", "explanation": "这里应该用〈错误〉。「犯」搭配的是错误，矛盾不能被「犯」。"}, {"text": "他的牙齿有矛盾，疼了一天。", "explanation": "这里应该用〈蛀牙〉。矛盾指事物之间互相对立，不能用来指身体上的毛病。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c70bd67-1f70-4fec-9ce1-5b472ee1565d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23896, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两个说法之间曾经存在了矛盾。", "corrected_sentence": "这两个说法之间曾经存在过矛盾。", "error_description": "错误：体标「过」用错。表示曾经有过的经历应用「过」，「存在了」表示已经出现的变化，与「曾经」不协调。正确应说「存在过矛盾」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c70bd67-1f70-4fec-9ce1-5b472ee1565d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23896, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份合同里有一条矛盾。", "corrected_sentence": "这份合同里有一个矛盾。", "error_description": "错误：量词用错了。矛盾应该用「个」，「条」用于细长的东西，不能用来计量矛盾。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c70bd67-1f70-4fec-9ce1-5b472ee1565d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
