INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23898, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "所有部分都相同的样子。", "primary_collocate": null, "pronunciation": "tǒng yī xìng", "ipa": "tʰʊŋ˨˩ i˥ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "这条街的房子有很强的统一性。", "target_word": "统一性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两本书的封面缺乏统一性。", "target_word": "统一性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校要求校服保持统一性。", "target_word": "统一性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这套杯子在大小和样子上都有很强的统一性。", "target_word": "统一性", "complexity_tier": "T3", "furigana": "tǒng yī xìng", "sentence_source": "generated"}, {"text": "这个小区的楼房在外观上很有统一性。", "target_word": "统一性", "complexity_tier": "T3", "furigana": "tǒng yī xìng", "sentence_source": "generated"}, {"text": "画里的颜色看起来很有统一性。", "target_word": "统一性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家穿同样的衣服，显得很有统一性。", "target_word": "统一性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些桌子的高度没有统一性。", "target_word": "统一性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我喜欢这套碗，它们的样式很有统一性。", "target_word": "统一性", "complexity_tier": "T3", "furigana": "tǒng yī xìng", "sentence_source": "generated"}, {"text": "桌上的花瓶没有统一性，有大有小。", "target_word": "统一性", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "統一性", "label": "繁体"}, {"form": "统一", "label": "词根"}, {"form": "统一体", "label": "复合词"}], "register": "书面", "sense_fingerprint": "各个部分样子完全相同的特点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '549d97fa-a22a-48f3-802f-0d64c12db3ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23898, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "统一性", "is_correct": true, "explanation": "正确。“很强的统一性”指房屋外观的一致程度，与句意相合。"}, {"text": "攻击性", "is_correct": false, "explanation": "语义：“攻击性”指对外的冲击倾向，用来形容房屋外观不合语境。"}, {"text": "导电性", "is_correct": false, "explanation": "搭配：“房子”不谈“导电性”，二者搭配不当。"}, {"text": "时效性", "is_correct": false, "explanation": "语义：“时效性”指在一定时期内有效，与描述房屋外观的语境无关。"}], "explanations": {"统一性": "正确。“很强的统一性”指房屋外观的一致程度，与句意相合。", "攻击性": "语义：“攻击性”指对外的冲击倾向，用来形容房屋外观不合语境。", "导电性": "搭配：“房子”不谈“导电性”，二者搭配不当。", "时效性": "语义：“时效性”指在一定时期内有效，与描述房屋外观的语境无关。"}, "sentence_index": 0, "correct_answer": "统一性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这套杯子在大小和样子上都很统一性。", "explanation": "这里应该用形容词〈一样〉。“统一性”是名词，不能直接用“很”修饰作谓语，“大小和样子上都很一样”才自然。"}, {"text": "这套杯子在大小上有一只统一性。", "explanation": "量词用错。“只”用于动物或成对的物品，不能计量“统一性”这类抽象名词，这里应该用〈种〉。"}, {"text": "这套杯子各不相同，每只都有很强的统一性。", "explanation": "这里应该用〈独特性〉。“统一性”指所有部分都相同，与“各不相同”正好相反；说每件都与众不同，应用〈独特性〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eaf93011-0e90-41ac-ab22-ff49726bb7fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23898, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "统一性", "is_correct": true, "explanation": "正确。“显得很有统一性”指大家穿同样的衣服所呈现的一致效果，与句意相合。"}, {"text": "多样性", "is_correct": false, "explanation": "语义：“多样性”指形式繁多，与“穿同样的衣服”的语境正相反。"}, {"text": "差异性", "is_correct": false, "explanation": "搭配：“差异性”常与“不同”“各异”连用，与“同样”不搭配。"}, {"text": "独特性", "is_correct": false, "explanation": "语义：“独特性”指与众不同的特点，与大家穿同样衣服的情形相悖。"}], "explanations": {"统一性": "正确。“显得很有统一性”指大家穿同样的衣服所呈现的一致效果，与句意相合。", "多样性": "语义：“多样性”指形式繁多，与“穿同样的衣服”的语境正相反。", "差异性": "搭配：“差异性”常与“不同”“各异”连用，与“同样”不搭配。", "独特性": "语义：“独特性”指与众不同的特点，与大家穿同样衣服的情形相悖。"}, "sentence_index": 6, "correct_answer": "统一性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他这个人很有统一性，前后说的话总是不一样。", "explanation": "这里应该用〈善变〉。“统一性”指所有部分都相同，此处说的是前后说法不同，应说〈善变〉。"}, {"text": "工人搬运了桌子的统一性。", "explanation": "这里应该用〈物品〉作宾语。〈搬运〉的对象是具体物品，“统一性”是抽象特征，不能被搬运。"}, {"text": "我们要把桌子的样式统一性起来。", "explanation": "这里应该用动词〈统一〉。“统一性”是名词，不能接“起来”作补语，“把样式统一起来”才正确。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eaf93011-0e90-41ac-ab22-ff49726bb7fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23898, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这排路灯的样式很有统一。", "corrected_sentence": "这排路灯的样式很有统一性。", "error_description": "“统一性”是名词，“性”不能省略；去掉“性”后，“统一”不能作“有”的宾语。应为“很有统一性”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eaf93011-0e90-41ac-ab22-ff49726bb7fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23898, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些杯子的统一性强很，大小和样式都一样。", "corrected_sentence": "这些杯子的统一性很强，大小和样式都一样。", "error_description": "“很”应放在形容词“强”前面，说“统一性很强”；“统一性强很”的语序不对，“很”不能放在“强”后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eaf93011-0e90-41ac-ab22-ff49726bb7fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23900, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '286cee17-2cf1-4c71-9582-97def2f7a317') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23900, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '286cee17-2cf1-4c71-9582-97def2f7a317') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23900, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "东西像水一样容易流来流去的性质。", "primary_collocate": null, "pronunciation": "liú dòng xìng", "ipa": "ljou̯˧˥ tʊŋ˥˩ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "水的流动性很好。", "target_word": "流动性", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "油比水黏，流动性差一些。", "target_word": "流动性", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "蜂蜜的流动性比牛奶差。", "target_word": "流动性", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "天气冷了，油的流动性变差了。", "target_word": "流动性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "沙子很细的时候，也有一点流动性。", "target_word": "流动性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "热巧克力酱的流动性很强，能慢慢流下来。", "target_word": "流动性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种墨水流动性好，写字很顺畅。", "target_word": "流动性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "加水以后，泥浆的流动性变大了。", "target_word": "流动性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "火山的岩浆流动性强，流得很快很远。", "target_word": "流动性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种涂料的流动性太好，刷在墙上会往下流。", "target_word": "流动性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "流動性", "label": "繁体"}, {"form": "流动", "label": "词根"}], "register": "通用", "sense_fingerprint": "液体或类似液体的物质容易流动的性质", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfbd5d03-db38-4b5a-b66d-53264770e077') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23900, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "形状", "is_correct": false, "explanation": "语义：水没有固定的形状，“形状”与“很好”的评价不搭配。"}, {"text": "重量", "is_correct": false, "explanation": "搭配：说水的好坏不用“重量”，“水的重量很好”不通。"}, {"text": "流动性", "is_correct": true, "explanation": "“流动性”指液体容易流动的性质，水的流动性好，语境相合。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“年龄”只用于人或生物，不能说水的年龄。"}], "explanations": {"形状": "语义：水没有固定的形状，“形状”与“很好”的评价不搭配。", "重量": "搭配：说水的好坏不用“重量”，“水的重量很好”不通。", "流动性": "“流动性”指液体容易流动的性质，水的流动性好，语境相合。", "年龄": "搭配：“年龄”只用于人或生物，不能说水的年龄。"}, "sentence_index": 0, "correct_answer": "流动性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "河水的流动性很快，几分钟就冲到了下游。", "explanation": "这里应该用〈流速〉。流动性指液体容易流动的性质，形容水流快慢要说“流速”，不能说流动性。"}, {"text": "这块石头的流动性很高，锤子都敲不碎。", "explanation": "这里应该用〈硬度〉。流动性指东西容易像水一样流动的性质，石头是固体，说它的坚硬程度要用“硬度”，不能说流动性。"}, {"text": "这块铁的流动性很大，放在水里会沉下去。", "explanation": "这里应该用〈密度〉。流动性指液体容易流动的性质，说铁放进水里沉不沉要用“密度”，铁是固体，不能说流动性。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '286cee17-2cf1-4c71-9582-97def2f7a317') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23900, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "身份", "is_correct": false, "explanation": "语义：“身份”指人的社会地位，墨水没有身份。"}, {"text": "学历", "is_correct": false, "explanation": "搭配：“学历”只用于人，不能用于墨水。"}, {"text": "流动性", "is_correct": true, "explanation": "“流动性”好指墨水容易流动，写字才会顺畅，语境相合。"}, {"text": "辈分", "is_correct": false, "explanation": "语义：“辈分”指人际或家族中的代际关系，与墨水无关。"}], "explanations": {"身份": "语义：“身份”指人的社会地位，墨水没有身份。", "学历": "搭配：“学历”只用于人，不能用于墨水。", "流动性": "“流动性”好指墨水容易流动，写字才会顺畅，语境相合。", "辈分": "语义：“辈分”指人际或家族中的代际关系，与墨水无关。"}, "sentence_index": 6, "correct_answer": "流动性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家公司的流动性很差，资金周转不开。", "explanation": "这里的“流动性”指资金周转和变现的能力，属于金融义项，不是液体流动的性质；这里应该用〈周转能力〉。"}, {"text": "市场上的流动性突然收紧，银行借钱变难了。", "explanation": "这里的“流动性”指金融市场上的资金充裕程度，属于金融义项，不是液体流动的性质；这里应该用〈资金面〉。"}, {"text": "这家企业的流动性不足，只好卖掉了厂房。", "explanation": "这里的“流动性”指资产变现的能力，属于金融义项，不是液体流动的性质；这里应该用〈变现能力〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '286cee17-2cf1-4c71-9582-97def2f7a317') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23900, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种油漆的流动性好很，刷起来很均匀。", "corrected_sentence": "这种油漆的流动性很好，刷起来很均匀。", "error_description": "语序错误：程度副词“很”应放在形容词“好”前面，应说“流动性很好”，不能说“流动性好很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '286cee17-2cf1-4c71-9582-97def2f7a317') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23900, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只流动性很强，涂料很快就流下来了。", "corrected_sentence": "这种流动性很强，涂料很快就流下来了。", "error_description": "量词错误：“流动性”的量词应用“种”，说“这种流动性”；“只”多用于动物或单件物品，不能用来计量这个词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '286cee17-2cf1-4c71-9582-97def2f7a317') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
