INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23902, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "别人相信你，听你的话。", "primary_collocate": null, "pronunciation": "quán wēi", "ipa": "tɕʰyɛn˧˥ wei˥", "syllable_count": 2, "sentences": [{"text": "老师在学生心中很有权威。", "target_word": "权威", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "校长的权威来自大家的信任。", "target_word": "权威", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在团队里很有权威，大家都愿意听他的。", "target_word": "权威", "complexity_tier": "T3", "furigana": "tā zài tuánduì lǐ hěn yǒu quánwēi, dàjiā dōu yuànyì tīng tā de.", "sentence_source": "generated"}, {"text": "妈妈很有权威，孩子们都听她的。", "target_word": "权威", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他说的话很有权威，没人不相信。", "target_word": "权威", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师的权威让教室里很安静。", "target_word": "权威", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "谁也不能怀疑医生的权威。", "target_word": "权威", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "不要为了权威而不听别人的意见。", "target_word": "权威", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们应该相信专家，因为他们有权威。", "target_word": "权威", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在公司里建立了自己的权威。", "target_word": "权威", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "权威性", "label": "复合"}, {"form": "權威", "label": "繁体"}], "register": "中性", "sense_fingerprint": "让人信服、使人听从的威信和地位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf9dc599-3173-4820-a892-52e831b34649') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23902, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "权威", "is_correct": true, "explanation": "权威指让人信服、值得听从的威信，老师在学生心中有这种地位，所以说很有权威。"}, {"text": "力气", "is_correct": false, "explanation": "语义：「力气」指身体的力量，与学生心中的威信无关。"}, {"text": "面积", "is_correct": false, "explanation": "搭配：「面积」用于平面或地域，不能说「心中很有面积」。"}, {"text": "体型", "is_correct": false, "explanation": "体貌：「体型」指身体的外形，不用来说人在学生心中的地位。"}], "explanations": {"权威": "权威指让人信服、值得听从的威信，老师在学生心中有这种地位，所以说很有权威。", "力气": "语义：「力气」指身体的力量，与学生心中的威信无关。", "面积": "搭配：「面积」用于平面或地域，不能说「心中很有面积」。", "体型": "体貌：「体型」指身体的外形，不用来说人在学生心中的地位。"}, "sentence_index": 0, "correct_answer": "权威"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他走路很权威，大家都让他先走。", "explanation": "这里应该用〈威风〉。权威指让人信服、值得听从的威信，不能用来形容走路的样子；形容走路气派应说〈威风〉。"}, {"text": "这个笑话很权威，大家都笑了。", "explanation": "这里应该用〈有趣〉。权威指让人信服、值得听从的威信，笑话的好坏要用〈有趣〉来说明。"}, {"text": "这间教室的权威只有十平方米。", "explanation": "这里应该用〈面积〉。权威指让人信服的威信，不能用平方米来衡量；说房间大小要用〈面积〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8790e4c8-b8b8-4a42-8c87-e897bb8be11a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23902, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "权威", "is_correct": true, "explanation": "权威：指令人信服的威信，谁也不怀疑医生在专业上的威信。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：「颜色」是视觉上的属性，与医生的可信度无关，不能被怀疑。"}, {"text": "味道", "is_correct": false, "explanation": "语义：「味道」指口感或气味，不能用来怀疑医生。"}, {"text": "辈分", "is_correct": false, "explanation": "语义：「辈分」指代际次序，与医生在专业上的威信无关，句意不通。"}], "explanations": {"权威": "权威：指令人信服的威信，谁也不怀疑医生在专业上的威信。", "颜色": "语义：「颜色」是视觉上的属性，与医生的可信度无关，不能被怀疑。", "味道": "语义：「味道」指口感或气味，不能用来怀疑医生。", "辈分": "语义：「辈分」指代际次序，与医生在专业上的威信无关，句意不通。"}, "sentence_index": 6, "correct_answer": "权威"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块石头的权威有三公斤。", "explanation": "这里应该用〈重量〉。权威指让人信服的威信，不能用公斤来计量；说石头的轻重要用〈重量〉。"}, {"text": "这盘菜的权威太咸了，没法吃。", "explanation": "这里应该用〈味道〉。权威指人或机构让人信服的威信，不能用来说食物咸淡；评价口味要说〈味道〉。"}, {"text": "他把权威剪短了，看起来精神多了。", "explanation": "这里应该用〈头发〉。权威是抽象的威信，不能剪；把头发剪短要说〈头发〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8790e4c8-b8b8-4a42-8c87-e897bb8be11a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23902, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在公司里打了自己的权威。", "corrected_sentence": "他在公司里树立了自己的权威。", "error_description": "错误：「打」不能与「权威」搭配。表示建立威信要用「树立」或「建立」，应说「树立了自己的权威」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8790e4c8-b8b8-4a42-8c87-e897bb8be11a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23902, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "张老师在这个领域有很权威。", "corrected_sentence": "张老师在这个领域很有权威。", "error_description": "错误：副词「很」的位置错误。「很」应放在「有」前面，说「很有权威」，「有很权威」不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8790e4c8-b8b8-4a42-8c87-e897bb8be11a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
