INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23908, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西送给别人。", "primary_collocate": null, "pronunciation": "shòu yǔ", "ipa": "ʂoʊ˥˩ y˨˩˦", "syllable_count": 2, "sentences": [{"text": "老师授予每个学生一张荣誉证书。", "target_word": "授予", "complexity_tier": "T3", "furigana": "lǎoshī shòuyǔ měi gè xuéshēng yì zhāng róngyù zhèngshū", "sentence_source": "generated"}, {"text": "校长把一张奖状授予了小明。", "target_word": "授予", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛结束后，主办方授予冠军一个奖杯。", "target_word": "授予", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司授予新员工一枚荣誉胸章。", "target_word": "授予", "complexity_tier": "T3", "furigana": "gōngsī shòuyǔ xīn yuángōng yì méi róngyù xiōngzhāng", "sentence_source": "generated"}, {"text": "村民授予老医生一面锦旗。", "target_word": "授予", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校长授予每位毕业生一枚纪念奖牌。", "target_word": "授予", "complexity_tier": "T3", "furigana": "xiàozhǎng shòuyǔ měi wèi bìyèshēng yì méi jìniàn jiǎngpái", "sentence_source": "generated"}, {"text": "馆长授予这位朋友一枚纪念徽章。", "target_word": "授予", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "俱乐部授予新会员一份入会证书。", "target_word": "授予", "complexity_tier": "T3", "furigana": "jùlèbù shòuyǔ xīn huìyuán yí fèn rùhuì zhèngshū", "sentence_source": "generated"}, {"text": "老教练授予队长一块金牌。", "target_word": "授予", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校授予获奖同学一枚奖章。", "target_word": "授予", "complexity_tier": "T3", "furigana": "xuéxiào shòuyǔ huòjiǎng tóngxué yì méi jiǎngzhāng", "sentence_source": "generated"}], "morphological_forms": [{"form": "授予了", "label": "体标"}, {"form": "授予过", "label": "体标"}], "register": "书面", "sense_fingerprint": "正式地把具体物品交给别人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f1c9b64-cfef-45a7-8659-93a59137a1df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23908, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "授予", "is_correct": true, "explanation": "授予 shòu yǔ：正式地把物品交给别人，是本词条的目标词。"}, {"text": "手语", "is_correct": false, "explanation": "shǒu（第三声）与 shòu（第四声）声调不同，手语指用手势交流的语言。"}, {"text": "术语", "is_correct": false, "explanation": "shù 与 shòu 的韵母不同（u 与 ou），术语指专业领域的固定词语。"}, {"text": "骤雨", "is_correct": false, "explanation": "zhòu（第四声）与 shòu（第四声）声母不同（zh 与 sh），骤雨指突然而猛烈的雨。"}], "explanations": {"授予": "授予 shòu yǔ：正式地把物品交给别人，是本词条的目标词。", "手语": "shǒu（第三声）与 shòu（第四声）声调不同，手语指用手势交流的语言。", "术语": "shù 与 shòu 的韵母不同（u 与 ou），术语指专业领域的固定词语。", "骤雨": "zhòu（第四声）与 shòu（第四声）声母不同（zh 与 sh），骤雨指突然而猛烈的雨。"}, "sentence_index": null, "correct_answer": "授予"}, "level_3": {"options": [{"text": "授予", "is_correct": true, "explanation": "正确：“授予”指正式把物品交给对方，与“每个学生一张证书”相合。"}, {"text": "撕", "is_correct": false, "explanation": "语义：“撕”是撕毁，与把荣誉证书发给学生的语境相反。"}, {"text": "扣", "is_correct": false, "explanation": "搭配：“扣”多用于扣分、扣工资，不能扣“荣誉证书”。"}, {"text": "嘲笑", "is_correct": false, "explanation": "配价：“嘲笑”的对象是人，不能带“荣誉证书”作宾语。"}], "explanations": {"授予": "正确：“授予”指正式把物品交给对方，与“每个学生一张证书”相合。", "撕": "语义：“撕”是撕毁，与把荣誉证书发给学生的语境相反。", "扣": "搭配：“扣”多用于扣分、扣工资，不能扣“荣誉证书”。", "嘲笑": "配价：“嘲笑”的对象是人，不能带“荣誉证书”作宾语。"}, "sentence_index": 0, "correct_answer": "授予"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "店主授予了顾客一笔费用。", "explanation": "这里应该用〈收取〉。“授予”是把东西无偿交给对方，向顾客收费要用“收取”。"}, {"text": "朋友授予了我一个拥抱。", "explanation": "这里应该用〈给〉。“授予”指正式把具体物品交给对方，拥抱不是能交付的物品，表达亲密动作要用“给”。"}, {"text": "他授予我一个想法。", "explanation": "这里应该用〈传达〉。“授予”的对象必须是可以交付的具体东西，想法不能被“送给”别人，表达想法要用“传达”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b036a8f5-9068-4757-82b6-347580cf1231') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23908, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "授予", "is_correct": true, "explanation": "正确：“授予”指正式把纪念徽章交给朋友，与“馆长……这位朋友一枚纪念徽章”相合。"}, {"text": "摔", "is_correct": false, "explanation": "语义：“摔”是打碎、摔坏，与馆长把纪念徽章送给朋友的语境相反。"}, {"text": "讥讽", "is_correct": false, "explanation": "配价：“讥讽”的对象是人，不能再带“纪念徽章”作宾语。"}, {"text": "拆", "is_correct": false, "explanation": "搭配：“拆”用于拆开包装、信件，不用来描述把纪念徽章交给别人。"}], "explanations": {"授予": "正确：“授予”指正式把纪念徽章交给朋友，与“馆长……这位朋友一枚纪念徽章”相合。", "摔": "语义：“摔”是打碎、摔坏，与馆长把纪念徽章送给朋友的语境相反。", "讥讽": "配价：“讥讽”的对象是人，不能再带“纪念徽章”作宾语。", "拆": "搭配：“拆”用于拆开包装、信件，不用来描述把纪念徽章交给别人。"}, "sentence_index": 6, "correct_answer": "授予"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生授予了病人一个诊断。", "explanation": "这里应该用〈告知〉。“授予”是把实物交给对方，诊断结果不是物品，要用“告知”。"}, {"text": "强盗授予了她的钱包。", "explanation": "这里应该用〈抢走〉。“授予”是自愿、正式地交给对方，不能用于抢夺他人财物。"}, {"text": "窃贼授予了我的手表。", "explanation": "这里应该用〈偷走〉。“授予”是自愿交付，窃取财物要用“偷走”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b036a8f5-9068-4757-82b6-347580cf1231') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23908, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师授予小红一条纪念册。", "corrected_sentence": "老师授予小红一本纪念册。", "error_description": "错误在于量词：“纪念册”应使用量词“本”，不能用“条”（“条”多用于细长之物）。应说“老师授予小红一本纪念册”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b036a8f5-9068-4757-82b6-347580cf1231') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23908, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "公司授予他了一份纪念品。", "corrected_sentence": "公司授予了他一份纪念品。", "error_description": "“了”位置错误：完成体“了”应紧跟动词“授予”，应说“授予了他”，不能放在“他”后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b036a8f5-9068-4757-82b6-347580cf1231') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
