INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23916, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让东西看起来平平的，没有凸起来。", "primary_collocate": null, "pronunciation": "biǎn píng huà", "ipa": "pjɛn˨˩˦ pʰiŋ˧˥ xwa˥˩", "syllable_count": 3, "sentences": [{"text": "照片把这座山扁平化了，看不出高低。", "target_word": "扁平化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "设计师把按钮扁平化，去掉了阴影。", "target_word": "扁平化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "正面强光会让人脸扁平化，失去立体感。", "target_word": "扁平化", "complexity_tier": "T3", "furigana": "zhèngmiàn qiángguāng huì ràng rénliǎn biǎnpínghuà, shīqù lìtǐgǎn", "sentence_source": "generated"}, {"text": "这张海报把建筑扁平化，没有明暗层次。", "target_word": "扁平化", "complexity_tier": "T3", "furigana": "zhè zhāng hǎibào bǎ jiànzhù biǎnpínghuà, méiyǒu míng''àn céngcì", "sentence_source": "generated"}, {"text": "这种画法使树木扁平化，缺少立体感。", "target_word": "扁平化", "complexity_tier": "T3", "furigana": "zhè zhǒng huàfǎ shǐ shùmù biǎnpínghuà, quēshǎo lìtǐgǎn", "sentence_source": "generated"}, {"text": "屏幕会让立体的东西变得扁平化。", "target_word": "扁平化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把人物插画扁平化，线条更简洁。", "target_word": "扁平化", "complexity_tier": "T3", "furigana": "tā bǎ rénwù chāhuà biǎnpínghuà, xiàntiáo gèng jiǎnjié", "sentence_source": "generated"}, {"text": "图标扁平化后，边上的阴影不见了。", "target_word": "扁平化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做地图时，要先把山形扁平化。", "target_word": "扁平化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个软件能把三维模型扁平化。", "target_word": "扁平化", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "扁平化了", "label": "体标"}], "register": "书面", "sense_fingerprint": "使物体或画面变平，失去立体感", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f1c9b64-cfef-45a7-8659-93a59137a1df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23916, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "扁平化", "is_correct": true, "explanation": "正确：“扁平化”指使画面变平、看不出高低，与句意相合。"}, {"text": "立体化", "is_correct": false, "explanation": "语义：“立体化”是使山显出高低、有立体感，与“看不出高低”相矛盾。"}, {"text": "拉高", "is_correct": false, "explanation": "语义：“拉高”是把山变得更高，与“看不出高低”的结果矛盾。"}, {"text": "挖空", "is_correct": false, "explanation": "搭配：“挖空”指从内部掏空，不用来描述照片对山的处理。"}], "explanations": {"扁平化": "正确：“扁平化”指使画面变平、看不出高低，与句意相合。", "立体化": "语义：“立体化”是使山显出高低、有立体感，与“看不出高低”相矛盾。", "拉高": "语义：“拉高”是把山变得更高，与“看不出高低”的结果矛盾。", "挖空": "搭配：“挖空”指从内部掏空，不用来描述照片对山的处理。"}, "sentence_index": 0, "correct_answer": "扁平化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把两边的重量扁平化了。", "explanation": "这里应该用〈平衡〉。“扁平化”指让东西看起来平平的、没有凸起，两边的重量要用“平衡”。"}, {"text": "他扁平化了文章的段落。", "explanation": "这里应该用〈删减〉。“扁平化”指使画面变平、失去立体感，不是删去内容。"}, {"text": "他扁平化了文件的体积。", "explanation": "这里应该用〈压缩〉。“扁平化”不能用来指缩小体积，压缩要用“压缩”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b036a8f5-9068-4757-82b6-347580cf1231') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23916, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "扁平化", "is_correct": true, "explanation": "正确：“扁平化”指把人物插画处理得平面简洁，与“线条更简洁”相合。"}, {"text": "复杂化", "is_correct": false, "explanation": "语义：“复杂化”是变得繁复，与“线条更简洁”相矛盾。"}, {"text": "撕", "is_correct": false, "explanation": "语义：“撕”是撕毁，与对插画的加工处理语境不符，也与“线条更简洁”不相合。"}, {"text": "涂抹", "is_correct": false, "explanation": "搭配：“涂抹”多用于颜料、墙面，不用来描述对插画整体的处理。"}], "explanations": {"扁平化": "正确：“扁平化”指把人物插画处理得平面简洁，与“线条更简洁”相合。", "复杂化": "语义：“复杂化”是变得繁复，与“线条更简洁”相矛盾。", "撕": "语义：“撕”是撕毁，与对插画的加工处理语境不符，也与“线条更简洁”不相合。", "涂抹": "搭配：“涂抹”多用于颜料、墙面，不用来描述对插画整体的处理。"}, "sentence_index": 6, "correct_answer": "扁平化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他扁平化了西瓜的甜度。", "explanation": "这里应该用〈提高〉。“扁平化”只指让物体显得平、没有凸起，不能用来说甜度，甜度的增加要用“提高”。"}, {"text": "店主扁平化了店铺的面积。", "explanation": "这里应该用〈扩大〉。“扁平化”指使画面变平、失去立体感，不能用来指增加面积。"}, {"text": "他扁平化了视频的时长。", "explanation": "这里应该用〈缩短〉。“扁平化”不能用来指减少时长，缩短时间要用“缩短”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b036a8f5-9068-4757-82b6-347580cf1231') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23916, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "画家把这幅肖像扁平化地了。", "corrected_sentence": "画家把这幅肖像扁平化了。", "error_description": "“地”误用：“地”是状语标记，不能插在“扁平化”和“了”之间。应说“画家把这幅肖像扁平化了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b036a8f5-9068-4757-82b6-347580cf1231') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23916, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人把画面扁平化了了。", "corrected_sentence": "工人把画面扁平化了。", "error_description": "“了”重复：完成体“了”只需一个，已放在动词“扁平化”后面，多加一个“了”是错误的。应说“工人把画面扁平化了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b036a8f5-9068-4757-82b6-347580cf1231') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
