INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23918, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一个团队或国家里最重要的人，大家听他的话。", "primary_collocate": null, "pronunciation": "lǐng xiù", "ipa": "liŋ˨˩˦ ɕjoʊ˥˩", "syllable_count": 2, "sentences": [{"text": "我们队的领袖是小王，大家都听他的。", "target_word": "领袖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很有魅力，是我们小组的领袖。", "target_word": "领袖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的领袖会先听大家的想法。", "target_word": "领袖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个团队需要一位真正的领袖。", "target_word": "领袖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们都把他当成班里的领袖。", "target_word": "领袖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她年纪不大，却成了公司的领袖。", "target_word": "领袖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "遇到困难时，领袖要站出来。", "target_word": "领袖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家选他做小队的领袖。", "target_word": "领袖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位领袖说话很清楚，也很有力量。", "target_word": "领袖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁是你们社团的领袖？", "target_word": "领袖", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "領袖", "label": "繁体"}, {"form": "意见领袖", "label": "复合"}], "register": "书面", "sense_fingerprint": "团队里最重要、大家都听从的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f1c9b64-cfef-45a7-8659-93a59137a1df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23918, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "领袖", "is_correct": true, "explanation": "领袖：团队里大家都听从的人，“我们队的领袖是小王”句意通顺。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：“冰箱”是家电，不能指团队里的人，“我们队的冰箱是小王”句意不通。"}, {"text": "食堂", "is_correct": false, "explanation": "语义：“食堂”是场所，不能指人，与“大家都听他的”矛盾，句子不通。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“年龄”不能用“我们队的年龄是小王”这种说法。"}], "explanations": {"领袖": "领袖：团队里大家都听从的人，“我们队的领袖是小王”句意通顺。", "冰箱": "语义：“冰箱”是家电，不能指团队里的人，“我们队的冰箱是小王”句意不通。", "食堂": "语义：“食堂”是场所，不能指人，与“大家都听他的”矛盾，句子不通。", "年龄": "搭配：“年龄”不能用“我们队的年龄是小王”这种说法。"}, "sentence_index": 0, "correct_answer": "领袖"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个团队的领袖是一把椅子，大家都坐在它上面。", "explanation": "这里的领袖指团队中大家听他话的人，是人，不是家具，不能说成椅子。"}, {"text": "这个团队的领袖今年才三岁，还不会说话。", "explanation": "这里的领袖应是能带领团队、让大家听他话的人，三岁幼儿不能指挥大家。"}, {"text": "这个团队的领袖是一根木头，放在门口。", "explanation": "这里的领袖指人，不是木头，不能把领袖说成一根木头放在门口。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b036a8f5-9068-4757-82b6-347580cf1231') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23918, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "领袖", "is_correct": true, "explanation": "领袖：团队里大家听从的带头人，“遇到困难时，领袖要站出来”句意通顺。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“石头”不是人，不能“站出来”带领大家，句子不通。"}, {"text": "地图", "is_correct": false, "explanation": "语义：“地图”是物品，不能“站出来”，句子不通。"}, {"text": "空气", "is_correct": false, "explanation": "配价：“站出来”需要有生命的主语，“空气”不能主动站出来。"}], "explanations": {"领袖": "领袖：团队里大家听从的带头人，“遇到困难时，领袖要站出来”句意通顺。", "石头": "语义：“石头”不是人，不能“站出来”带领大家，句子不通。", "地图": "语义：“地图”是物品，不能“站出来”，句子不通。", "空气": "配价：“站出来”需要有生命的主语，“空气”不能主动站出来。"}, "sentence_index": 6, "correct_answer": "领袖"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "谁把你们社团的领袖放进了冰箱？", "explanation": "这里的领袖指团队中大家听他话的人，是人，不能放进冰箱。"}, {"text": "这台电脑的领袖坏了，谁能修一下？", "explanation": "电脑的零件不叫领袖，领袖指团队中大家听他话的人。"}, {"text": "你们社团的领袖今天下雨了吗？", "explanation": "这里的领袖指人，不能用来说天气，下雨的是天气而不是领袖。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b036a8f5-9068-4757-82b6-347580cf1231') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23918, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们班选出了一只新领袖。", "corrected_sentence": "我们班选出了一位新领袖。", "error_description": "量词错误：“领袖”指人，应用量词“位”计数，“只”多用于动物，应改为“一位新领袖”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b036a8f5-9068-4757-82b6-347580cf1231') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23918, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们组推选出一条新领袖。", "corrected_sentence": "我们组推选出一位新领袖。", "error_description": "量词错误：“领袖”指人，应用量词“位”计数，“条”用于细长的东西，不能用于人。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b036a8f5-9068-4757-82b6-347580cf1231') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
