INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23920, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让吵架的两个人不再吵架，和好。", "primary_collocate": null, "pronunciation": "tiáo jiě", "ipa": "tʰjɑʊ˧˥ tɕjɛ˨˩˦", "syllable_count": 2, "sentences": [{"text": "他们吵架了，妈妈在中间调解。", "target_word": "调解", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师来调解，两个孩子和好了。", "target_word": "调解", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "姐姐从中调解，我和朋友又和好了。", "target_word": "调解", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷最会调解家人之间的争吵。", "target_word": "调解", "complexity_tier": "T3", "furigana": "yé ye zuì huì tiáo jiě jiā rén zhī jiān de zhēng chǎo", "sentence_source": "generated"}, {"text": "邻居吵起来了，大家都来调解。", "target_word": "调解", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们吵得很凶，没人敢去调解。", "target_word": "调解", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "同事吵架时，经理出来调解了一下。", "target_word": "调解", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我请她来调解我和哥哥的争吵。", "target_word": "调解", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶一调解，两家人就不吵了。", "target_word": "调解", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友们吵架了，你去调解一下吧。", "target_word": "调解", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "调解了", "label": "体标"}, {"form": "调解调解", "label": "重叠"}, {"form": "调解员", "label": "复合"}], "register": "中性", "sense_fingerprint": "调解：劝吵架的人和好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '397a99f4-7813-4bc2-8e8d-66e04969afa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23920, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "调解", "is_correct": true, "explanation": "正确答案：调解（tiáo jiě），指劝吵架的人和好。"}, {"text": "调节", "is_correct": false, "explanation": "jiě（第三声）与 jié（第二声）声调不同，调节意思是调整使其适当。"}, {"text": "了解", "is_correct": false, "explanation": "liǎo（第三声）与 tiáo（第二声）声母和声调都不同，了解意思是知道、明白。"}, {"text": "老姐", "is_correct": false, "explanation": "lǎo（第三声）与 tiáo（第二声）声母和声调都不同，老姐意思是姐姐，口语用法。"}], "explanations": {"调解": "正确答案：调解（tiáo jiě），指劝吵架的人和好。", "调节": "jiě（第三声）与 jié（第二声）声调不同，调节意思是调整使其适当。", "了解": "liǎo（第三声）与 tiáo（第二声）声母和声调都不同，了解意思是知道、明白。", "老姐": "lǎo（第三声）与 tiáo（第二声）声母和声调都不同，老姐意思是姐姐，口语用法。"}, "sentence_index": null, "correct_answer": "调解"}, "level_3": {"options": [{"text": "调解", "is_correct": true, "explanation": "正确：句中“他们吵架了”说明有争执，妈妈在中间让两人和好，即调解。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：吵架时妈妈在中间睡觉，与前文的劝和语境不合。"}, {"text": "散步", "is_correct": false, "explanation": "语义：吵架时在中间散步，与“在中间”的居中劝和意义不符。"}, {"text": "比赛", "is_correct": false, "explanation": "搭配：“比赛”要有对手或场地，不说“在中间比赛”。"}], "explanations": {"调解": "正确：句中“他们吵架了”说明有争执，妈妈在中间让两人和好，即调解。", "睡觉": "语义：吵架时妈妈在中间睡觉，与前文的劝和语境不合。", "散步": "语义：吵架时在中间散步，与“在中间”的居中劝和意义不符。", "比赛": "搭配：“比赛”要有对手或场地，不说“在中间比赛”。"}, "sentence_index": 0, "correct_answer": "调解"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "空调调解室内温度。", "explanation": "这里应该用〈调节〉。调解是让吵架的人和好，调整温度、流量等要用调节。"}, {"text": "妈妈调解孩子写作业。", "explanation": "这里应该用〈陪伴〉。调解是让吵架的人和好，陪孩子写作业要用陪伴。"}, {"text": "这位老师调解了迟到的学生。", "explanation": "这里应该用〈批评〉。调解是让吵架的人和好，学生迟到要用批评。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aba9b977-9c6a-4780-927e-2733c92d52a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23920, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "调解", "is_correct": true, "explanation": "正确答案：调解（tiáo jiě），指劝吵架的人和好。"}, {"text": "小姐", "is_correct": false, "explanation": "xiǎo（第三声）与 tiáo（第二声）声母和声调都不同，小姐意思是年轻女子。"}, {"text": "条件", "is_correct": false, "explanation": "jiàn（第四声）与 jiě（第三声）韵母与声调不同，条件意思是情况或前提。"}, {"text": "调减", "is_correct": false, "explanation": "jiǎn（第三声）与 jiě（第三声）韵母不同，调减意思是下调、减少。"}], "explanations": {"调解": "正确答案：调解（tiáo jiě），指劝吵架的人和好。", "小姐": "xiǎo（第三声）与 tiáo（第二声）声母和声调都不同，小姐意思是年轻女子。", "条件": "jiàn（第四声）与 jiě（第三声）韵母与声调不同，条件意思是情况或前提。", "调减": "jiǎn（第三声）与 jiě（第三声）韵母不同，调减意思是下调、减少。"}, "sentence_index": null, "correct_answer": "调解"}, "level_3": {"options": [{"text": "调解", "is_correct": true, "explanation": "正确：同事吵架时经理出面劝和，即调解了一下。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：吵架时经理出来打扫，与劝和的语境不合。"}, {"text": "修车", "is_correct": false, "explanation": "语义：吵架时经理出来修车，与前文的人际矛盾不相关。"}, {"text": "拍照", "is_correct": false, "explanation": "搭配：“拍照一下”需要拍摄对象，不与吵架的场面搭配。"}], "explanations": {"调解": "正确：同事吵架时经理出面劝和，即调解了一下。", "打扫": "语义：吵架时经理出来打扫，与劝和的语境不合。", "修车": "语义：吵架时经理出来修车，与前文的人际矛盾不相关。", "拍照": "搭配：“拍照一下”需要拍摄对象，不与吵架的场面搭配。"}, "sentence_index": 6, "correct_answer": "调解"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "奶奶调解生病的孩子。", "explanation": "这里应该用〈照顾〉。调解是让吵架的人和好，照顾生病的孩子要用照顾。"}, {"text": "他调解了坏掉的自行车。", "explanation": "这里应该用〈修理〉。调解是让吵架的人和好，修理坏掉的东西要用修理。"}, {"text": "厨师调解了那道菜的咸淡。", "explanation": "这里应该用〈调味〉。调解是让吵架的人和好，给菜调整咸淡要用调味。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aba9b977-9c6a-4780-927e-2733c92d52a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_e