INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23920, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "爸爸成功调解着我和哥哥的争吵。", "corrected_sentence": "爸爸成功调解了我和哥哥的争吵。", "error_description": "体标错误：“成功调解”是已完成的动作，应用“了”；“着”表示持续状态，与已完成的动作不合。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aba9b977-9c6a-4780-927e-2733c92d52a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23920, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈早就调解过这对兄弟着。", "corrected_sentence": "妈妈早就调解过这对兄弟了。", "error_description": "体标错误：“过”标示曾经发生的经历，“着”标示持续状态；“早就……过”指已完成的经历，“着”不合，应改为“调解过这对兄弟了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aba9b977-9c6a-4780-927e-2733c92d52a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
