INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23922, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "对别人好，愿意帮助有困难的人。", "primary_collocate": null, "pronunciation": "cí shàn", "ipa": "tsʰɨ˧˥ ʂan˥˩", "syllable_count": 2, "sentences": [{"text": "她心地慈善，常把食物分给有困难的人。", "target_word": "慈善", "complexity_tier": "T3", "furigana": "tā xīn dì cí shàn, cháng bǎ shí wù fēn gěi yǒu kùn nan de rén.", "sentence_source": "generated"}, {"text": "王奶奶心肠慈善，常常帮助邻居。", "target_word": "慈善", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位医生心地慈善，总愿意帮助穷人。", "target_word": "慈善", "complexity_tier": "T3", "furigana": "zhè wèi yī shēng xīn dì cí shàn, zǒng yuàn yì bāng zhù qióng rén.", "sentence_source": "generated"}, {"text": "他心肠慈善，孩子们都喜欢他。", "target_word": "慈善", "complexity_tier": "T3", "furigana": "tā xīn cháng cí shàn, hái zi men dōu xǐ huan tā.", "sentence_source": "generated"}, {"text": "那位老板心地慈善，给工人加了工资。", "target_word": "慈善", "complexity_tier": "T3", "furigana": "nà wèi lǎo bǎn xīn dì cí shàn, gěi gōng rén jiā le gōng zī.", "sentence_source": "generated"}, {"text": "那位老太太心地慈善，见了乞丐就给钱。", "target_word": "慈善", "complexity_tier": "T3", "furigana": "nà wèi lǎo tài tai xīn dì cí shàn, jiàn le qǐ gài jiù gěi qián.", "sentence_source": "generated"}, {"text": "她心地慈善，连流浪的小狗也照顾。", "target_word": "慈善", "complexity_tier": "T3", "furigana": "tā xīn dì cí shàn, lián liú làng de xiǎo gǒu yě zhào gù.", "sentence_source": "generated"}, {"text": "我的外婆心肠慈善，从不骂人。", "target_word": "慈善", "complexity_tier": "T3", "furigana": "wǒ de wài pó xīn cháng cí shàn, cóng bú mà rén.", "sentence_source": "generated"}, {"text": "校长心地慈善，常为学生着想。", "target_word": "慈善", "complexity_tier": "T3", "furigana": "xiào zhǎng xīn dì cí shàn, cháng wèi xué sheng zhuó xiǎng.", "sentence_source": "generated"}, {"text": "这个老人心地慈善，总是给乞丐饭吃。", "target_word": "慈善", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "慈善家", "label": "复合"}, {"form": "慈善机构", "label": "复合"}], "register": "中性", "sense_fingerprint": "形容人心地善良、乐于帮助困难者", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caac8116-bbb0-40db-b2bd-488d2c40e0ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23922, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "慈善", "is_correct": true, "explanation": "正确：慈善形容心地好、乐于助人，与常把食物分给困难者的情节一致。"}, {"text": "冷漠", "is_correct": false, "explanation": "语义：冷漠指对人漠不关心，与把食物分给有困难的人相悖，句子讲不通。"}, {"text": "刻薄", "is_correct": false, "explanation": "语义：刻薄指待人苛刻，与主动分食物给困难者的情节矛盾。"}, {"text": "漂亮", "is_correct": false, "explanation": "搭配：“漂亮”多用于外貌或事物，不能说“心地漂亮”，搭配不当。"}], "explanations": {"慈善": "正确：慈善形容心地好、乐于助人，与常把食物分给困难者的情节一致。", "冷漠": "语义：冷漠指对人漠不关心，与把食物分给有困难的人相悖，句子讲不通。", "刻薄": "语义：刻薄指待人苛刻，与主动分食物给困难者的情节矛盾。", "漂亮": "搭配：“漂亮”多用于外貌或事物，不能说“心地漂亮”，搭配不当。"}, "sentence_index": 0, "correct_answer": "慈善"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的脸色很慈善，孩子们都喜欢他。", "explanation": "这里应该用〈和善〉。和善形容神色、态度；慈善指对人关怀、助人的心地与行为，不用来形容脸色。"}, {"text": "她的声音很慈善，孩子们都爱听。", "explanation": "这里应该用〈温柔〉。温柔形容声音、性情的柔和；慈善指对人关怀、助人的心地与行为，不用来形容声音。"}, {"text": "他脾气慈善，孩子们都有点怕他。", "explanation": "这里应该用〈温和〉。温和形容脾气、性情；慈善指对人关怀、助人的心地与行为，不用来形容脾气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1290d92c-e7b4-47b3-ad92-00364367db95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23922, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "慈善", "is_correct": true, "explanation": "正确：慈善形容心地善良、乐于助人，与连流浪小狗也照顾的情节一致。"}, {"text": "狠毒", "is_correct": false, "explanation": "语义：狠毒指心肠恶毒，与后面照顾流浪小狗的情节相悖。"}, {"text": "冷酷", "is_correct": false, "explanation": "语义：冷酷指无情，与照顾流浪小狗的行为相矛盾。"}, {"text": "粗壮", "is_correct": false, "explanation": "体貌：粗壮形容人的体格强壮，不能用来形容心地。"}], "explanations": {"慈善": "正确：慈善形容心地善良、乐于助人，与连流浪小狗也照顾的情节一致。", "狠毒": "语义：狠毒指心肠恶毒，与后面照顾流浪小狗的情节相悖。", "冷酷": "语义：冷酷指无情，与照顾流浪小狗的行为相矛盾。", "粗壮": "体貌：粗壮形容人的体格强壮，不能用来形容心地。"}, "sentence_index": 6, "correct_answer": "慈善"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个老人的字迹很慈善，总是给乞丐饭吃。", "explanation": "这里应该用〈工整〉。工整形容字迹规矩；慈善指对人关怀、助人的心地与行为，不用来形容字迹。"}, {"text": "这个老人的脚步很慈善，总是给乞丐饭吃。", "explanation": "这里应该用〈轻快〉。轻快形容步态、动作；慈善指对人关怀、助人的心地与行为，不用来形容脚步。"}, {"text": "这个老人的房间很慈善，总是给乞丐饭吃。", "explanation": "这里应该用〈整洁〉。整洁形容房间、环境；慈善指对人关怀、助人的心地与行为，不用来形容房间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1290d92c-e7b4-47b3-ad92-00364367db95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23922, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她心地很很慈善，常把食物分给有困难的人。", "corrected_sentence": "她心地很慈善，常把食物分给有困难的人。", "error_description": "叠用错误：程度副词“很”不能重复，应说“心地很慈善”，“很很”不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1290d92c-e7b4-47b3-ad92-00364367db95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23922, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位老人心地慈善家，每天都给流浪猫喂食。", "corrected_sentence": "这位老人心地慈善，每天都给流浪猫喂食。", "error_description": "词性错误：“慈善家”是名词，指从事慈善事业的人，不能用在“心地”后作谓语；应说“心地慈善”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1290d92c-e7b4-47b3-ad92-00364367db95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23924, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eaf93011-0e90-41ac-ab22-ff49726bb7fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
