INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23924, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "生来就有的本领。", "primary_collocate": null, "pronunciation": "tiān fù", "ipa": "tʰjɛn˥ fu˥˩", "syllable_count": 2, "sentences": [{"text": "小鸟天生会飞，这是它的天赋。", "target_word": "天赋", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他有一种打篮球的天赋。", "target_word": "天赋", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小明的天赋是记住人的名字。", "target_word": "天赋", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家都说她跳舞很有天赋。", "target_word": "天赋", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个小男孩有做饭的天赋。", "target_word": "天赋", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天赋不够，也可以靠练习补上。", "target_word": "天赋", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他学什么都快，真是有天赋。", "target_word": "天赋", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的天赋是一听就会唱。", "target_word": "天赋", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "弟弟没有学过画画，却有这方面的天赋。", "target_word": "天赋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说我们每个人都有自己的天赋。", "target_word": "天赋", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "天賦", "label": "繁体"}], "register": "中性", "sense_fingerprint": "生来就有的本领", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '549d97fa-a22a-48f3-802f-0d64c12db3ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23924, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "天赋", "is_correct": true, "explanation": "正确答案：天赋（tiān fù），指生来就有的本领。"}, {"text": "颠覆", "is_correct": false, "explanation": "diān（第一声）与 tiān 声母不同（d/t），意思是推翻、打倒。"}, {"text": "肩负", "is_correct": false, "explanation": "jiān（第一声）与 tiān 声母不同（j/t），意思是承担责任。"}, {"text": "担负", "is_correct": false, "explanation": "dān（第一声）与 tiān 声母不同（d/t），意思是承担（任务、责任）。"}, {"text": "天路", "is_correct": false, "explanation": "lù（第四声）与 fù 声母不同（l/f），意思是通往高原或天上的道路。"}], "explanations": {"天赋": "正确答案：天赋（tiān fù），指生来就有的本领。", "颠覆": "diān（第一声）与 tiān 声母不同（d/t），意思是推翻、打倒。", "肩负": "jiān（第一声）与 tiān 声母不同（j/t），意思是承担责任。", "担负": "dān（第一声）与 tiān 声母不同（d/t），意思是承担（任务、责任）。", "天路": "lù（第四声）与 fù 声母不同（l/f），意思是通往高原或天上的道路。"}, "sentence_index": null, "correct_answer": "天赋"}, "level_3": {"options": [{"text": "天赋", "is_correct": true, "explanation": "正确：“它的天赋”指生来的本领，与“天生会飞”相符，句意通顺。"}, {"text": "习惯", "is_correct": false, "explanation": "语义：“习惯”是后天养成的，与“天生会飞”相反，句意矛盾。"}, {"text": "经验", "is_correct": false, "explanation": "语义：“经验”是靠实践积累的，与“天生”相反，句意矛盾。"}, {"text": "训练", "is_correct": false, "explanation": "搭配：“训练”是后天的过程，不能用来指“天生”的本领，搭配不当。"}], "explanations": {"天赋": "正确：“它的天赋”指生来的本领，与“天生会飞”相符，句意通顺。", "习惯": "语义：“习惯”是后天养成的，与“天生会飞”相反，句意矛盾。", "经验": "语义：“经验”是靠实践积累的，与“天生”相反，句意矛盾。", "训练": "搭配：“训练”是后天的过程，不能用来指“天生”的本领，搭配不当。"}, "sentence_index": 0, "correct_answer": "天赋"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她养成了早睡的天赋。", "explanation": "这里应该用〈习惯〉。天赋是生来的本领，不能“养成”，早睡要说习惯。"}, {"text": "他积累了十年的工作天赋。", "explanation": "这里应该用〈经验〉。天赋是天生的，不能靠积累获得，积累工作的体会要用经验。"}, {"text": "她练就了跳舞的天赋。", "explanation": "这里应该用〈技艺〉。天赋是生来就有的才能，不能靠练就得到，练成的舞蹈功夫应该用技艺。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eaf93011-0e90-41ac-ab22-ff49726bb7fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23924, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天赋", "is_correct": true, "explanation": "正确：“真是有天赋”指生来有学习的本领，与“学什么都快”相符。"}, {"text": "钱", "is_correct": false, "explanation": "语义：“有钱”说的是财力，与“学什么都快”的能力无关。"}, {"text": "时间", "is_correct": false, "explanation": "语义：“有时间”说的是空闲，与“学什么都快”的能力无关。"}, {"text": "毛病", "is_correct": false, "explanation": "搭配：“有毛病”指有缺点，与“学什么都快”的称赞语气不搭配。"}], "explanations": {"天赋": "正确：“真是有天赋”指生来有学习的本领，与“学什么都快”相符。", "钱": "语义：“有钱”说的是财力，与“学什么都快”的能力无关。", "时间": "语义：“有时间”说的是空闲，与“学什么都快”的能力无关。", "毛病": "搭配：“有毛病”指有缺点，与“学什么都快”的称赞语气不搭配。"}, "sentence_index": 6, "correct_answer": "天赋"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她天赋开朗，很乐观。", "explanation": "这里应该用〈性格〉。天赋指生来的本领，不能用来形容性格，此处应该用性格。"}, {"text": "他的天赋很急躁，常常发火。", "explanation": "这里应该用〈脾气〉。天赋指本领，不能用来形容性情，此处应该用脾气。"}, {"text": "这段天赋让他明白了很多道理。", "explanation": "这里应该用〈经历〉。天赋指生来的本领，不指亲身经过的事情，此处应该用经历。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eaf93011-0e90-41ac-ab22-ff49726bb7fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23924, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些孩子都有自己的天赋们。", "corrected_sentence": "这些孩子都有自己的天赋。", "error_description": "错误在于给抽象名词“天赋”加了复数后缀“们”。“天赋”不加“们”，说“这些孩子都有自己的天赋”即可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eaf93011-0e90-41ac-ab22-ff49726bb7fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23924, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个小女孩有一只唱歌的天赋。", "corrected_sentence": "这个小女孩有一种唱歌的天赋。", "error_description": "错误在于量词：“天赋”的量词是“种”，“只”多用于动物，不能修饰天赋，应改为“一种唱歌的天赋”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eaf93011-0e90-41ac-ab22-ff49726bb7fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
