INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23930, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6e9e744-4847-4ffa-9912-38d63166b1ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23930, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "看完前面的说法，可以得出后面的结果。", "primary_collocate": null, "pronunciation": "yóu cǐ guān zhī", "ipa": "joʊ˧˥ tsʰɹ̩˨˩˦ kwan˥ ʈʂɹ̩˥", "syllable_count": 4, "sentences": [{"text": "他一直很早到公司，由此观之，他很负责。", "target_word": "由此观之", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们都爱吃这道菜，由此观之，它一定好吃。", "target_word": "由此观之", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天和今天的雨都很大，由此观之，这个月雨水多。", "target_word": "由此观之", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书卖得很快，由此观之，大家都喜欢它。", "target_word": "由此观之", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李帮了每个同事，由此观之，他是个热心人。", "target_word": "由此观之", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地上全是水，由此观之，昨晚下过大雨。", "target_word": "由此观之", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每天读书两小时，由此观之，她的中文会越来越好。", "target_word": "由此观之", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车站里人很少，由此观之，今天不是假期。", "target_word": "由此观之", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人每天都笑着，由此观之，他过得很开心。", "target_word": "由此观之", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说的和做的不一样，由此观之，不能全信他。", "target_word": "由此观之", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "由此觀之", "label": "繁体"}], "register": "书面", "sense_fingerprint": "由此观之：看完前面的说法，得出后面的结果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bff508bb-4dd4-4d17-9788-2be285a2506d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23930, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "可是", "is_correct": false, "explanation": "语义：“可是”表示转折，前后句并不对立，不合语境。"}, {"text": "不过", "is_correct": false, "explanation": "语义：“不过”同样表示转折，与“很早到公司，所以很负责”的顺承关系不符。"}, {"text": "尽管", "is_correct": false, "explanation": "搭配：“尽管”需要与“却”“也”呼应，这里后面没有相应的结构。"}, {"text": "由此观之", "is_correct": true, "explanation": "由此观之：看完前面的说法，得出“他很负责”的结果，与句意相符。"}], "explanations": {"可是": "语义：“可是”表示转折，前后句并不对立，不合语境。", "不过": "语义：“不过”同样表示转折，与“很早到公司，所以很负责”的顺承关系不符。", "尽管": "搭配：“尽管”需要与“却”“也”呼应，这里后面没有相应的结构。", "由此观之": "由此观之：看完前面的说法，得出“他很负责”的结果，与句意相符。"}, "sentence_index": 0, "correct_answer": "由此观之"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本书的内容很好，由此观之，卖得不快。", "explanation": "这里应该用〈然而〉。由此观之表示从前文推出结论，不能用来引出转折。"}, {"text": "由此观之，他已经吃完饭，我们要先去看电影。", "explanation": "这里应该用〈首先〉。由此观之表示看完前面的说法后得出结果，不能用来列出先做的事。"}, {"text": "他写完作业，由此观之，去睡觉。", "explanation": "这里应该用〈然后〉。由此观之表示推论，不能用来表示动作的先后顺序。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6e9e744-4847-4ffa-9912-38d63166b1ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23930, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "然而", "is_correct": false, "explanation": "语义：“然而”表示转折，与“每天读书两小时”推出的结果相反，句意不通。"}, {"text": "否则", "is_correct": false, "explanation": "语义：“否则”表示相反的假设后果，与前文的努力和进步不符。"}, {"text": "只是", "is_correct": false, "explanation": "搭配：“只是”需要前文有保留或让步，这里前后没有对应的关系。"}, {"text": "由此观之", "is_correct": true, "explanation": "由此观之：根据“每天读书两小时”推出“中文会越来越好”，与句意相符。"}], "explanations": {"然而": "语义：“然而”表示转折，与“每天读书两小时”推出的结果相反，句意不通。", "否则": "语义：“否则”表示相反的假设后果，与前文的努力和进步不符。", "只是": "搭配：“只是”需要前文有保留或让步，这里前后没有对应的关系。", "由此观之": "由此观之：根据“每天读书两小时”推出“中文会越来越好”，与句意相符。"}, "sentence_index": 6, "correct_answer": "由此观之"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工作已经做完了，由此观之，他还读了一本书。", "explanation": "这里应该用〈另外〉。由此观之表示推论，不能用来补充一件并列的事。"}, {"text": "会议结束了，由此观之，大家一起合了影。", "explanation": "这里应该用〈最后〉。由此观之表示推论，不能用来表示事情的最后一步。"}, {"text": "由此观之，夏天的时候，我们去海边游泳了。", "explanation": "这里应该用〈于是〉。由此观之表示推论，不能用来表示动作的因果承接。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6e9e744-4847-4ffa-9912-38d63166b1ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23930, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他每周都去健身房，由此观之了，他很重视健康。", "corrected_sentence": "他每周都去健身房，由此观之，他很重视健康。", "error_description": "“由此观之”后加了“了”：该词是连词，不能带体标记，应去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6e9e744-4847-4ffa-9912-38d63166b1ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23930, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他连续三周都准时参加会议，由此观之，所以他很守纪律。", "corrected_sentence": "他连续三周都准时参加会议，由此观之，他很守纪律。", "error_description": "“由此观之”已经表示结论，后面不应再加“所以”；两者重复，应去掉“所以”，说“由此观之，他很守纪律”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6e9e744-4847-4ffa-9912-38d63166b1ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
