INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23932, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "达到了最好的情况，没有比这个更好的了。", "primary_collocate": null, "pronunciation": "jí zhì", "ipa": "tɕi˧˥ ʈʂʐ̩˥˩", "syllable_count": 2, "sentences": [{"text": "这家店的服务已经到了极致。", "target_word": "极致", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她把舞蹈跳到了极致。", "target_word": "极致", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这顿饭让我感受到了味道的极致。", "target_word": "极致", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位设计师追求极致的细节。", "target_word": "极致", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这台相机拍出了极致的画质。", "target_word": "极致", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们把环保做到了极致。", "target_word": "极致", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "躺在家里的沙发上，就是舒服的极致。", "target_word": "极致", "complexity_tier": "T3", "furigana": "jí zhì", "sentence_source": "generated"}, {"text": "爸爸对干净的要求到了极致。", "target_word": "极致", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这幅画把细节表现到了极致。", "target_word": "极致", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想要成功，就要把每件小事做到极致。", "target_word": "极致", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "极致的", "label": "定语形式"}, {"form": "极致体验", "label": "复合"}], "register": "中性", "sense_fingerprint": "极致|达到最好、没有比这更好的了", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f96f18b6-c394-4703-a301-fe5590358afb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23932, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "极致", "is_correct": true, "explanation": "jí zhì（第二声、第四声）即本词，指达到了最好的境况，没有比这更好的了。"}, {"text": "机制", "is_correct": false, "explanation": "机制 jī zhì 与 jí zhì 只有第一音节声调不同（jī 第一声，jí 第二声），意思是事物内部的构造与运行方式。"}, {"text": "集市", "is_correct": false, "explanation": "集市 jí shì 与 jí zhì 只有第二音节声母不同（sh 与 zh），意思是定期聚集交易的市场。"}, {"text": "极值", "is_correct": false, "explanation": "极值 jí zhí 与 jí zhì 只有第二音节声调不同（zhí 第二声，zhì 第四声），意思是数学上的极大或极小值。"}], "explanations": {"极致": "jí zhì（第二声、第四声）即本词，指达到了最好的境况，没有比这更好的了。", "机制": "机制 jī zhì 与 jí zhì 只有第一音节声调不同（jī 第一声，jí 第二声），意思是事物内部的构造与运行方式。", "集市": "集市 jí shì 与 jí zhì 只有第二音节声母不同（sh 与 zh），意思是定期聚集交易的市场。", "极值": "极值 jí zhí 与 jí zhì 只有第二音节声调不同（zhí 第二声，zhì 第四声），意思是数学上的极大或极小值。"}, "sentence_index": null, "correct_answer": "极致"}, "level_3": {"options": [{"text": "极致", "is_correct": true, "explanation": "与上下文相符：“到了极致”表示服务达到了最好的程度，是固定说法。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“服务到了价格”不成话，句意要求的是程度，而不是价钱。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：服务不能“到了颜色”，与句意不符。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“到了年龄”搭配的是人或事物的年限，“服务到了年龄”不符合习惯说法。"}], "explanations": {"极致": "与上下文相符：“到了极致”表示服务达到了最好的程度，是固定说法。", "价格": "语义：“服务到了价格”不成话，句意要求的是程度，而不是价钱。", "颜色": "语义：服务不能“到了颜色”，与句意不符。", "年龄": "搭配：“到了年龄”搭配的是人或事物的年限，“服务到了年龄”不符合习惯说法。"}, "sentence_index": 0, "correct_answer": "极致"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次比赛出现了一个极致的错误。", "explanation": "这里应该用〈严重〉。极致指达到最好的情况，只能形容好的事物；错误是负面的，要用严重。"}, {"text": "这次比赛他的失误降到了极致。", "explanation": "这里应该用〈最低〉。极致指最高程度，不能用于表示失误降到最低。"}, {"text": "这条小路已经走到了极致，前面就是大海。", "explanation": "这里应该用〈尽头〉。极致指程度上的最高，不指路的终点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd438de31-d2f2-4485-ba1f-d93681089655') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23932, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "极致", "is_correct": true, "explanation": "jí zhì（第二声、第四声）即本词，指达到了最好的境况，没有比这更好的了。"}, {"text": "直至", "is_correct": false, "explanation": "直至 zhí zhì 与 jí zhì 只有第一音节声母不同（zh 与 j），意思是一直到某个时间或程度。"}, {"text": "节制", "is_correct": false, "explanation": "节制 jié zhì 与 jí zhì 只有第一音节韵母不同（ie 与 i），意思是控制、有所约束。"}, {"text": "基质", "is_correct": false, "explanation": "基质 jī zhì 与 jí zhì 只有第一音节声调不同（jī 第一声，jí 第二声），意思是物质的基础成分。"}], "explanations": {"极致": "jí zhì（第二声、第四声）即本词，指达到了最好的境况，没有比这更好的了。", "直至": "直至 zhí zhì 与 jí zhì 只有第一音节声母不同（zh 与 j），意思是一直到某个时间或程度。", "节制": "节制 jié zhì 与 jí zhì 只有第一音节韵母不同（ie 与 i），意思是控制、有所约束。", "基质": "基质 jī zhì 与 jí zhì 只有第一音节声调不同（jī 第一声，jí 第二声），意思是物质的基础成分。"}, "sentence_index": null, "correct_answer": "极致"}, "level_3": {"options": [{"text": "极致", "is_correct": true, "explanation": "与上下文相符：“舒服的极致”指舒适达到了最高程度。"}, {"text": "账单", "is_correct": false, "explanation": "语义：“舒服的账单”与句中的“躺在沙发上”的舒适感无关，句意不通。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“舒服”多形容身体或环境的感受，不能说“舒服的体重”。"}, {"text": "字母", "is_correct": false, "explanation": "语义：“舒服的字母”与句中描述的舒适情境毫不相关。"}], "explanations": {"极致": "与上下文相符：“舒服的极致”指舒适达到了最高程度。", "账单": "语义：“舒服的账单”与句中的“躺在沙发上”的舒适感无关，句意不通。", "体重": "搭配：“舒服”多形容身体或环境的感受，不能说“舒服的体重”。", "字母": "语义：“舒服的字母”与句中描述的舒适情境毫不相关。"}, "sentence_index": 6, "correct_answer": "极致"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的做法太极致了，大家都受不了。", "explanation": "这里应该用〈极端〉。极致指达到最好的境界，多带褒义；做法过激、令人难以接受要用极端。"}, {"text": "他的兴趣已经减到了极致。", "explanation": "这里应该用〈零〉。极致指最高程度，兴趣减少到几乎消失时应说减少到零。"}, {"text": "这座山我们已经爬到了极致，再往上就没路了。", "explanation": "这里应该用〈尽头〉。极致指程度上的最高，不指地点的终点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd438de31-d2f2-4485-ba1f-d93681089655') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23932, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这顿饭的味道已经了极致。", "corrected_sentence": "这顿饭的味道已经到了极致。", "error_description": "错误在于“到”被省略。“到了极致”中的“到”不能省，应说“已经到了极致”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd438de31-d2f2-4485-ba1f-d93681089655') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23932, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她把书法练了极致。", "corrected_sentence": "她把书法练到了极致。", "error_description": "错误在于“练到”的补语“到”被省略。应说“练到了极致”，表示练习达到最高水平。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd438de31-d2f2-4485-ba1f-d93681089655') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
