INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23938, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用来做事情的工具或机器。", "primary_collocate": null, "pronunciation": "shè bèi", "ipa": "ʂɤ˥˩ pei˥˩", "syllable_count": 2, "sentences": [{"text": "这家工厂的设备很新。", "target_word": "设备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院买了一台新设备。", "target_word": "设备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套设备能帮工人做很重的工作。", "target_word": "设备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "设备坏了，工人正在修理。", "target_word": "设备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教室里的设备有电脑和投影仪。", "target_word": "设备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动场的设备很齐全。", "target_word": "设备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "使用这些设备以前，要先看说明书。", "target_word": "设备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司花了很多钱买实验设备。", "target_word": "设备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要乱动房间里的设备。", "target_word": "设备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个体育馆的设备让大家很满意。", "target_word": "设备", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一台设备", "label": "量词"}, {"form": "一套设备", "label": "量词"}, {"form": "医疗设备", "label": "复合"}, {"form": "設備", "label": "繁体"}], "register": "中性", "sense_fingerprint": "工作或生产中使用的机器、工具和装置", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c432fe6-4db2-4f87-8eb1-bd238a86f80d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23938, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "设备", "is_correct": true, "explanation": "正确：“这家工厂的设备”指工厂使用的机器和工具，可以说“很新”。"}, {"text": "心情", "is_correct": false, "explanation": "语义：心情是人的感受，工厂不会有“很新”的心情，句意不通。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不属于工厂，也不说“这家工厂的天空很新”。"}, {"text": "水平", "is_correct": false, "explanation": "搭配：“水平”不用“新”来形容，应说“高”或“低”。"}], "explanations": {"设备": "正确：“这家工厂的设备”指工厂使用的机器和工具，可以说“很新”。", "心情": "语义：心情是人的感受，工厂不会有“很新”的心情，句意不通。", "天空": "语义：天空不属于工厂，也不说“这家工厂的天空很新”。", "水平": "搭配：“水平”不用“新”来形容，应说“高”或“低”。"}, "sentence_index": 0, "correct_answer": "设备"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的设备很和气，学生都喜欢他。", "explanation": "这里应该用〈老师〉。设备是机器和工具，不会和气待人，句子的主语应指人，如“老师很和气”。"}, {"text": "战士们穿好了设备，准备出发。", "explanation": "这里应该用〈装备〉。装备可以穿戴，说“穿好了装备”；设备指机器和仪器，不能穿。"}, {"text": "妈妈做好了设备，等我们回家吃饭。", "explanation": "这里是把〈设备〉误当成〈饭菜〉的意思。设备指机器和工具，不能做成饭菜，应说“做好了饭菜”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8872be9-c801-4bb0-b205-2f8a454cec2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23938, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "设备", "is_correct": true, "explanation": "正确：“使用这些设备”指使用机器和工具，使用前要看说明书，与句意相符。"}, {"text": "食物", "is_correct": false, "explanation": "语义：食物是用来吃的，不是需要先看说明书才能“使用”的东西。"}, {"text": "心情", "is_correct": false, "explanation": "语义：心情是人的感受，不能被“使用”，句中的语境不合。"}, {"text": "节目", "is_correct": false, "explanation": "搭配：“节目”一般说“看节目”“播节目”，不说“使用节目”。"}], "explanations": {"设备": "正确：“使用这些设备”指使用机器和工具，使用前要看说明书，与句意相符。", "食物": "语义：食物是用来吃的，不是需要先看说明书才能“使用”的东西。", "心情": "语义：心情是人的感受，不能被“使用”，句中的语境不合。", "节目": "搭配：“节目”一般说“看节目”“播节目”，不说“使用节目”。"}, "sentence_index": 6, "correct_answer": "设备"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个体育馆的设备唱得很好听。", "explanation": "这里应该用〈歌手〉。设备是机器和工具，不会唱歌，句子的施事不能是设备。"}, {"text": "这个体育馆的设备很年轻。", "explanation": "这里应该用〈工作人员〉。“年轻”形容人，设备应说“新”。"}, {"text": "我们在这个体育馆的设备里踢足球。", "explanation": "这里应该用〈场地〉。设备是机器和工具，不是可以进去踢球的地方，应说“在场地里”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8872be9-c801-4bb0-b205-2f8a454cec2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23938, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们公司新买了一只设备。", "corrected_sentence": "我们公司新买了一台设备。", "error_description": "错误形式：“一只设备”；正确形式：“一台设备”。“只”用于动物等个体，设备多为机器，应使用量词“台”或“套”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8872be9-c801-4bb0-b205-2f8a454cec2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23938, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们把设备安装了好。", "corrected_sentence": "他们把设备安装好了。", "error_description": "错误形式：“安装了好”；正确形式：“安装好了”。结果补语“好”应紧跟动词“安装”，“了”放在补语后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8872be9-c801-4bb0-b205-2f8a454cec2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23942, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd438de31-d2f2-4485-ba1f-d93681089655') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
