INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23942, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "某样东西属于谁，就是谁的。", "primary_collocate": null, "pronunciation": "guī shǔ", "ipa": "kweɪ˥ ʂu˨˩˦", "syllable_count": 2, "sentences": [{"text": "这辆自行车归属于学校宿舍，别随便骑走。", "target_word": "归属", "complexity_tier": "T3", "furigana": "guī shǔ", "sentence_source": "generated"}, {"text": "公园里的花草都归属于国家。", "target_word": "归属", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那本旧词典归属于图书馆，不能卖。", "target_word": "归属", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这张桌子归属于谁，请你问问老师。", "target_word": "归属", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们吵了很久，不知道这块表归属于谁。", "target_word": "归属", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "合同上写着，这套房子归属于妻子。", "target_word": "归属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些玩具归属于幼儿园，小朋友可以借来玩。", "target_word": "归属", "complexity_tier": "T3", "furigana": "guī shǔ", "sentence_source": "generated"}, {"text": "这张照片归属于摄影社，社员不能私自转发。", "target_word": "归属", "complexity_tier": "T3", "furigana": "guī shǔ", "sentence_source": "generated"}, {"text": "这笔钱归属于公司，不是个人的。", "target_word": "归属", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校的操场归属于全校同学。", "target_word": "归属", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "归属于", "label": "搭配"}], "register": "中性", "sense_fingerprint": "东西属于谁就是谁的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f96f18b6-c394-4703-a301-fe5590358afb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23942, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "归属", "is_correct": true, "explanation": "正确：“归属于学校宿舍”表示车辆属于宿舍，与“别随便骑走”一致。"}, {"text": "忠于", "is_correct": false, "explanation": "语义：车辆不能“忠于”宿舍，与语境不符。"}, {"text": "等于", "is_correct": false, "explanation": "语义：“等于”表示相等，不表示东西属于谁。"}, {"text": "陷于", "is_correct": false, "explanation": "搭配：“陷于”后多接困境、泥潭等，不接“学校宿舍”这样的处所。"}], "explanations": {"归属": "正确：“归属于学校宿舍”表示车辆属于宿舍，与“别随便骑走”一致。", "忠于": "语义：车辆不能“忠于”宿舍，与语境不符。", "等于": "语义：“等于”表示相等，不表示东西属于谁。", "陷于": "搭配：“陷于”后多接困境、泥潭等，不接“学校宿舍”这样的处所。"}, "sentence_index": 0, "correct_answer": "归属"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件事最终归属于平静。", "explanation": "这里应该用〈归于〉。归属表示所属，不能表示事情最终变成平静的状态。"}, {"text": "这份资料最终归属于一个结论。", "explanation": "这里应该用〈归纳〉。归属表示所属，不能表示从资料中概括出结论。"}, {"text": "这两个班最终归属于一个班。", "explanation": "这里应该用〈归并〉。归属表示所属，不能表示两个班合并成一个。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd438de31-d2f2-4485-ba1f-d93681089655') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23942, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "归属", "is_correct": true, "explanation": "正确：“归属于幼儿园”表示玩具属于幼儿园，与“小朋友可以借来玩”一致。"}, {"text": "依赖", "is_correct": false, "explanation": "语义：玩具不能“依赖”幼儿园，与“借来玩”的语境矛盾。"}, {"text": "屈服", "is_correct": false, "explanation": "语义：玩具不会“屈服于”幼儿园，句意无法成立。"}, {"text": "献身", "is_correct": false, "explanation": "搭配：“献身于”后接事业或理想，不接玩具与幼儿园。"}], "explanations": {"归属": "正确：“归属于幼儿园”表示玩具属于幼儿园，与“小朋友可以借来玩”一致。", "依赖": "语义：玩具不能“依赖”幼儿园，与“借来玩”的语境矛盾。", "屈服": "语义：玩具不会“屈服于”幼儿园，句意无法成立。", "献身": "搭配：“献身于”后接事业或理想，不接玩具与幼儿园。"}, "sentence_index": 6, "correct_answer": "归属"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他伤好后终于归属于那张病床。", "explanation": "这里应该用〈归队〉。归属表示所属，不能表示伤愈后回到原来的部队。"}, {"text": "一切都归属于平静。", "explanation": "这里应该用〈归于〉。归属只表示所属，不能表示最终变成某种状态。"}, {"text": "玩完游戏后，棋子要归属于原位。", "explanation": "这里应该用〈归位〉。归属表示所属，不能表示把棋子放回原位。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd438de31-d2f2-4485-ba1f-d93681089655') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23942, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这把伞归属在那位老师。", "corrected_sentence": "这把伞归属于那位老师。", "error_description": "错误在于“归属”后的介词用错。引出归属方要用“于”，“在”表示处所，应为“归属于那位老师”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd438de31-d2f2-4485-ba1f-d93681089655') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23942, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这块地归属村里。", "corrected_sentence": "这块地归属于村里。", "error_description": "错误在于漏掉介词“于”。引出归属方要用“归属于”，应为“归属于村里”；直接接处所名词不符合汉语习惯。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd438de31-d2f2-4485-ba1f-d93681089655') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23944, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd438de31-d2f2-4485-ba1f-d93681089655') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23944, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd438de31-d2f2-4485-ba1f-d93681089655') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23944, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "你觉得自己属于一个地方或一个群体，心里很安稳。", "primary_collocate": null, "pronunciation": "guī shǔ gǎn", "ipa": "kweɪ˥ ʂu˨˩˦ kan˨˩˦", "syllable_count": 3, "sentences": [{"text": "在家里，我总是觉得很有归属感。", "target_word": "归属感", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他离开家乡多年，一直没有归属感。", "target_word": "归属感", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家小店像家一样，客人都很有归属感。", "target_word": "归属感", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们班同学感情好，大家都有归属感。", "target_word": "归属感", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "搬了三次家，孩子还没有找到归属感。", "target_word": "归属感", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友们的笑声，给了我一种归属感。", "target_word": "归属感", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她喜欢这座小城，因为这里有归属感。", "target_word": "归属感", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有归属感的人，常常觉得很孤单。", "target_word": "归属感", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司给新同事开了欢迎会，增强了他们的归属感。", "target_word": "归属感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "回到老房子，我心里有一种安稳的归属感。", "target_word": "归属感", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种归属感", "label": "量词"}, {"form": "一份归属感", "label": "量词"}], "register": "中性", "sense_fingerprint": "觉得属于某处或某群体而心里安稳", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f96f18b6-c394-4703-a301-fe5590358afb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23944, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "归属感", "is_correct": true, "explanation": "“归属感”指觉得属于某地而心里安稳，与“在家里”的语境相符。"}, {"text": "股票", "is_correct": false, "explanation": "语义：“在家里觉得很有股票”，两者不相关，句子不成立。"}, {"text": "体积", "is_correct": false, "explanation": "语义：体积是物体的属性，不能用来形容“我”的心理感受。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：“很有”后接“工资”不构成表达心理感受的搭配。"}], "explanations": {"归属感": "“归属感”指觉得属于某地而心里安稳，与“在家里”的语境相符。", "股票": "语义：“在家里觉得很有股票”，两者不相关，句子不成立。", "体积": "语义：体积是物体的属性，不能用来形容“我”的心理感受。", "工资": "搭配：“很有”后接“工资”不构成表达心理感受的搭配。"}, "sentence_index": 0, "correct_answer": "归属感"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他考了零分，心里却很有归属感。", "explanation": "这里应该用〈沮丧〉。归属感指觉得属于某群体的心理认同，考砸后的失望要用“沮丧”。"}, {"text": "老师对学生很有归属感。", "explanation": "这里应该用〈同情心〉。归属感指觉得属于某群体的心理认同，不表示对他人的怜悯。"}, {"text": "他说话很有归属感。", "explanation": "这里应该用〈幽默感〉。归属感指觉得属于某地或群体的认同，不用来描述说话的风格。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd438de31-d2f2-4485-ba1f-d93681089655') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23944, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "归属感", "is_correct": true, "explanation": "“归属感”指觉得属于某地而心里安稳，是她喜欢这座城市的理由，符合语境。"}, {"text": "体温", "is_correct": false, "explanation": "语义：体温不是让人喜欢一座城市的理由，“因为这里有体温”说不通。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：有窗户并不能构成她喜欢这座小城的理由，句子不成立。"}, {"text": "螺丝", "is_correct": false, "explanation": "搭配：“有螺丝”不构成描述地方特点的常见搭配。"}], "explanations": {"归属感": "“归属感”指觉得属于某地而心里安稳，是她喜欢这座城市的理由，符合语境。", "体温": "语义：体温不是让人喜欢一座城市的理由，“因为这里有体温”说不通。", "窗户": "语义：有窗户并不能构成她喜欢这座小城的理由，句子不成立。", "螺丝": "搭配：“有螺丝”不构成描述地方特点的常见搭配。"}, "sentence_index": 6, "correct_answer": "归属感"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他没有被选上，心里却很有归属感。", "explanation": "这里应该用〈失落感〉。归属感指觉得属于某群体的心理认同，落选后的失落要用“失落感”。"}, {"text": "他一整天没吃饭，归属感很强。", "explanation": "这里应该用〈饥饿感〉。归属感指觉得属于某地或群体的心理认同，空腹的感觉要用“饥饿感”。"}, {"text": "孩子对新事物很有归属感。", "explanation": "这里应该用〈好奇心〉。归属感指觉得属于某地或群体的心理安稳，不表示求知的兴趣。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd438de31-d2f2-4485-ba1f-d93681089655') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23944, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "搬到新城市后，我才慢慢有了一只归属感。", "corrected_sentence": "搬到新城市后，我才慢慢有了一种归属感。", "error_description": "错误：“一只归属感”，量词“只”不能修饰抽象的心理感受；正确：“一种归属感”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd438de31-d2f2-4485-ba1f-d93681089655') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23944, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她在这座小城里找到了很归属感。", "corrected_sentence": "她在这座小城里找到了归属感。", "error_description": "错误：“很归属感”，程度副词“很”不能直接修饰名词“归属感”；正确：“找到了归属感”，去掉“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd438de31-d2f2-4485-ba1f-d93681089655') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
