INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23950, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "自己主动做一件事，不是别人让做的。", "primary_collocate": null, "pronunciation": "zì fā", "ipa": "tsɨ˥˩ fa˥", "syllable_count": 2, "sentences": [{"text": "同学们自发地把教室打扫干净了。", "target_word": "自发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雨过后，居民自发去帮助邻居。", "target_word": "自发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这不是老师要求的，是孩子们自发做的。", "target_word": "自发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地震后，很多人自发给灾区捐钱。", "target_word": "自发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没人安排，大家自发排好了队。", "target_word": "自发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他自发地每天早上跑步，没人叫他。", "target_word": "自发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次活动是学生自发组织的。", "target_word": "自发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到老人摔倒，路人自发上前帮忙。", "target_word": "自发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚会结束后，志愿者自发留下来收拾。", "target_word": "自发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她自发学习英语，不是为了考试。", "target_word": "自发", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "自发地", "label": "状语形式"}, {"form": "自发性", "label": "复合词"}], "register": "中性", "sense_fingerprint": "没有人要求，出于自己的想法主动去做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0b36993-6be1-4beb-8bc2-c6c37fd0d0a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23950, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自发", "is_correct": true, "explanation": "自发：指没有别人要求而主动去做，与「地把教室打扫干净」搭配，符合句意。"}, {"text": "懒惰", "is_correct": false, "explanation": "语义：「懒惰地」与「把教室打扫干净」的意思相矛盾，懒惰的人不会主动打扫。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：「高大」描述人或物的外形，不能用来修饰「打扫」这个动作。"}, {"text": "透明", "is_correct": false, "explanation": "搭配：「透明」多用于物体或液体的质地，不能修饰「打扫」这个动作。"}], "explanations": {"自发": "自发：指没有别人要求而主动去做，与「地把教室打扫干净」搭配，符合句意。", "懒惰": "语义：「懒惰地」与「把教室打扫干净」的意思相矛盾，懒惰的人不会主动打扫。", "高大": "体貌：「高大」描述人或物的外形，不能用来修饰「打扫」这个动作。", "透明": "搭配：「透明」多用于物体或液体的质地，不能修饰「打扫」这个动作。"}, "sentence_index": 0, "correct_answer": "自发"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台洗衣机可以自发地完成脱水。", "explanation": "这里应该用〈自动〉。自发指出于个人意愿、无人安排，机器按程序运转要用自动。"}, {"text": "我在路上遇到老同学，这完全是自发的。", "explanation": "这里应该用〈偶然〉。自发指出于自己的意愿主动去做，遇见老同学是没有预料的，要用偶然。"}, {"text": "工厂因为订单减少，自发停工了。", "explanation": "这里应该用〈被迫〉。自发强调出于自己的意愿，没有外力；因订单减少而停工是受压力所迫，要用被迫。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c70bd67-1f70-4fec-9ce1-5b472ee1565d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23950, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自发", "is_correct": true, "explanation": "自发：说明活动是学生主动发起的，与「组织的」搭配，符合句意。"}, {"text": "晴朗", "is_correct": false, "explanation": "语义：「晴朗」形容天气，不能用来修饰「组织」。"}, {"text": "慢性", "is_correct": false, "explanation": "搭配：「慢性」多用于病症，「学生慢性组织」不能搭配。"}, {"text": "圆形", "is_correct": false, "explanation": "体貌：「圆形」描述事物的外形，不能用来说明活动组织的方式。"}], "explanations": {"自发": "自发：说明活动是学生主动发起的，与「组织的」搭配，符合句意。", "晴朗": "语义：「晴朗」形容天气，不能用来修饰「组织」。", "慢性": "搭配：「慢性」多用于病症，「学生慢性组织」不能搭配。", "圆形": "体貌：「圆形」描述事物的外形，不能用来说明活动组织的方式。"}, "sentence_index": 6, "correct_answer": "自发"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他被警察自发地带走了。", "explanation": "这里应该用〈强行〉。自发表示出于自己的意愿主动去做，被警察带走是被强制的，不能用自发修饰。"}, {"text": "全班同学都自发地考了满分。", "explanation": "这里应该用〈取得〉。自发强调出于自己的意愿主动去做，考试成绩是靠努力取得的，不能用自发修饰。"}, {"text": "他在会议上自发地睡着了。", "explanation": "这里应该用〈不由自主〉。自发强调出于自己的意愿主动去做，睡着是身不由己的，要用不由自主。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c70bd67-1f70-4fec-9ce1-5b472ee1565d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23950, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "没人要求，大家自发的捐了款。", "corrected_sentence": "没人要求，大家自发地捐了款。", "error_description": "错误：修饰动词时要用「地」，不能用「的」。「的」用于名词前面的修饰语，正确形式是「自发地捐了款」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c70bd67-1f70-4fec-9ce1-5b472ee1565d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23950, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个俱乐部是大家自发成立地。", "corrected_sentence": "这个俱乐部是大家自发成立的。", "error_description": "错误：句末「的」写成了「地」。「地」用在动词前作状语，「成立」后不能接「地」。「是……的」句式应说「自发成立的」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c70bd67-1f70-4fec-9ce1-5b472ee1565d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
