INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23954, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "意思是以后一定会发生。", "primary_collocate": null, "pronunciation": "zhōng jiāng", "ipa": "ʈʂʊŋ˥ tɕjɑŋ˥", "syllable_count": 2, "sentences": [{"text": "小树终将长成大树。", "target_word": "终将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雪终将变成水。", "target_word": "终将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题终将解决。", "target_word": "终将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天练习，终将成为好歌手。", "target_word": "终将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你现在不懂，以后终将明白。", "target_word": "终将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坏天气终将过去，明天会更好。", "target_word": "终将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她相信自己终将回到家乡。", "target_word": "终将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路虽然很长，但你终将走到终点。", "target_word": "终将", "complexity_tier": "T3", "furigana": "zhè tiáo lù suī rán hěn cháng, dàn nǐ zhōng jiāng zǒu dào zhōng diǎn。", "sentence_source": "generated"}, {"text": "我们终将见面，不用太难过。", "target_word": "终将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天终将结束，学校又要开学了。", "target_word": "终将", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "終將", "label": "繁体"}], "register": "书面", "sense_fingerprint": "终将:副词，以后一定会发生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bff508bb-4dd4-4d17-9788-2be285a2506d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23954, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "终将", "is_correct": true, "explanation": "“终将”表示经过较长时间必然实现，与“小树长成大树”的将来过程相合。"}, {"text": "已经", "is_correct": false, "explanation": "语义：“已经”表示已经发生，与“小树”尚未长大的现状相矛盾。"}, {"text": "立刻", "is_correct": false, "explanation": "语义：“立刻”指马上完成，与“长成大树”需要长时间成长的过程不符。"}, {"text": "偶尔", "is_correct": false, "explanation": "搭配：“偶尔”修饰不常发生的动作，不能用于“长成大树”这种持续的变化。"}], "explanations": {"终将": "“终将”表示经过较长时间必然实现，与“小树长成大树”的将来过程相合。", "已经": "语义：“已经”表示已经发生，与“小树”尚未长大的现状相矛盾。", "立刻": "语义：“立刻”指马上完成，与“长成大树”需要长时间成长的过程不符。", "偶尔": "搭配：“偶尔”修饰不常发生的动作，不能用于“长成大树”这种持续的变化。"}, "sentence_index": 0, "correct_answer": "终将"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "弟弟昨天终将考完试，我们都很高兴。", "explanation": "这里应该用〈终于〉。“终将”表示将来必然出现，句中的“昨天”已经过去，不能描述已经完成的事。"}, {"text": "去年，他终将获胜。", "explanation": "这里应该用〈最终〉。“终将”只用于将来必然会出现的结果，“去年”的获胜已经发生。"}, {"text": "这班车马上终将到站。", "explanation": "这里应该用〈就要〉。“终将”指将来必然会出现的结果，“马上”指眼前的事，两者语义冲突，应用“就要”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6e9e744-4847-4ffa-9912-38d63166b1ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23954, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "终将", "is_correct": true, "explanation": "“终将”表示将来必然实现，与“相信自己”后面的未来愿望相合。"}, {"text": "曾经", "is_correct": false, "explanation": "语义：“曾经”表示过去发生过，与句中指向将来的回家愿望相反。"}, {"text": "从来", "is_correct": false, "explanation": "搭配：“从来”需与否定词连用，不能直接用在“相信自己”之后表示将来的回家。"}, {"text": "一直", "is_correct": false, "explanation": "搭配：“一直”表示持续的动作，不能与“回到”这类一次性的结果动词连用。"}], "explanations": {"终将": "“终将”表示将来必然实现，与“相信自己”后面的未来愿望相合。", "曾经": "语义：“曾经”表示过去发生过，与句中指向将来的回家愿望相反。", "从来": "搭配：“从来”需与否定词连用，不能直接用在“相信自己”之后表示将来的回家。", "一直": "搭配：“一直”表示持续的动作，不能与“回到”这类一次性的结果动词连用。"}, "sentence_index": 6, "correct_answer": "终将"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "前天晚上，他终将没有回家。", "explanation": "这里应该用〈终究〉。“终将”指将来必然发生，句中的“前天晚上”已经过去，不能用“终将”描述已经发生的事。"}, {"text": "那天，他终将同意我们去。", "explanation": "这里应该用〈最后〉。这是当天已经做出的同意，“终将”只用来说将来必然出现的结果。"}, {"text": "刚才他终将离开教室。", "explanation": "这里应该用〈已经〉。“终将”指将来必然发生的结果，“刚才”说的是刚发生的事，应该用“已经”表示已经完成。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6e9e744-4847-4ffa-9912-38d63166b1ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23954, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些烦恼终将过去了。", "corrected_sentence": "这些烦恼终将过去。", "error_description": "错误在于“终将”与“了”连用。“终将”表示将来必然发生，不能与表示完成的“了”搭配，应说“这些烦恼终将过去”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6e9e744-4847-4ffa-9912-38d63166b1ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23954, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个办法终将被人们接受了。", "corrected_sentence": "这个办法终将被人们接受。", "error_description": "错误在于“终将”与“了”连用。“终将”表示将来必然发生，不能与表示完成的“了”搭配，应说“这个办法终将被人们接受”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6e9e744-4847-4ffa-9912-38d63166b1ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
