INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23964, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "脚向前移动，让身体到别的地方去。", "primary_collocate": null, "pronunciation": "zǒu", "ipa": "tsoʊ˨˩", "syllable_count": 1, "sentences": [{"text": "从我家走到学校要十分钟。", "target_word": "走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天黑了，我们快走几步回家吧。", "target_word": "走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天走着去上班。", "target_word": "走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前面有一条河，我们不能再往前走了。", "target_word": "走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥很窄，只有行人能走。", "target_word": "走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她走过那条街，去了对面的商店。", "target_word": "走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我昨天走了很多路，脚很疼。", "target_word": "走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请沿着这条路走，不要走错方向。", "target_word": "走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公交车还没来，我们先走一段吧。", "target_word": "走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地铁站不远，咱们走着去吧。", "target_word": "走", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "走了", "label": "体标"}, {"form": "走着", "label": "体标"}, {"form": "走过", "label": "体标"}, {"form": "走开", "label": "复合"}], "register": "通用", "sense_fingerprint": "走|脚向前移动让身体到别的地方去", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12883278-5600-40df-b779-2c94d6e49eb7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23964, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "走", "is_correct": true, "explanation": "动词用法，表示人步行从家到学校，与句意相符。"}, {"text": "飞", "is_correct": false, "explanation": "语义：“飞”需要借助飞行工具，人从家到学校不能说“飞”。"}, {"text": "搬", "is_correct": false, "explanation": "语义：“搬”指搬迁或搬运物品，不能用于人走路程。"}, {"text": "游", "is_correct": false, "explanation": "语义：“游”指在水里前进，人从家步行到学校不能说“游”。"}], "explanations": {"走": "动词用法，表示人步行从家到学校，与句意相符。", "飞": "语义：“飞”需要借助飞行工具，人从家到学校不能说“飞”。", "搬": "语义：“搬”指搬迁或搬运物品，不能用于人走路程。", "游": "语义：“游”指在水里前进，人从家步行到学校不能说“游”。"}, "sentence_index": 0, "correct_answer": "走"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "小鸟在天上走了很远。", "explanation": "这里应该用〈飞〉。鸟靠翅膀在空中移动，要说飞，不用“走”。"}, {"text": "我每天走自行车去学校。", "explanation": "这里应该用〈骑〉。骑自行车要说“骑”，不能说“走自行车”。"}, {"text": "鸭子在湖面上走。", "explanation": "这里应该用〈游〉。鸭子靠游动前进，不能说在湖面上走。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '10b491d0-23cf-4c85-bdb8-11cf085212bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23964, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "走", "is_correct": true, "explanation": "动词用法，表示步行经过很多路，与“脚很疼”相符。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能与“路”搭配，“吃了很多路”不通。"}, {"text": "写", "is_correct": false, "explanation": "语义：“写”指书写文字，句中说的是步行，不是写字。"}, {"text": "看", "is_correct": false, "explanation": "搭配：“看”不以“路”为宾语表示经过，“看了很多路”不通。"}], "explanations": {"走": "动词用法，表示步行经过很多路，与“脚很疼”相符。", "吃": "搭配：“吃”不能与“路”搭配，“吃了很多路”不通。", "写": "语义：“写”指书写文字，句中说的是步行，不是写字。", "看": "搭配：“看”不以“路”为宾语表示经过，“看了很多路”不通。"}, "sentence_index": 6, "correct_answer": "走"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "蜘蛛在墙上走了一圈。", "explanation": "这里应该用〈爬〉。蜘蛛靠腿在墙上爬行，不用“走”。"}, {"text": "花瓣在水面上走了很远。", "explanation": "这里应该用〈漂〉。花瓣随水流动，没有脚，要说漂。"}, {"text": "石头在山坡上走了下来。", "explanation": "这里应该用〈滚〉。石头靠滚动下来，不用“走”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '10b491d0-23cf-4c85-bdb8-11cf085212bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23964, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们走很快，半小时就到了山顶。", "corrected_sentence": "我们走得很快，半小时就到了山顶。", "error_description": "错误：“走很快”；正确：“走得很快”。“走”后面的程度补语要用结构助词“得”连接，不能省略。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '10b491d0-23cf-4c85-bdb8-11cf085212bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23964, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "刚才他走着一段路，就停下来休息了。", "corrected_sentence": "刚才他走了一段路，就停下来休息了。", "error_description": "错误：“走着一段路”；正确：“走了一段路”。“刚才”指已完成的动作，要用“了”，不能用表示持续的“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '10b491d0-23cf-4c85-bdb8-11cf085212bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
