INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23966, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "飞机是一种能在天上飞的交通工具。", "primary_collocate": null, "pronunciation": "fēi jī", "ipa": "fei˥ tɕi˥", "syllable_count": 2, "sentences": [{"text": "我坐飞机去北京。", "target_word": "飞机", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "飞机几点起飞？", "target_word": "飞机", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这架飞机很大。", "target_word": "飞机", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他第一次坐飞机，有点儿紧张。", "target_word": "飞机", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "飞机在天上飞过。", "target_word": "飞机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从上海到北京坐飞机要两个小时。", "target_word": "飞机", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "飞机已经飞走了。", "target_word": "飞机", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天上有一架飞机。", "target_word": "飞机", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "因为下大雾，飞机不能起飞。", "target_word": "飞机", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每个月都坐飞机出差。", "target_word": "飞机", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "架", "label": "量词"}, {"form": "飞机场", "label": "复合"}, {"form": "飞机票", "label": "复合"}], "register": "中性", "sense_fingerprint": "名词：能在天上飞的交通工具", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e55a90f-bee7-49d4-adc2-7ec13ce55273') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23966, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "飞机", "is_correct": true, "explanation": "正确。“飞机”是能在天上飞的交通工具。"}, {"text": "肥鸡", "is_correct": false, "explanation": "féi（第二声）与 fēi（第一声）声调不同，意思是肥的鸡。"}, {"text": "分机", "is_correct": false, "explanation": "fēn 与 fēi 韵母不同（n 与 i），意思是电话的分机。"}, {"text": "风机", "is_correct": false, "explanation": "fēng 与 fēi 韵母不同（eng 与 i），意思是送风或通风的机器。"}], "explanations": {"飞机": "正确。“飞机”是能在天上飞的交通工具。", "肥鸡": "féi（第二声）与 fēi（第一声）声调不同，意思是肥的鸡。", "分机": "fēn 与 fēi 韵母不同（n 与 i），意思是电话的分机。", "风机": "fēng 与 fēi 韵母不同（eng 与 i），意思是送风或通风的机器。"}, "sentence_index": null, "correct_answer": "飞机"}, "level_3": {"options": [{"text": "飞机", "is_correct": true, "explanation": "正确。“坐飞机去北京”是常见的说法。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“坐”要搭配可以乘坐的交通工具，不说“坐桌子去北京”。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不能被乘坐，句子不通。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包不能被乘坐去北京，句子不通。"}], "explanations": {"飞机": "正确。“坐飞机去北京”是常见的说法。", "桌子": "搭配：“坐”要搭配可以乘坐的交通工具，不说“坐桌子去北京”。", "空气": "语义：空气不能被乘坐，句子不通。", "书包": "语义：书包不能被乘坐去北京，句子不通。"}, "sentence_index": 0, "correct_answer": "飞机"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他第一次坐飞机去隔壁超市，有点儿紧张。", "explanation": "这里应该用〈走〉。去隔壁超市不需要坐飞机，走过去即可。"}, {"text": "他第一次坐飞机穿过隧道，有点儿紧张。", "explanation": "这里应该用〈火车〉。火车会穿过隧道，飞机不会。"}, {"text": "他第一次坐飞机去图书馆借书，有点儿紧张。", "explanation": "这里应该用〈公交车〉。飞机只用于远距离飞行，去图书馆坐公交车即可。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25231ecd-b38e-4013-b8b0-2f67ce0365af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23966, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "飞机", "is_correct": true, "explanation": "正确。飞机能飞，所以可以说“飞走了”。"}, {"text": "大楼", "is_correct": false, "explanation": "语义：大楼是固定的建筑，不会飞走，句子不通。"}, {"text": "大山", "is_correct": false, "explanation": "语义：大山是固定的地形，不会飞走，句子不通。"}, {"text": "墙", "is_correct": false, "explanation": "语义：墙是固定的结构，不会飞走，句子不通。"}], "explanations": {"飞机": "正确。飞机能飞，所以可以说“飞走了”。", "大楼": "语义：大楼是固定的建筑，不会飞走，句子不通。", "大山": "语义：大山是固定的地形，不会飞走，句子不通。", "墙": "语义：墙是固定的结构，不会飞走，句子不通。"}, "sentence_index": 6, "correct_answer": "飞机"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每个月都用飞机擦窗户。", "explanation": "这里应该用〈抹布〉。飞机是交通工具，擦窗户要用抹布，不能用飞机。"}, {"text": "飞机能把卫星送入太空。", "explanation": "这里应该用〈火箭〉。飞机飞不出大气层，不能把卫星送入太空。"}, {"text": "他坐飞机到五楼开会。", "explanation": "这里应该用〈电梯〉。飞机只能在空中飞行，到楼层要坐电梯。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25231ecd-b38e-4013-b8b0-2f67ce0365af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23966, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只飞机起飞了。", "corrected_sentence": "那架飞机起飞了。", "error_description": "量词错误：飞机应用“架”，不用“只”。正确的说法是“那架飞机起飞了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25231ecd-b38e-4013-b8b0-2f67ce0365af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23966, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他坐了过一次飞机。", "corrected_sentence": "他坐过一次飞机。", "error_description": "“了”与“过”不能同时用在动词后表示经历，应为“坐过一次飞机”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25231ecd-b38e-4013-b8b0-2f67ce0365af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23972, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "吃", "is_correct": false, "explanation": "吃：指把食物咽下，与“推”没有反义关系。"}, {"text": "读", "is_correct": false, "explanation": "读：指看文字并发出声音，与“推”没有反义关系。"}, {"text": "拉", "is_correct": true, "explanation": "正确答案。拉与推方向相反，指使东西向自己这边移动。"}, {"text": "跑", "is_correct": false, "explanation": "跑：指快速移动双脚，与“推”没有反义关系。"}], "correct_answer": "拉", "explanations": {"吃": "吃：指把食物咽下，与“推”没有反义关系。", "读": "读：指看文字并发出声音，与“推”没有反义关系。", "拉": "正确答案。拉与推方向相反，指使东西向自己这边移动。", "跑": "跑：指快速移动双脚，与“推”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ae601c2-2197-4720-9241-627f965dae00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23972, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "喝", "is_correct": false, "explanation": "喝：指用嘴吞咽液体，与“推”没有反义关系。"}, {"text": "拉", "is_correct": true, "explanation": "正确答案。拉与推方向相反，指使东西向自己这边移动。"}, {"text": "睡", "is_correct": false, "explanation": "睡：指闭眼休息，与“推”没有反义关系。"}, {"text": "唱", "is_correct": false, "explanation": "唱：指发出有节奏的声音，与“推”没有反义关系。"}], "correct_answer": "拉", "explanations": {"喝": "喝：指用嘴吞咽液体，与“推”没有反义关系。", "拉": "正确答案。拉与推方向相反，指使东西向自己这边移动。", "睡": "睡：指闭眼休息，与“推”没有反义关系。", "唱": "唱：指发出有节奏的声音，与“推”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ae601c2-2197-4720-9241-627f965dae00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23972, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用手或身体使东西向前移动。", "primary_collocate": null, "pronunciation": "tuī", "ipa": "tʰuei̯˥", "syllable_count": 1, "sentences": [{"text": "妈妈推着婴儿车在公园里走。", "target_word": "推", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我用肩膀推开了那扇门。", "target_word": "推", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他推着自行车走上了小山。", "target_word": "推", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家一起推，车终于动了。", "target_word": "推", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明从后面推了我一下。", "target_word": "推", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在超市里，爸爸推着购物车。", "target_word": "推", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把箱子往前推了一点。", "target_word": "推", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶坐在轮椅上，孙子在后面推。", "target_word": "推", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这扇门要往外推，不要拉。", "target_word": "推", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她推开窗户，外面下雪了。", "target_word": "推", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "推了", "label": "体标"}, {"form": "推着", "label": "体标"}, {"form": "推过", "label": "体标"}, {"form": "推推", "label": "重叠"}, {"form": "推开", "label": "复合"}], "register": "中性", "sense_fingerprint": "推：用手或身体使东西向前移动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7bcf024-40e1-464a-b19b-d6126447d7ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23972, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "腿", "is_correct": false, "explanation": "推（第一声）与腿（第三声）声调不同，腿指身体的下肢部分。"}, {"text": "推", "is_correct": true, "explanation": "正确答案。推 tuī（第一声），指用手或身体使东西向前移动。"}, {"text": "退", "is_correct": false, "explanation": "推（第一声）与退（第四声）声调不同，退指向后移动。"}, {"text": "堆", "is_correct": false, "explanation": "推与堆的声母不同（t 与 d），堆 duī 指堆积。"}], "explanations": {"腿": "推（第一声）与腿（第三声）声调不同，腿指身体的下肢部分。", "推": "正确答案。推 tuī（第一声），指用手或身体使东西向前移动。", "退": "推（第一声）与退（第四声）声调不同，退指向后移动。", "堆": "推与堆的声母不同（t 与 d），堆 duī 指堆积。"}, "sentence_index": null, "correct_answer": "推"}, "level_3": {"options": [{"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的宾语应是食物，不能说“吃着婴儿车”。"}, {"text": "推", "is_correct": true, "explanation": "正确答案。“推着婴儿车”表示妈妈用手使车向前移动。"}, {"text": "写", "is_correct": false, "explanation": "语义：写是用笔记录文字，无法表示推动婴儿车。"}, {"text": "扔", "is_correct": false, "explanation": "语义：扔是丢弃，与妈妈推婴儿车在公园散步的语境不合。"}], "explanations": {"吃": "搭配：“吃”的宾语应是食物，不能说“吃着婴儿车”。", "推": "正确答案。“推着婴儿车”表示妈妈用手使车向前移动。", "写": "语义：写是用笔记录文字，无法表示推动婴儿车。", "扔": "语义：扔是丢弃，与妈妈推婴儿车在公园散步的语境不合。"}, "sentence_index": 0, "correct_answer": "推"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把碗筷推干净了。", "explanation": "这里应该用〈洗〉。推是使物体移动，把碗筷洗干净要用洗。"}, {"text": "他推起手，向大家挥了挥。", "explanation": "这里应该用〈举〉。推是使物体向前移动，把手抬起来要用举。"}, {"text": "他把饼干推成两半。", "explanation": "这里应该用〈掰〉。推是使物体移动，把饼干弄成两半要用掰。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ae601c2-2197-4720-9241-627f965dae00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23972, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "吹", "is_correct": false, "explanation": "推与吹的声母不同（t 与 ch），吹 chuī 指用嘴或风送出气流。"}, {"text": "催", "is_correct": false, "explanation": "推与催的声母不同（t 与 c），催 cuī 指促使对方快做。"}, {"text": "推", "is_correct": true, "explanation": "正确答案。推 tuī（第一声），指用手或身体使东西向前移动。"}, {"text": "追", "is_correct": false, "explanation": "推与追的声母不同（t 与 zh），追 zhuī 指跟在后面赶上。"}], "explanations": {"吹": "推与吹的声母不同（t 与 ch），吹 chuī 指用嘴或风送出气流。", "催": "推与催的声母不同（t 与 c），催 cuī 指促使对方快做。", "推": "正确答案。推 tuī（第一声），指用手或身体使东西向前移动。", "追": "推与追的声母不同（t 与 zh），追 zhuī 指跟在后面赶上。"}, "sentence_index": null, "correct_answer": "推"}, "level_3": {"options": [{"text": "唱", "is_correct": false, "explanation": "语义：唱是发声歌唱，无法表示用力使箱子向前移动。"}, {"text": "读", "is_correct": false, "explanation": "语义：读是看文字，与移动箱子的动作无关。"}, {"text": "咬", "is_correct": false, "explanation": "搭配：“咬”的对象一般是食物或具体咬合物，不能说“咬箱子往前”。"}, {"text": "推", "is_correct": true, "explanation": "正确答案。“把箱子往前推”表示用力使箱子向前移动一点。"}], "explanations": {"唱": "语义：唱是发声歌唱，无法表示用力使箱子向前移动。", "读": "语义：读是看文字，与移动箱子的动作无关。", "咬": "搭配：“咬”的对象一般是食物或具体咬合物，不能说“咬箱子往前”。", "推": "正确答案。“把箱子往前推”表示用力使箱子向前移动一点。"}, "sentence_index": 6, "correct_answer": "推"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他推着一碗热汤，小心地走了过来。", "explanation": "这里应该用〈端〉。推是使物体向前移动，端着碗要用端。"}, {"text": "他弯腰推起了跌倒的老人。", "explanation": "这里应该用〈扶〉。推是使物体离开原位置，扶起跌倒的人要用扶。"}, {"text": "妈妈用力把毛巾推干了。", "explanation": "这里应该用〈拧〉。推是使物体移动，把毛巾里的水挤出来要用拧。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ae601c2-2197-4720-9241-627f965dae00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23972, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他用力把窗户推了开。", "corrected_sentence": "他用力把窗户推开了。", "error_description": "错误：“推了开”。“了”应放在复合动词“推开”之后，写作“推开了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ae601c2-2197-4720-9241-627f965dae00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23972, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "奶奶着推轮椅到了门口。", "corrected_sentence": "奶奶推着轮椅到了门口。", "error_description": "错误：“着推轮椅”。“着”应紧跟动词“推”之后，写作“推着轮椅”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ae601c2-2197-4720-9241-627f965dae00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23976, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "跳舞", "is_correct": false, "explanation": "跳舞：指随音乐摆动身体，与“向前走”没有反义关系。"}, {"text": "散步", "is_correct": false, "explanation": "散步：指悠闲地走走，与“向前走”不构成反义。"}, {"text": "向后走", "is_correct": true, "explanation": "正确答案。“向后走”指朝相反方向行进，与“向前走”构成反义。"}, {"text": "睡觉", "is_correct": false, "explanation": "睡觉：指闭眼休息，与“向前走”没有反义关系。"}], "correct_answer": "向后走", "explanations": {"跳舞": "跳舞：指随音乐摆动身体，与“向前走”没有反义关系。", "散步": "散步：指悠闲地走走，与“向前走”不构成反义。", "向后走": "正确答案。“向后走”指朝相反方向行进，与“向前走”构成反义。", "睡觉": "睡觉：指闭眼休息，与“向前走”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ae601c2-2197-4720-9241-627f965dae00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23976, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "吃饭", "is_correct": false, "explanation": "吃饭：指进食，与“向前走”没有反义关系。"}, {"text": "唱歌", "is_correct": false, "explanation": "唱歌：指用嗓音演唱，与“向前走”没有反义关系。"}, {"text": "写字", "is_correct": false, "explanation": "写字：指用笔写出文字，与“向前走”没有反义关系。"}, {"text": "向后走", "is_correct": true, "explanation": "正确答案。“向后走”指朝相反方向行进，与“向前走”构成反义。"}], "correct_answer": "向后走", "explanations": {"吃饭": "吃饭：指进食，与“向前走”没有反义关系。", "唱歌": "唱歌：指用嗓音演唱，与“向前走”没有反义关系。", "写字": "写字：指用笔写出文字，与“向前走”没有反义关系。", "向后走": "正确答案。“向后走”指朝相反方向行进，与“向前走”构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ae601c2-2197-4720-9241-627f965dae00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23976, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "往前面走。", "primary_collocate": null, "pronunciation": "xiàng qián zǒu", "ipa": "ɕi̯ɑŋ˥˩ tɕʰi̯ɛn˧˥ tsou̯˨˩˦", "syllable_count": 3, "sentences": [{"text": "他向前走了两步，站在门口。", "target_word": "向前走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "队伍开始向前走了。", "target_word": "向前走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "绿灯亮了，车和人都向前走。", "target_word": "向前走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她看着路，一直向前走着。", "target_word": "向前走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你向前走五米，再向左拐。", "target_word": "向前走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗跟着我向前走。", "target_word": "向前走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山路很陡，但他不停地向前走。", "target_word": "向前走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们向前走了一会儿，就看到了河。", "target_word": "向前走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，病人可以自己向前走了。", "target_word": "向前走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他闭着眼睛，伸出手向前走。", "target_word": "向前走", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "向前走了", "label": "体标"}, {"form": "向前走着", "label": "体标"}, {"form": "向前走过", "label": "体标"}], "register": "中性", "sense_fingerprint": "向前走：往前面走", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7bcf024-40e1-464a-b19b-d6126447d7ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23976, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "唱", "is_correct": false, "explanation": "语义：唱是发声歌唱，不能与“两步”搭配表示移动。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能与“两步”搭配，不说“吃了两步”。"}, {"text": "写", "is_correct": false, "explanation": "语义：写是用笔记录文字，与走两步站到门口的语境无关。"}, {"text": "向前走", "is_correct": true, "explanation": "正确答案。“向前走了两步”表示朝前方行进两步。"}], "explanations": {"唱": "语义：唱是发声歌唱，不能与“两步”搭配表示移动。", "吃": "搭配：“吃”不能与“两步”搭配，不说“吃了两步”。", "写": "语义：写是用笔记录文字，与走两步站到门口的语境无关。", "向前走": "正确答案。“向前走了两步”表示朝前方行进两步。"}, "sentence_index": 0, "correct_answer": "向前走"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一直向前走着不动，没有说话。", "explanation": "这里应该用〈站〉。“向前走”表示朝前行进，与“不动”矛盾，静止要用站。"}, {"text": "她向前走回了屋子，然后关上门。", "explanation": "这里应该用〈返回〉。“向前走”表示朝前行进，与“回屋子”的返回方向矛盾。"}, {"text": "她一边向前走，一边一直往后退。", "explanation": "这里的“向前走”是朝前方行进，与“一直往后退”方向相反，表示向后移动应改用〈倒着走〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ae601c2-2197-4720-9241-627f965dae00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23976, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "读书", "is_correct": false, "explanation": "搭配：“不停地读书”与“山路很陡”的语境不搭，不能描述爬坡。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：睡觉是休息，与山路陡峭却坚持前进的语境相反。"}, {"text": "跳舞", "is_correct": false, "explanation": "语义：跳舞与在陡峭山路上行进的语境不符。"}, {"text": "向前走", "is_correct": true, "explanation": "正确答案。“不停地向前走”表示即使山路陡峭也持续前行。"}], "explanations": {"读书": "搭配：“不停地读书”与“山路很陡”的语境不搭，不能描述爬坡。", "睡觉": "语义：睡觉是休息，与山路陡峭却坚持前进的语境相反。", "跳舞": "语义：跳舞与在陡峭山路上行进的语境不符。", "向前走": "正确答案。“不停地向前走”表示即使山路陡峭也持续前行。"}, "sentence_index": 6, "correct_answer": "向前走"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他闭着眼睛，向前走在床上，一动不动。", "explanation": "这里应该用〈躺〉。“向前走”表示行进，躺在床上是静止的，要用躺。"}, {"text": "他闭着眼睛，伸出手，却在原地向前走，一步也没挪。", "explanation": "这里应该用〈踏步〉。“向前走”表示朝前行进，原地不挪步应说“原地踏步”。"}, {"text": "他闭着眼睛，伸出手，向前走上了墙。", "explanation": "这里应该用〈爬〉。“向前走”指朝前方行进，不能表示沿墙面向上移动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ae601c2-2197-4720-9241-627f965dae00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23976, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子们一起向前走很慢，去看海。", "corrected_sentence": "孩子们一起向前走得很慢，去看海。", "error_description": "错误：“向前走很慢”。缺少补语标记“得”，应写作“向前走得很慢”，用“得”引出表示程度的补语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ae601c2-2197-4720-9241-627f965dae00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23976, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们向前走着一百米，就到了河边。", "corrected_sentence": "他们向前走了一百米，就到了河边。", "error_description": "错误：“向前走着一百米”。“着”表示动作持续，不能接表示距离的数量短语；表示完成的动作应用“了”，写作“向前走了一百米”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ae601c2-2197-4720-9241-627f965dae00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
