INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23986, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "就是不让东西往前走的力量。", "primary_collocate": null, "pronunciation": "zǔ lì", "ipa": "tsu˨˩˦ li˥˩", "syllable_count": 2, "sentences": [{"text": "水里的阻力比空气里大。", "target_word": "阻力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跑步时，迎面吹来的风会产生阻力。", "target_word": "阻力", "complexity_tier": "T3", "furigana": "zǔ lì", "sentence_source": "generated"}, {"text": "汽车开得太快，空气阻力就会变大。", "target_word": "阻力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆自行车的轮子很圆，阻力很小。", "target_word": "阻力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "船在水中走得慢，是因为水有阻力。", "target_word": "阻力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机的形状可以减小空气的阻力。", "target_word": "阻力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在泳池里游泳，感到水的阻力很大。", "target_word": "阻力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雪地上走路，阻力比平地大。", "target_word": "阻力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "轮子下面有油，阻力就小了。", "target_word": "阻力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鸟的身体很轻，飞的时候阻力很小。", "target_word": "阻力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "空气阻力", "label": "复合"}, {"form": "摩擦阻力", "label": "复合"}], "register": "中性", "sense_fingerprint": "阻碍物体运动的力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebd53f51-cdf0-46b6-96dd-99270f958475') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23986, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "阻力", "is_correct": true, "explanation": "阻力：阻碍物体运动的力，符合句意。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：水和空气比较的是阻碍运动的力，颜色无法比较大小。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：水和空气没有年龄，句意不通。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高是人的体貌特征，不能用来比较水和空气。"}], "explanations": {"阻力": "阻力：阻碍物体运动的力，符合句意。", "颜色": "语义：水和空气比较的是阻碍运动的力，颜色无法比较大小。", "年龄": "语义：水和空气没有年龄，句意不通。", "身高": "体貌：身高是人的体貌特征，不能用来比较水和空气。"}, "sentence_index": 0, "correct_answer": "阻力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这辆车的轮子上有一只阻力。", "explanation": "这里量词用错。阻力应用〈股〉或〈个〉，〈只〉多用于动物或成对物品中的一个，不能用来数阻力。"}, {"text": "水的阻力是三十度。", "explanation": "这里应该用〈温度〉。阻力是阻碍运动的力，不能表示冷热程度；说水的冷热要用温度。"}, {"text": "汽车靠阻力前进。", "explanation": "这里应该用〈动力〉。阻力是阻碍运动的力，推动汽车前进要用动力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77e535a1-3d00-41a4-8a35-d6188aee7aa7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23986, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "阻力", "is_correct": true, "explanation": "阻力：阻碍运动的力，符合句意。"}, {"text": "名字", "is_correct": false, "explanation": "语义：水没有名字，「感到水的名字很大」句意不通。"}, {"text": "价格", "is_correct": false, "explanation": "语义：水的价格与游泳时的感受无关，句意不通。"}, {"text": "长相", "is_correct": false, "explanation": "体貌：水没有长相，不能用来描述游泳时的感受。"}], "explanations": {"阻力": "阻力：阻碍运动的力，符合句意。", "名字": "语义：水没有名字，「感到水的名字很大」句意不通。", "价格": "语义：水的价格与游泳时的感受无关，句意不通。", "长相": "体貌：水没有长相，不能用来描述游泳时的感受。"}, "sentence_index": 6, "correct_answer": "阻力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆汽车的阻力很快。", "explanation": "这里应该用〈速度〉。阻力是力，没有快慢；说车快要用速度。"}, {"text": "火箭靠阻力升空。", "explanation": "这里应该用〈推力〉。阻力只能阻碍运动，不能使火箭升空；推动火箭要用推力。"}, {"text": "风对帆船形成了一头阻力。", "explanation": "这里量词用错。阻力应用〈股〉，〈头〉用于牛、猪等动物，不能用来数阻力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77e535a1-3d00-41a4-8a35-d6188aee7aa7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23986, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "水流对船体产生了一只阻力。", "corrected_sentence": "水流对船体产生了一股阻力。", "error_description": "错误：「阻力」的量词应用「股」，不能用「只」（只多用于动物或成对物品中的一个）。应说「一股阻力」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77e535a1-3d00-41a4-8a35-d6188aee7aa7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23986, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "车子开起来后，阻力就变小着。", "corrected_sentence": "车子开起来后，阻力就变小了。", "error_description": "错误：「变小」表示已经发生的变化，要用「了」，不用「着」。应说「阻力就变小了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77e535a1-3d00-41a4-8a35-d6188aee7aa7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
