INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23994, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "使物体运动或改变运动状态的力。", "primary_collocate": null, "pronunciation": "lì liang", "ipa": "li˥˩ liaŋ", "syllable_count": 2, "sentences": [{"text": "他的力量很大，一个人就能搬起桌子。", "target_word": "力量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台起重机的力量很大，能吊起一辆汽车。", "target_word": "力量", "complexity_tier": "T3", "furigana": "lìliang", "sentence_source": "generated"}, {"text": "大风的力量很大，把树吹倒了。", "target_word": "力量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水的力量可以推动水车。", "target_word": "力量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台机器有很大的力量，能拉动火车。", "target_word": "力量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海浪的力量很大，小船一直在动。", "target_word": "力量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "磁铁的力量能把铁钉吸过来。", "target_word": "力量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小小的蚂蚁也有力量，能搬动比自己大的东西。", "target_word": "力量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只有一个人的力量不够，我们一起推吧。", "target_word": "力量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台发动机的力量很大，能带动整个机器。", "target_word": "力量", "complexity_tier": "T3", "furigana": "lìliang", "sentence_source": "generated"}], "morphological_forms": [{"form": "一股力量", "label": "量词"}, {"form": "一种力量", "label": "量词"}, {"form": "力量感", "label": "复合"}], "register": "中性", "sense_fingerprint": "能使物体运动或改变的力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b46a45-2baa-4fa4-b1e2-7adacd8bb984') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23994, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "力量", "is_correct": true, "explanation": "正确。lì liang，指能使物体运动或改变的力。"}, {"text": "质量", "is_correct": false, "explanation": "zhì 与 lì 声母不同（zh / l），意思是事物的好坏程度，不是作用力。"}, {"text": "技量", "is_correct": false, "explanation": "jì 与 lì 声母不同（j / l），意思是技艺水平，不是作用力。"}, {"text": "体量", "is_correct": false, "explanation": "tǐ 与 lì 声母及声调都不同，意思是体积或规模，不是作用力。"}], "explanations": {"力量": "正确。lì liang，指能使物体运动或改变的力。", "质量": "zhì 与 lì 声母不同（zh / l），意思是事物的好坏程度，不是作用力。", "技量": "jì 与 lì 声母不同（j / l），意思是技艺水平，不是作用力。", "体量": "tǐ 与 lì 声母及声调都不同，意思是体积或规模，不是作用力。"}, "sentence_index": null, "correct_answer": "力量"}, "level_3": {"options": [{"text": "力量", "is_correct": true, "explanation": "正确。力量指人的体力，这里说一个人能搬起桌子。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不能用来搬起桌子。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄指岁数，不能用来搬起桌子。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“身高”一般说“高”，不说“很大”，也不能表示搬东西的能力。"}], "explanations": {"力量": "正确。力量指人的体力，这里说一个人能搬起桌子。", "颜色": "语义：颜色不能用来搬起桌子。", "年龄": "语义：年龄指岁数，不能用来搬起桌子。", "身高": "搭配：“身高”一般说“高”，不说“很大”，也不能表示搬东西的能力。"}, "sentence_index": 0, "correct_answer": "力量"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这箱书的力量很大，两个人才能抬动。", "explanation": "这里应该用〈重量〉。“力量”指作用力，说物体的轻重要用“重量”。"}, {"text": "这匹马的力量很快，一个小时能跑十公里。", "explanation": "这里应该用〈速度〉。“力量”指使东西动起来的作用，不能用“快”来形容；马跑得快要说“速度”。"}, {"text": "这台机器有一把很大的力量，能拉动火车。", "explanation": "这里应该用〈股〉。“把”用于有柄的器具，力量应说“一股”或“一种”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd65afb6c-6dd9-4e04-86e5-d2c2067f175e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23994, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "力量", "is_correct": true, "explanation": "正确。力量指使物体运动的作用力，磁铁能把铁钉吸过来。"}, {"text": "温度", "is_correct": false, "explanation": "语义：温度不能把铁钉吸过来。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“味道”不能与“吸过来”搭配。"}, {"text": "音量", "is_correct": false, "explanation": "语义：音量指声音大小，不能把铁钉吸过来。"}], "explanations": {"力量": "正确。力量指使物体运动的作用力，磁铁能把铁钉吸过来。", "温度": "语义：温度不能把铁钉吸过来。", "味道": "搭配：“味道”不能与“吸过来”搭配。", "音量": "语义：音量指声音大小，不能把铁钉吸过来。"}, "sentence_index": 6, "correct_answer": "力量"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次任务的力量很快，团队三天就完成了。", "explanation": "这里应该用〈进度〉。「力量」指作用力，不能用「快」来形容任务的完成情况；进展快慢要说「进度」。"}, {"text": "这壶水的力量很高，烧开只要五分钟。", "explanation": "这里应该用〈温度〉。“力量”指作用力，不能用“高”来形容水的冷热；水的冷热要说“温度”。"}, {"text": "这头牛有一根很大的力量，能拉动一辆车。", "explanation": "这里应该用〈股〉。“根”用于细长的东西，力量应说“一股”或“一种”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd65afb6c-6dd9-4e04-86e5-d2c2067f175e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23994, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台吊车有一只很大的力量，能把货物吊起来。", "corrected_sentence": "这台吊车有一股很大的力量，能把货物吊起来。", "error_description": "量词错误：“力量”应搭配“股”或“种”，“只”用于动物或成对的东西，不能修饰力量。正确说法是“一股很大的力量”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd65afb6c-6dd9-4e04-86e5-d2c2067f175e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23994, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "海风有一条很大的力量，能把船吹向岸边。", "corrected_sentence": "海风有一股很大的力量，能把船吹向岸边。", "error_description": "量词错误：“力量”应搭配“股”或“种”，“条”用于细长或条状的东西，不能修饰力量。正确说法是“一股很大的力量”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd65afb6c-6dd9-4e04-86e5-d2c2067f175e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23996, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "轻松", "is_correct": true, "explanation": "反义：「用力」指费很大力气，「轻松」指做事不费力，二者相对。"}, {"text": "睡觉", "is_correct": false, "explanation": "与「用力」无反义关系，二者不构成对立。"}, {"text": "画画", "is_correct": false, "explanation": "与「用力」无反义关系，二者不构成对立。"}, {"text": "唱歌", "is_correct": false, "explanation": "与「用力」无反义关系，二者不构成对立。"}], "correct_answer": "轻松", "explanations": {"轻松": "反义：「用力」指费很大力气，「轻松」指做事不费力，二者相对。", "睡觉": "与「用力」无反义关系，二者不构成对立。", "画画": "与「用力」无反义关系，二者不构成对立。", "唱歌": "与「用力」无反义关系，二者不构成对立。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1868310-7d36-4fb0-bf71-06d69048f60c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23996, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "放手", "is_correct": true, "explanation": "反义：「用力拉」指施力，「放手」指松开不再施力，二者相对。"}, {"text": "下棋", "is_correct": false, "explanation": "与「用力」无反义关系，二者不构成对立。"}, {"text": "看电影", "is_correct": false, "explanation": "与「用力」无反义关系，二者不构成对立。"}, {"text": "弹琴", "is_correct": false, "explanation": "与「用力」无反义关系，二者不构成对立。"}], "correct_answer": "放手", "explanations": {"放手": "反义：「用力拉」指施力，「放手」指松开不再施力，二者相对。", "下棋": "与「用力」无反义关系，二者不构成对立。", "看电影": "与「用力」无反义关系，二者不构成对立。", "弹琴": "与「用力」无反义关系，二者不构成对立。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1868310-7d36-4fb0-bf71-06d69048f60c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23996, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用很多力气做事情。", "primary_collocate": null, "pronunciation": "yòng lì", "ipa": "jʊŋ˥˩ li˥˩", "syllable_count": 2, "sentences": [{"text": "他用力搬起了那个大箱子。", "target_word": "用力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你用力一点，才能把钉子打进去。", "target_word": "用力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用力擦着窗户上的灰。", "target_word": "用力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们用力喊：“加油！”", "target_word": "用力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用力握住我的手，不想放开。", "target_word": "用力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我用力关上门，声音很大。", "target_word": "用力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈用力揉着面，要做很多饺子。", "target_word": "用力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请用力按这个红色的按钮。", "target_word": "用力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用力把石头扔到了河对面。", "target_word": "用力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "拔河的时候，大家都在用力拉绳子。", "target_word": "用力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "用了力", "label": "体标"}, {"form": "用过力", "label": "体标"}, {"form": "用力地", "label": "状语形式"}], "register": "中性", "sense_fingerprint": "人花很大力气去做某件事（搬、拉、按、喊等）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2efa2384-c1dd-4c37-a182-92a2f89de8d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23996, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "用力", "is_correct": true, "explanation": "正确。「用力」读作 yòng lì，指用很大力气做事。"}, {"text": "运力", "is_correct": false, "explanation": "韵尾不同：「运力」第一音节为 yùn（n 韵尾），「用力」为 yòng（ng 韵尾），意思是运输能力。"}, {"text": "样例", "is_correct": false, "explanation": "韵母不同：「样」为 yàng，「用」为 yòng，两者只差一个元音，意思是样例。"}, {"text": "勇力", "is_correct": false, "explanation": "声调不同：「勇」为第三声 yǒng，「用」为第四声 yòng，意思是勇敢有力。"}], "explanations": {"用力": "正确。「用力」读作 yòng lì，指用很大力气做事。", "运力": "韵尾不同：「运力」第一音节为 yùn（n 韵尾），「用力」为 yòng（ng 韵尾），意思是运输能力。", "样例": "韵母不同：「样」为 yàng，「用」为 yòng，两者只差一个元音，意思是样例。", "勇力": "声调不同：「勇」为第三声 yǒng，「用」为第四声 yòng，意思是勇敢有力。"}, "sentence_index": null, "correct_answer": "用力"}, "level_3": {"options": [{"text": "用力", "is_correct": true, "explanation": "正确。「用力」修饰「搬起」，表示用很大力气搬起重箱子。"}, {"text": "轻飘飘地", "is_correct": false, "explanation": "语义：「轻飘飘」形容东西很轻，与「大箱子」的分量明显矛盾，句意不通。"}, {"text": "温柔地", "is_correct": false, "explanation": "搭配：「温柔地」形容态度，不能修饰「搬起」这种有力的动作。"}, {"text": "懒洋洋地", "is_correct": false, "explanation": "语义：「懒洋洋地」表示没有力气，与搬起大箱子的语境矛盾。"}], "explanations": {"用力": "正确。「用力」修饰「搬起」，表示用很大力气搬起重箱子。", "轻飘飘地": "语义：「轻飘飘」形容东西很轻，与「大箱子」的分量明显矛盾，句意不通。", "温柔地": "搭配：「温柔地」形容态度，不能修饰「搬起」这种有力的动作。", "懒洋洋地": "语义：「懒洋洋地」表示没有力气，与搬起大箱子的语境矛盾。"}, "sentence_index": 0, "correct_answer": "用力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她用力地知道了这个消息。", "explanation": "这里应该用〈得知〉。用力指使出身体的力气，知道消息不靠力气，应说〈得知〉。"}, {"text": "她用力地梦见了一只猫。", "explanation": "这里不应使用〈用力〉。用力指使出身体的力气，梦境是睡眠中的感受，不能用力去梦见。"}, {"text": "她用力地同意了这个计划。", "explanation": "这里应该用〈赞同〉。用力指使出力气，表态赞同不靠力气，应说〈赞同〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1868310-7d36-4fb0-bf71-06d69048f60c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23996, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "用力", "is_correct": true, "explanation": "正确。「用力」修饰「揉」，表示使劲揉面。"}, {"text": "呆呆地", "is_correct": false, "explanation": "语义：「呆呆地」指发愣的样子，与「要做很多饺子」的忙碌语境不符。"}, {"text": "悠闲地", "is_correct": false, "explanation": "语义：「悠闲地」表示不着急，与「要做很多饺子」的语境相矛盾。"}, {"text": "发呆", "is_correct": false, "explanation": "搭配：「发呆」是不及物的状态，不能作「揉着面」的修饰成分。"}], "explanations": {"用力": "正确。「用力」修饰「揉」，表示使劲揉面。", "呆呆地": "语义：「呆呆地」指发愣的样子，与「要做很多饺子」的忙碌语境不符。", "悠闲地": "语义：「悠闲地」表示不着急，与「要做很多饺子」的语境相矛盾。", "发呆": "搭配：「发呆」是不及物的状态，不能作「揉着面」的修饰成分。"}, "sentence_index": 6, "correct_answer": "用力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用力地生了一场病。", "explanation": "这里不应使用〈用力〉。用力指使出身体的力气，生病是身体的状况，不靠用力，应说〈患病〉。"}, {"text": "他遇到难题时用力地消失了。", "explanation": "这里不应使用〈用力〉。用力指使出力气，消失是状态变化，不是用力做的事。"}, {"text": "她用力地喜欢上了一位画家。", "explanation": "这里不应使用〈用力〉。用力指使出力气，喜欢是情感，应说〈倾心〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1868310-7d36-4fb0-bf71-06d69048f60c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23996, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她用力得擦干净了桌子。", "corrected_sentence": "她用力地擦干净了桌子。", "error_description": "助词误用：修饰动词的状语后应用「地」，应说「用力地擦」，不能用「得」。「得」用于动词后引出补语，如「擦得干净」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1868310-7d36-4fb0-bf71-06d69048f60c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23996, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他用力了推开门。", "corrected_sentence": "他用了力推开门。", "error_description": "语序错误：「用」与「力」是动词加宾语，「了」应放在「用」后，应说「用了力」，不能说「用力了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1868310-7d36-4fb0-bf71-06d69048f60c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
