INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23998, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1868310-7d36-4fb0-bf71-06d69048f60c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23998, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "东西从上面落下来。", "primary_collocate": null, "pronunciation": "diào xià lái", "ipa": "tjɑʊ̯˥˩ ɕjɑ˥˩ laɪ̯˧˥", "syllable_count": 3, "sentences": [{"text": "天花板上的灯掉下来了。", "target_word": "掉下来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "桌子太小，杯子很容易掉下来。", "target_word": "掉下来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子睡觉时从床上掉下来了。", "target_word": "掉下来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "果子熟了，会自己掉下来。", "target_word": "掉下来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "楼上的花盆掉下来，砸坏了车。", "target_word": "掉下来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你坐稳，别从椅子上掉下来。", "target_word": "掉下来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大风一吹，树上的雪都掉下来了。", "target_word": "掉下来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书包没拉好，铅笔都掉下来了。", "target_word": "掉下来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "窗台上的花盆掉下来过，真危险。", "target_word": "掉下来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他爬到树上，不小心掉下来了。", "target_word": "掉下来", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "掉下来", "label": "基本形式"}, {"form": "掉下来了", "label": "完成体"}, {"form": "掉下来过", "label": "经历体"}, {"form": "掉下來", "label": "繁体"}], "register": "中性", "sense_fingerprint": "东西从上面落下，常指没拿稳或没固定好而落下", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2efa2384-c1dd-4c37-a182-92a2f89de8d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23998, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "飞起来", "is_correct": false, "explanation": "语义：灯没有飞行的能力，“天花板上的灯飞起来了”与灯从上面落下的语境不符。"}, {"text": "掉下来", "is_correct": true, "explanation": "正确：“天花板上的灯掉下来了”表示灯从上面落下，与词义一致。"}, {"text": "跑下来", "is_correct": false, "explanation": "搭配：“跑”用于人或动物的移动，灯不能“跑”。"}, {"text": "站起来", "is_correct": false, "explanation": "搭配：“站起来”指人或动物起身，不能用于描述天花板上的灯。"}], "explanations": {"飞起来": "语义：灯没有飞行的能力，“天花板上的灯飞起来了”与灯从上面落下的语境不符。", "掉下来": "正确：“天花板上的灯掉下来了”表示灯从上面落下，与词义一致。", "跑下来": "搭配：“跑”用于人或动物的移动，灯不能“跑”。", "站起来": "搭配：“站起来”指人或动物起身，不能用于描述天花板上的灯。"}, "sentence_index": 0, "correct_answer": "掉下来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他踩着凳子，把书包掉下来，交给了妹妹。", "explanation": "这里应该用〈拿下来〉。掉下来指无意中落下，不能用于人有意取下物品的动作。"}, {"text": "果子熟了，我爬上树，把它们掉下来。", "explanation": "这里应该用〈摘下来〉。掉下来指无意间落下，不能用于人有意采摘的动作。"}, {"text": "风筝从地面掉下来，慢慢飞上了天空。", "explanation": "〈掉下来〉只表示由高往低的移动，这里描述的是上升，方向前后矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1868310-7d36-4fb0-bf71-06d69048f60c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23998, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "停下来", "is_correct": false, "explanation": "语义：大风一吹，雪本会被吹落，“都停下来了”与风吹的结果相反。"}, {"text": "掉下来", "is_correct": true, "explanation": "正确：“大风一吹，树上的雪都掉下来了”表示雪被风吹落，与词义一致。"}, {"text": "坐下来", "is_correct": false, "explanation": "搭配：“坐下来”指人或动物坐下，雪不能“坐下来”。"}, {"text": "躺下来", "is_correct": false, "explanation": "搭配：“躺下来”指人或动物躺倒，不能用于描述树上的雪。"}], "explanations": {"停下来": "语义：大风一吹，雪本会被吹落，“都停下来了”与风吹的结果相反。", "掉下来": "正确：“大风一吹，树上的雪都掉下来了”表示雪被风吹落，与词义一致。", "坐下来": "搭配：“坐下来”指人或动物坐下，雪不能“坐下来”。", "躺下来": "搭配：“躺下来”指人或动物躺倒，不能用于描述树上的雪。"}, "sentence_index": 6, "correct_answer": "掉下来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把沉重的背包掉下来，靠在墙上休息。", "explanation": "这里应该用〈放下来〉。掉下来指无意落下，不能用于人主动放下东西的动作。"}, {"text": "他踩着凳子，故意把灯掉下来，然后换了一个新的。", "explanation": "这里应该用〈取下来〉。掉下来指无意落下，不能用于人有意去取下东西的动作。"}, {"text": "他从地上掉下来，爬到了树顶。", "explanation": "〈掉下来〉只表示由高往低的移动，这里描述的是从低处到高处，方向与词义相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1868310-7d36-4fb0-bf71-06d69048f60c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23998, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "窗台上的花盆没放稳，很容易被掉下来。", "corrected_sentence": "窗台上的花盆没放稳，很容易掉下来。", "error_description": "错误在于“掉下来”前加了“被”。“掉下来”是不及物动词，不能用于被动句，应直接说“很容易掉下来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1868310-7d36-4fb0-bf71-06d69048f60c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23998, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "窗户没关紧，风一吹，窗台上的纸都被掉下来了。", "corrected_sentence": "窗户没关紧，风一吹，窗台上的纸都掉下来了。", "error_description": "错误在于多加了“被”。“掉下来”是不及物动词，不能用于被动句，应说“纸都掉下来了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1868310-7d36-4fb0-bf71-06d69048f60c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
