INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24004, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ab1c25b-999f-44d7-8efd-44c987dcdbdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24004, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用脚快速向前移动。", "primary_collocate": null, "pronunciation": "pǎo", "ipa": "pʰɑʊ̯˨˩˦", "syllable_count": 1, "sentences": [{"text": "他跑得很快，第一个到了终点。", "target_word": "跑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小男孩从家里跑出来，大声叫妈妈。", "target_word": "跑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你跑什么？车还没来呢。", "target_word": "跑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一口气跑了三公里。", "target_word": "跑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫听到声音，很快跑走了。", "target_word": "跑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我今天跑得太快，肚子疼了。", "target_word": "跑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "马在草地上跑着，样子很好看。", "target_word": "跑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动员们站好了，听到声音就往前跑。", "target_word": "跑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看见大狗，小女孩吓得转身就跑。", "target_word": "跑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她跑过去，一把抱住了弟弟。", "target_word": "跑", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "跑了", "label": "体标"}, {"form": "跑着", "label": "体标"}, {"form": "跑过", "label": "体标"}, {"form": "跑跑", "label": "重叠"}], "register": "中性", "sense_fingerprint": "用脚快速向前移动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c22b99d-de53-433a-91c3-3cfd2942df23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24004, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "跑", "is_correct": true, "explanation": "跑（pǎo，第三声）：用脚快速向前移动，是本题的正确答案。"}, {"text": "泡", "is_correct": false, "explanation": "泡（pào，第四声）与 pǎo 声调不同，意思是把东西浸在水里。"}, {"text": "抛", "is_correct": false, "explanation": "抛（pāo，第一声）与 pǎo 声调不同，意思是把东西扔出去。"}, {"text": "饱", "is_correct": false, "explanation": "饱（bǎo，第三声）与 pǎo 声母不同（b 与 p），意思是吃足了。"}, {"text": "袍", "is_correct": false, "explanation": "袍（páo，第二声）与 pǎo 声调不同，意思是长衣服。"}], "explanations": {"跑": "跑（pǎo，第三声）：用脚快速向前移动，是本题的正确答案。", "泡": "泡（pào，第四声）与 pǎo 声调不同，意思是把东西浸在水里。", "抛": "抛（pāo，第一声）与 pǎo 声调不同，意思是把东西扔出去。", "饱": "饱（bǎo，第三声）与 pǎo 声母不同（b 与 p），意思是吃足了。", "袍": "袍（páo，第二声）与 pǎo 声调不同，意思是长衣服。"}, "sentence_index": null, "correct_answer": "跑"}, "level_3": {"options": [{"text": "跑", "is_correct": true, "explanation": "跑：“跑得很快”说明速度，“第一个到了终点”是比赛结果，两者相合。"}, {"text": "睡", "is_correct": false, "explanation": "语义：“睡得很快”指很快入睡，与“第一个到了终点”矛盾。"}, {"text": "哭", "is_correct": false, "explanation": "语义：哭得快与比赛到达终点无关，句子说不通。"}, {"text": "坐", "is_correct": false, "explanation": "搭配：“坐”没有快慢的说法，不能说“坐得很快”。"}], "explanations": {"跑": "跑：“跑得很快”说明速度，“第一个到了终点”是比赛结果，两者相合。", "睡": "语义：“睡得很快”指很快入睡，与“第一个到了终点”矛盾。", "哭": "语义：哭得快与比赛到达终点无关，句子说不通。", "坐": "搭配：“坐”没有快慢的说法，不能说“坐得很快”。"}, "sentence_index": 0, "correct_answer": "跑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在湖里跑了一公里，很快就上了岸。", "explanation": "这里应该用〈游〉。在水里移动要用游，跑指用脚在地面快速移动。"}, {"text": "风筝在天上跑过了山头。", "explanation": "这里应该用〈飞〉。风筝在空中移动要用飞，跑只用于用脚在地面快速移动。"}, {"text": "他把那张大桌子跑到了二楼。", "explanation": "这里应该用〈搬〉。搬桌子要用搬，跑只用于人或动物自己用脚快速移动，不能带“桌子”移动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ab1c25b-999f-44d7-8efd-44c987dcdbdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24004, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "跑", "is_correct": true, "explanation": "跑（pǎo，第三声）：用脚快速向前移动，是本题的正确答案。"}, {"text": "炮", "is_correct": false, "explanation": "炮（pào，第四声）与 pǎo 声调不同，意思是大炮。"}, {"text": "保", "is_correct": false, "explanation": "保（bǎo，第三声）与 pǎo 声母不同（b 与 p），意思是保护。"}, {"text": "刨", "is_correct": false, "explanation": "刨（páo，第二声）与 pǎo 声调不同，意思是用刀具削平或挖掘。"}], "explanations": {"跑": "跑（pǎo，第三声）：用脚快速向前移动，是本题的正确答案。", "炮": "炮（pào，第四声）与 pǎo 声调不同，意思是大炮。", "保": "保（bǎo，第三声）与 pǎo 声母不同（b 与 p），意思是保护。", "刨": "刨（páo，第二声）与 pǎo 声调不同，意思是用刀具削平或挖掘。"}, "sentence_index": null, "correct_answer": "跑"}, "level_3": {"options": [{"text": "跑", "is_correct": true, "explanation": "跑：马在草地上用脚奔跑，符合句意，样子好看。"}, {"text": "唱", "is_correct": false, "explanation": "语义：马不会唱歌，“唱着”与草地上的场景不符。"}, {"text": "游", "is_correct": false, "explanation": "语义：草地上没有水，马在草地上游，句子不成立。"}, {"text": "写", "is_correct": false, "explanation": "搭配：马不能写字，“写着”用来形容马，搭配不当。"}], "explanations": {"跑": "跑：马在草地上用脚奔跑，符合句意，样子好看。", "唱": "语义：马不会唱歌，“唱着”与草地上的场景不符。", "游": "语义：草地上没有水，马在草地上游，句子不成立。", "写": "搭配：马不能写字，“写着”用来形容马，搭配不当。"}, "sentence_index": 6, "correct_answer": "跑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在河上跑着，很快就到了对岸。", "explanation": "这里应该用〈划〉。靠桨在水上移动小船要用划，跑指用脚在地面快速移动。"}, {"text": "一只红气球跑过了操场，很快就到了天上。", "explanation": "这里应该用〈飘〉。气球没有脚，靠风移动要用飘，跑只用于人或动物用脚移动。"}, {"text": "他在台上跑了一首歌，大家都很喜欢。", "explanation": "这里应该用〈唱〉。唱歌要用唱，跑指用脚快速移动，不能表示演唱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ab1c25b-999f-44d7-8efd-44c987dcdbdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24004, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "队员们听到哨声，就跑了回场地。", "corrected_sentence": "队员们听到哨声，就跑回了场地。", "error_description": "趋向补语“回”后面才加“了”：应说“跑回了场地”，“跑了回”不对。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ab1c25b-999f-44d7-8efd-44c987dcdbdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24004, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他累跑了，坐在草地上休息。", "corrected_sentence": "他跑累了，坐在草地上休息。", "error_description": "结果补语“累”应放在动词后：应说“跑累了”，“累跑了”不对。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ab1c25b-999f-44d7-8efd-44c987dcdbdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
