INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24008, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "汽车、飞机等机器动起来的部分。", "primary_collocate": null, "pronunciation": "fā dòng jī", "ipa": "fa˥ tʊŋ˥˩ tɕi˥", "syllable_count": 3, "sentences": [{"text": "汽车的发动机在前面的车盖下面。", "target_word": "发动机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "发动机一响，汽车就开走了。", "target_word": "发动机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这艘船有两台大发动机。", "target_word": "发动机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机把发动机关了，下车休息。", "target_word": "发动机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "发动机太热了，要停一会儿。", "target_word": "发动机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "修车师傅说发动机有问题。", "target_word": "发动机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机的发动机在两边的机翼下。", "target_word": "发动机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想学怎么修发动机。", "target_word": "发动机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新发动机比旧的安静多了。", "target_word": "发动机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小汽车的发动机比卡车的小。", "target_word": "发动机", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "台", "label": "量词"}, {"form": "柴油发动机", "label": "复合"}, {"form": "汽油发动机", "label": "复合"}, {"form": "發動機", "label": "繁体"}], "register": "通用", "sense_fingerprint": "汽车飞机等机器上让它动起来的部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27b79c64-687c-41da-88a3-fa2136641a60') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24008, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "发动机", "is_correct": true, "explanation": "发动机装在汽车前部的引擎舱里，车盖下面正是它的位置。"}, {"text": "轮胎", "is_correct": false, "explanation": "语义：轮胎装在车轮上，不在车盖下面。"}, {"text": "座椅", "is_correct": false, "explanation": "语义：座椅在车厢里，不在车头的车盖下面。"}, {"text": "后备箱", "is_correct": false, "explanation": "搭配：“后备箱”在车尾，不能和“前面的车盖下面”搭配。"}], "explanations": {"发动机": "发动机装在汽车前部的引擎舱里，车盖下面正是它的位置。", "轮胎": "语义：轮胎装在车轮上，不在车盖下面。", "座椅": "语义：座椅在车厢里，不在车头的车盖下面。", "后备箱": "搭配：“后备箱”在车尾，不能和“前面的车盖下面”搭配。"}, "sentence_index": 0, "correct_answer": "发动机"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这款游戏的发动机很强，玩家都喜欢。", "explanation": "这里应该用〈引擎〉。“游戏引擎”是固定说法，发动机指汽车、飞机等实体机器。"}, {"text": "这座小岛靠风力发动机发电。", "explanation": "这里应该用〈发电机〉。发动机把燃料能量变成机械动力，发电需要的是发电机。"}, {"text": "这台电风扇的发动机转得很慢。", "explanation": "这里应该用〈马达〉。电风扇等小型电器的动力部件叫马达，发动机指汽车、飞机等机器。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a604ca5-856b-4e8b-ac01-e8eb9932bbef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24008, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "发动机", "is_correct": true, "explanation": "发动机是飞机的动力部件，挂在两边的机翼下，符合句意。"}, {"text": "机舱", "is_correct": false, "explanation": "语义：机舱是机身中间载人的部分，不在机翼下面。"}, {"text": "尾翼", "is_correct": false, "explanation": "语义：尾翼在机身尾部，不在两边的机翼下面。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：窗户属于机身，不说“在两边的机翼下”。"}], "explanations": {"发动机": "发动机是飞机的动力部件，挂在两边的机翼下，符合句意。", "机舱": "语义：机舱是机身中间载人的部分，不在机翼下面。", "尾翼": "语义：尾翼在机身尾部，不在两边的机翼下面。", "窗户": "搭配：窗户属于机身，不说“在两边的机翼下”。"}, "sentence_index": 6, "correct_answer": "发动机"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台笔记本的发动机太吵了，影响工作。", "explanation": "这里应该用〈风扇〉。笔记本的噪音和散热主要来自风扇，发动机指汽车、飞机等机器，不用于笔记本。"}, {"text": "工人们决定发动机罢工，明天停工。", "explanation": "这里应该用〈发动〉。“发动罢工”中是动词“发动”，发动机是名词，不能代替动词。"}, {"text": "这台空调的发动机坏了，不制冷。", "explanation": "这里应该用〈压缩机〉。空调制冷靠压缩机，发动机指汽车、飞机等机器的动力部分，不用于空调。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a604ca5-856b-4e8b-ac01-e8eb9932bbef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24008, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "修车师傅换了一条新发动机。", "corrected_sentence": "修车师傅换了一台新发动机。", "error_description": "量词错误：“发动机”是机器，量词应用“台”。“条”只用于细长之物，不能用来数发动机。应改为“修车师傅换了一台新发动机。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a604ca5-856b-4e8b-ac01-e8eb9932bbef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24008, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把发动机修。", "corrected_sentence": "他把发动机修好了。", "error_description": "“把”字句的动词后须有补足成分（如结果补语“好”、动态助词“了”）。“他把发动机修”结构不完整，应说“他把发动机修好了。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a604ca5-856b-4e8b-ac01-e8eb9932bbef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
