INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24010, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ab1c25b-999f-44d7-8efd-44c987dcdbdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24010, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "风吹过来时，人能感觉到的一股流动的空气。", "primary_collocate": null, "pronunciation": "kōng qì liú", "ipa": "kʰʊŋ˥ tɕʰi˥˩ lioʊ̯˧˥", "syllable_count": 3, "sentences": [{"text": "打开门以后，我感到一股空气流。", "target_word": "空气流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风扇一开，就有空气流吹到脸上。", "target_word": "空气流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间里有空气流，所以蜡烛一直在动。", "target_word": "空气流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我站在窗边，能感觉到凉凉的空气流。", "target_word": "空气流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里有空气流，你不会觉得热。", "target_word": "空气流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地铁来的时候，会带来一阵空气流。", "target_word": "空气流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用手摸了摸，没有感觉到空气流。", "target_word": "空气流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "空气流太大，纸都被吹到了地上。", "target_word": "空气流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩用手挡着脸，不想让空气流吹进眼睛。", "target_word": "空气流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门缝里进来一点空气流，脚觉得很冷。", "target_word": "空气流", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "风吹来时能感觉到的气流", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c22b99d-de53-433a-91c3-3cfd2942df23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24010, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "空气流", "is_correct": true, "explanation": "正确：空气流指风吹来时感到的气流，“感到一股”与“打开门以后”的情境吻合。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“感到”的对象是可以感知的气流，颜色只能看见，不能被感到。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“一股”不修饰“声音”，声音一般用“听到”，不用“感到一股”。"}, {"text": "阴影", "is_correct": false, "explanation": "语义：阴影是光线被遮挡形成的暗处，不能被感到，也不能说“一股阴影”。"}], "explanations": {"空气流": "正确：空气流指风吹来时感到的气流，“感到一股”与“打开门以后”的情境吻合。", "颜色": "语义：“感到”的对象是可以感知的气流，颜色只能看见，不能被感到。", "声音": "搭配：“一股”不修饰“声音”，声音一般用“听到”，不用“感到一股”。", "阴影": "语义：阴影是光线被遮挡形成的暗处，不能被感到，也不能说“一股阴影”。"}, "sentence_index": 0, "correct_answer": "空气流"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "打开窗户，我闻到一股空气流。", "explanation": "这里应该用〈气味〉。空气流指空气的流动，能感到却闻不到；闻到的是气味。"}, {"text": "这座城市的空气流很干净。", "explanation": "这里应该用〈空气质量〉。空气流只指风吹过来的流动感，不表示清洁程度，不能用“干净”来形容。"}, {"text": "我在窗边感到一颗空气流。", "explanation": "这里应该用〈股〉。“颗”用于圆形小粒，空气流不是颗粒，不能用“颗”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ab1c25b-999f-44d7-8efd-44c987dcdbdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24010, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "空气流", "is_correct": true, "explanation": "正确：空气流可以用手感知，“没有感觉到”与“用手摸了摸”前后呼应。"}, {"text": "香味", "is_correct": false, "explanation": "搭配：“感觉到”不搭配“香味”，香味一般说“闻到”。"}, {"text": "色彩", "is_correct": false, "explanation": "语义：句中的动作是用手触摸，色彩不能被触摸。"}, {"text": "影子", "is_correct": false, "explanation": "语义：影子不能被手摸到，句中的动作是触摸，影子无法被触摸。"}], "explanations": {"空气流": "正确：空气流可以用手感知，“没有感觉到”与“用手摸了摸”前后呼应。", "香味": "搭配：“感觉到”不搭配“香味”，香味一般说“闻到”。", "色彩": "语义：句中的动作是用手触摸，色彩不能被触摸。", "影子": "语义：影子不能被手摸到，句中的动作是触摸，影子无法被触摸。"}, "sentence_index": 6, "correct_answer": "空气流"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个房间的空气流有二十度。", "explanation": "这里应该用〈温度〉。空气流指流动的气，不表示温度；说多少度要用“温度”。"}, {"text": "我用手把门外的一阵空气流捏成了一团。", "explanation": "空气流是流动的感觉，无法被手捏成一团，这里不能用“空气流”描述被握住的东西。"}, {"text": "地上有很多空气流。", "explanation": "这里应该用〈垃圾〉。空气流是流动的气，不能堆在地上；地上堆积的东西要说“垃圾”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ab1c25b-999f-44d7-8efd-44c987dcdbdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24010, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "窗户开着，有一只空气流进来。", "corrected_sentence": "窗户开着，有一阵空气流进来。", "error_description": "错误：“一只空气流”，量词“只”多用于动物等，不能用来计量空气流。正确：“一阵空气流”，量词“阵”表示一段时间内出现的气流，与空气流搭配。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ab1c25b-999f-44d7-8efd-44c987dcdbdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24010, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "风扇转得很快，空气流的很大。", "corrected_sentence": "风扇转得很快，空气流很大。", "error_description": "错误：“空气流的很大”，多加了“的”。正确：“空气流很大”，形容词作谓语时不加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ab1c25b-999f-44d7-8efd-44c987dcdbdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24016, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "进入", "is_correct": true, "explanation": "反义：进入指由外到内，与离开的“从某处走开”方向相反，是此义的反义词。"}, {"text": "写作", "is_correct": false, "explanation": "写作是创作文字，与离开没有反义关系。"}, {"text": "跳舞", "is_correct": false, "explanation": "跳舞是身体动作，与离开的动作不相对。"}, {"text": "检查", "is_correct": false, "explanation": "检查是查看核对，与离开没有反义关系。"}], "correct_answer": "进入", "explanations": {"进入": "反义：进入指由外到内，与离开的“从某处走开”方向相反，是此义的反义词。", "写作": "写作是创作文字，与离开没有反义关系。", "跳舞": "跳舞是身体动作，与离开的动作不相对。", "检查": "检查是查看核对，与离开没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3990624-4451-427e-a3e3-e64c06faf824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24016, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "留下", "is_correct": true, "explanation": "反义：留下指不再离去、继续停在原处，与离开的“走开”相对。"}, {"text": "种植", "is_correct": false, "explanation": "种植是栽种植物，与离开没有反义关系。"}, {"text": "吃饭", "is_correct": false, "explanation": "吃饭是进食，与离开的动作不相对。"}, {"text": "打扫", "is_correct": false, "explanation": "打扫是清理，与离开没有反义关系。"}], "correct_answer": "留下", "explanations": {"留下": "反义：留下指不再离去、继续停在原处，与离开的“走开”相对。", "种植": "种植是栽种植物，与离开没有反义关系。", "吃饭": "吃饭是进食，与离开的动作不相对。", "打扫": "打扫是清理，与离开没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3990624-4451-427e-a3e3-e64c06faf824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24016, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "一个人从一个地方走掉，不再待在那里。", "primary_collocate": null, "pronunciation": "lí kāi", "ipa": "li˧˥ kʰaɪ˥", "syllable_count": 2, "sentences": [{"text": "他九点离开了学校。", "target_word": "离开", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请不要离开这里。", "target_word": "离开", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我下个月要离开这个城市。", "target_word": "离开", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈离开家去上班了。", "target_word": "离开", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们已经离开了饭店。", "target_word": "离开", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她离开教室，去了图书馆。", "target_word": "离开", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你什么时候离开北京？", "target_word": "离开", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小王离开公司后，去了南方。", "target_word": "离开", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "客人都离开了，房间很安静。", "target_word": "离开", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他从没离开过自己的家乡。", "target_word": "离开", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "离开了", "label": "体标（了）"}, {"form": "离开过", "label": "体标（过）"}], "register": "中性", "sense_fingerprint": "人从一个地方走掉不再待在那里", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93d46aa3-eeb1-4c0a-b496-7cdabfc5bb1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24016, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "离开", "is_correct": true, "explanation": "“离开”指人从学校走开，与“九点”这个时间搭配自然。"}, {"text": "毕业", "is_correct": false, "explanation": "配价：毕业要说“从学校毕业”，不能直接带学校作宾语。"}, {"text": "播种", "is_correct": false, "explanation": "语义：播种是把种子撒进土里，与离开学校无关，句意不成立。"}, {"text": "占领", "is_correct": false, "explanation": "搭配：占领多用于阵地、地盘，不用于人在学校里的时间。"}], "explanations": {"离开": "“离开”指人从学校走开，与“九点”这个时间搭配自然。", "毕业": "配价：毕业要说“从学校毕业”，不能直接带学校作宾语。", "播种": "语义：播种是把种子撒进土里，与离开学校无关，句意不成立。", "占领": "搭配：占领多用于阵地、地盘，不用于人在学校里的时间。"}, "sentence_index": 0, "correct_answer": "离开"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他终于离开了那支笔，把它插进了笔筒。", "explanation": "这里应该用〈放下〉。离开指人从某处走开，笔要说“放下”，不说“离开”。"}, {"text": "他终于离开了那副眼镜，看清了黑板。", "explanation": "这里应该用〈摘下〉。离开指人从某处走开，眼镜要说“摘下”，不说“离开”。"}, {"text": "他终于离开了那件外套，走进了屋子。", "explanation": "这里应该用〈脱下〉。离开指人从某处走开，外套要说“脱下”，不说“离开”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3990624-4451-427e-a3e3-e64c06faf824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24016, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "离开", "is_correct": true, "explanation": "“离开”指人从北京走开，正好回答“什么时候”的问题。"}, {"text": "出生", "is_correct": false, "explanation": "配价：出生要说“出生在北京”，不能直接带北京作宾语。"}, {"text": "散步", "is_correct": false, "explanation": "语义：散步指悠闲地走，与“什么时候离开北京”的意思不符。"}, {"text": "打扮", "is_correct": false, "explanation": "语义：打扮指装饰外表，与北京无法构成离去的意思。"}], "explanations": {"离开": "“离开”指人从北京走开，正好回答“什么时候”的问题。", "出生": "配价：出生要说“出生在北京”，不能直接带北京作宾语。", "散步": "语义：散步指悠闲地走，与“什么时候离开北京”的意思不符。", "打扮": "语义：打扮指装饰外表，与北京无法构成离去的意思。"}, "sentence_index": 6, "correct_answer": "离开"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他终于离开了那双鞋，光着脚走进了屋子。", "explanation": "这里应该用〈脱下〉。离开指人从某处走开，鞋要说“脱下”，不说“离开”。"}, {"text": "她终于离开了那把剪刀，开始包饺子。", "explanation": "这里应该用〈放下〉。离开指人从某处走开，剪刀要说“放下”，不说“离开”。"}, {"text": "他终于离开了那本书，开始做饭。", "explanation": "这里应该用〈放下〉。离开指人从某处走开，书要说“放下”，不说“离开”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3990624-4451-427e-a3e3-e64c06faf824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24016, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "爸爸向车站离开，去了外地。", "corrected_sentence": "爸爸从车站离开，去了外地。", "error_description": "“向”表示朝向，不能引出离开的起点，应说“从车站离开”，不说“向车站离开”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3990624-4451-427e-a3e3-e64c06faf824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24016, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们从来没离开了这个岛。", "corrected_sentence": "我们从来没离开过这个岛。", "error_description": "“从来没”后面要用“过”表示经历，不能用“了”；正确应为“离开过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3990624-4451-427e-a3e3-e64c06faf824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
